export type AnimationType = 'pulse' | 'sweep' | 'neon' | 'focus' | 'underline';

export interface Selection {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface AnimationSettings {
  type: AnimationType;
  color: string;
  intensity: number; // 0 to 1
  speed: number; // Multiplier
  delay: number; // Seconds
  duration: number; // Seconds (video length)
  backgroundDim: number; // 0 to 1
}

export interface VideoExportOptions {
  width: number;
  height: number;
  fps: number;
}

import { AnimationType, AnimationSettings } from './types';
import { MousePointer2, Zap, Monitor, Sun, PenTool } from 'lucide-react';

export const DEFAULT_SETTINGS: AnimationSettings = {
  type: 'pulse',
  color: '#EF4444', // Tailwind red-500
  intensity: 0.8,
  speed: 1.5,
  delay: 0.5,
  duration: 4,
  backgroundDim: 0.6,
};

export const ANIMATION_TYPES: { id: AnimationType; label: string; icon: any; description: string }[] = [
  { id: 'pulse', label: 'Glow Pulse', icon: Sun, description: 'Soft pulsating glow effect' },
  { id: 'sweep', label: 'Sweep', icon: Zap, description: 'Directional shine moving across' },
  { id: 'neon', label: 'Neon Box', icon: Monitor, description: 'Bright, sharp outline' },
  { id: 'focus', label: 'Spotlight', icon: MousePointer2, description: 'Darken background, focus on target' },
  { id: 'underline', label: 'Marker', icon: PenTool, description: 'Hand-drawn style underline' },
];

export const RESOLUTION_PRESETS = [
  { label: 'Original', value: 'original' },
  { label: '1080p (16:9)', value: { w: 1920, h: 1080 } },
  { label: 'Portrait (9:16)', value: { w: 1080, h: 1920 } },
  { label: 'Square (1:1)', value: { w: 1080, h: 1080 } },
];

import { AnimationSettings, Selection } from '../types';

/**
 * Main render function used by both the preview loop and the export recorder.
 */
export const renderFrame = (
  ctx: CanvasRenderingContext2D,
  image: HTMLImageElement,
  selection: Selection | null,
  settings: AnimationSettings,
  timestamp: number, // current time in ms
  totalDurationMs: number
) => {
  const { width, height } = ctx.canvas;

  // 1. Clear & Draw Base Image
  ctx.clearRect(0, 0, width, height);
  ctx.drawImage(image, 0, 0, width, height);

  // If no selection, just show image
  if (!selection) return;

  // Calculate Relative Time for Animation
  const delayMs = settings.delay * 1000;
  const activeTime = timestamp - delayMs;
  const isStarted = activeTime > 0;

  // 2. Draw Background Dimming
  // We draw a semi-transparent black layer over everything...
  if (settings.backgroundDim > 0) {
    ctx.fillStyle = `rgba(0, 0, 0, ${settings.backgroundDim})`;
    ctx.beginPath();
    // ... but we cut out the selection hole so the original image shows through clearly
    // Outer rectangle (canvas)
    ctx.rect(0, 0, width, height);
    // Inner rectangle (selection) - wound counter-clockwise to create hole
    ctx.rect(
      selection.x + selection.width,
      selection.y,
      -selection.width,
      selection.height
    );
    ctx.fill();
  }

  if (!isStarted) return;

  // 3. Draw Highlights/Animations
  ctx.save();

  // Set clipping region to selection (default for most effects)
  // For 'neon' or 'underline', we might draw outside, so we handle clip differently inside switch

  const cycle = (activeTime / 1000) * settings.speed;

  switch (settings.type) {
    case 'pulse': {
      // Oscillate alpha between 0.2 and settings.intensity
      const alpha = 0.2 + (Math.sin(cycle * Math.PI) + 1) / 2 * (settings.intensity - 0.2);

      ctx.globalCompositeOperation = 'overlay'; // Blend mode for nice glow
      ctx.fillStyle = settings.color;
      ctx.globalAlpha = alpha;
      ctx.fillRect(selection.x, selection.y, selection.width, selection.height);

      // Add a stroke for definition
      ctx.globalCompositeOperation = 'source-over';
      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 4;
      ctx.globalAlpha = alpha * 0.8;
      ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
      break;
    }

    case 'sweep': {
      // Moving gradient
      ctx.beginPath();
      ctx.rect(selection.x, selection.y, selection.width, selection.height);
      ctx.clip();

      const gradientWidth = selection.width * 0.5;
      const totalDist = selection.width + gradientWidth * 2;
      const progress = (cycle % 2); // 0 to 2 range to allow pause/reset if needed
      const xPos = selection.x - gradientWidth + (progress * totalDist);

      // Create gradient
      const grad = ctx.createLinearGradient(xPos, selection.y, xPos + gradientWidth, selection.y);
      grad.addColorStop(0, 'rgba(255,255,255,0)');
      grad.addColorStop(0.5, settings.color);
      grad.addColorStop(1, 'rgba(255,255,255,0)');

      ctx.fillStyle = grad;
      ctx.globalCompositeOperation = 'screen';
      ctx.globalAlpha = settings.intensity;
      ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
      break;
    }

    case 'neon': {
      const pulseIntensity = 0.8 + (Math.sin(cycle * Math.PI * 2) * 0.2);

      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 6;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.shadowBlur = 20 * settings.intensity;
      ctx.shadowColor = settings.color;
      ctx.globalAlpha = pulseIntensity;

      ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);

      // Inner white core for neon effect
      ctx.strokeStyle = 'white';
      ctx.lineWidth = 2;
      ctx.shadowBlur = 0;
      ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
      break;
    }

    case 'underline': {
        const lineY = selection.y + selection.height + 10;
        const progress = Math.min(1, cycle); // Draw once then stop (or loop)
        const activeProgress = progress > 1 ? 1 : progress; 

        ctx.beginPath();
        ctx.strokeStyle = settings.color;
        ctx.lineWidth = 8;
        ctx.lineCap = 'round';

        // Simple easing for handwriting feel
        const currentWidth = selection.width * activeProgress;

        ctx.moveTo(selection.x, lineY);
        // Add a slight curve
        ctx.quadraticCurveTo(
            selection.x + currentWidth / 2, 
            lineY + 5, 
            selection.x + currentWidth, 
            lineY
        );
        ctx.stroke();
        break;
    }

    case 'focus': {
       // Focus is mostly handled by backgroundDim, but we add a subtle scale/grow effect to the selection
       // Actually, let's just draw a border
       ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
       ctx.lineWidth = 1;
       ctx.setLineDash([5, 5]);
       ctx.strokeRect(selection.x - 5, selection.y - 5, selection.width + 10, selection.height + 10);
       break;
    }
  }

  ctx.restore();
};

import { useState, useRef, useCallback } from 'react';
import { renderFrame } from '../utils/drawing';
import { AnimationSettings, Selection } from '../types';

export const useCanvasRecorder = () => {
  const [isRecording, setIsRecording] = useState(false);
  const [progress, setProgress] = useState(0);

  const exportVideo = useCallback(async (
    sourceCanvas: HTMLCanvasElement,
    image: HTMLImageElement,
    selection: Selection,
    settings: AnimationSettings
  ) => {
    return new Promise<void>((resolve, reject) => {
      setIsRecording(true);
      setProgress(0);

      // Create an offscreen canvas for rendering at full resolution
      const canvas = document.createElement('canvas');
      canvas.width = sourceCanvas.width;
      canvas.height = sourceCanvas.height;
      const ctx = canvas.getContext('2d');

      if (!ctx) {
        setIsRecording(false);
        reject(new Error("Could not create canvas context"));
        return;
      }

      // Setup MediaRecorder
      const stream = canvas.captureStream(30); // 30 FPS
      const mimeType = MediaRecorder.isTypeSupported('video/webm;codecs=vp9') 
        ? 'video/webm;codecs=vp9' 
        : 'video/webm';

      const recorder = new MediaRecorder(stream, {
        mimeType,
        videoBitsPerSecond: 5000000 // 5 Mbps
      });

      const chunks: Blob[] = [];
      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.push(e.data);
      };

      recorder.onstop = () => {
        const blob = new Blob(chunks, { type: 'video/webm' });
        const url = URL.createObjectURL(blob);

        // Trigger download
        const a = document.createElement('a');
        a.href = url;
        a.download = `highlight-${Date.now()}.webm`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);

        setIsRecording(false);
        resolve();
      };

      recorder.start();

      // Animation Loop logic purely for the recording
      const startTime = performance.now();
      const durationMs = settings.duration * 1000;

      const processFrame = (now: number) => {
        const elapsed = now - startTime;

        // Update progress
        setProgress(Math.min(100, Math.round((elapsed / durationMs) * 100)));

        renderFrame(ctx, image, selection, settings, elapsed, durationMs);

        if (elapsed < durationMs) {
          requestAnimationFrame(processFrame);
        } else {
          recorder.stop();
        }
      };

      requestAnimationFrame(processFrame);
    });
  }, []);

  return { isRecording, progress, exportVideo };
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Selection, AnimationSettings } from '../types';
import { renderFrame } from '../utils/drawing';

interface EditorCanvasProps {
  imageSrc: string;
  selection: Selection | null;
  setSelection: (sel: Selection | null) => void;
  settings: AnimationSettings;
  canvasRef: React.RefObject<HTMLCanvasElement>;
}

export const EditorCanvas: React.FC<EditorCanvasProps> = ({
  imageSrc,
  selection,
  setSelection,
  settings,
  canvasRef,
}) => {
  const [image, setImage] = useState<HTMLImageElement | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const isDragging = useRef(false);
  const startPos = useRef({ x: 0, y: 0 });
  const requestRef = useRef<number>();
  const startTimeRef = useRef<number>(performance.now());

  // Load Image
  useEffect(() => {
    if (!imageSrc) return;
    const img = new Image();
    img.src = imageSrc;
    img.onload = () => {
      setImage(img);
      // Reset selection when new image loads
      setSelection(null);
    };
  }, [imageSrc, setSelection]);

  // Animation Loop (Preview)
  const animate = useCallback((time: number) => {
    if (!canvasRef.current || !image) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    // Use loop relative time for preview
    const durationMs = settings.duration * 1000;
    const elapsed = (time - startTimeRef.current) % (durationMs + 1000); // Add 1s pause at end

    // Reset loop if passed duration
    if (elapsed > durationMs) {
        // Just showing static final frame or waiting
    }

    renderFrame(ctx, image, selection, settings, elapsed, durationMs);
    requestRef.current = requestAnimationFrame(animate);
  }, [image, selection, settings, canvasRef]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [animate]);

  // Initial Canvas Sizing
  useEffect(() => {
    if (image && canvasRef.current && containerRef.current) {
      // Fit canvas to container while maintaining aspect ratio
      const containerAspect = containerRef.current.clientWidth / containerRef.current.clientHeight;
      const imageAspect = image.width / image.height;

      // We actually want the canvas to be the full resolution of the image
      // Visual sizing is handled by CSS (max-w-full)
      canvasRef.current.width = image.width;
      canvasRef.current.height = image.height;
    }
  }, [image, canvasRef]);

  // Mouse Handlers for Selection
  const getCanvasCoordinates = (e: React.MouseEvent | React.TouchEvent) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const rect = canvasRef.current.getBoundingClientRect();
    const scaleX = canvasRef.current.width / rect.width;
    const scaleY = canvasRef.current.height / rect.height;

    const clientX = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : (e as React.MouseEvent).clientY;

    return {
      x: (clientX - rect.left) * scaleX,
      y: (clientY - rect.top) * scaleY,
    };
  };

  const handleMouseDown = (e: React.MouseEvent | React.TouchEvent) => {
    if (!image) return;
    isDragging.current = true;
    const { x, y } = getCanvasCoordinates(e);
    startPos.current = { x, y };
    setSelection({ x, y, width: 0, height: 0 });
  };

  const handleMouseMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDragging.current || !image) return;
    const { x, y } = getCanvasCoordinates(e);

    const width = x - startPos.current.x;
    const height = y - startPos.current.y;

    // Normalize rectangle (handle negative width/height)
    setSelection({
      x: width < 0 ? x : startPos.current.x,
      y: height < 0 ? y : startPos.current.y,
      width: Math.abs(width),
      height: Math.abs(height),
    });
  };

  const handleMouseUp = () => {
    isDragging.current = false;
    // Clear selection if too small (accidental click)
    if (selection && (selection.width < 10 || selection.height < 10)) {
        setSelection(null);
    }
    // Restart animation loop on release
    startTimeRef.current = performance.now();
  };

  return (
    <div 
      ref={containerRef} 
      className="relative w-full h-full flex items-center justify-center bg-zinc-900 overflow-hidden select-none cursor-crosshair touch-none"
    >
      {!image && (
         <div className="text-zinc-500 flex flex-col items-center">
            <p>Upload an image to start</p>
         </div>
      )}
      <canvas
        ref={canvasRef}
        className="max-w-full max-h-full shadow-2xl"
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onTouchStart={handleMouseDown}
        onTouchMove={handleMouseMove}
        onTouchEnd={handleMouseUp}
      />
    </div>
  );
};

import React from 'react';
import { AnimationSettings } from '../types';
import { ANIMATION_TYPES } from '../constants';
import { Sliders, Clock, Palette, Eye } from 'lucide-react';

interface ControlsProps {
  settings: AnimationSettings;
  updateSettings: (partial: Partial<AnimationSettings>) => void;
  onExport: () => void;
  isRecording: boolean;
  progress: number;
  hasSelection: boolean;
}

export const Controls: React.FC<ControlsProps> = ({
  settings,
  updateSettings,
  onExport,
  isRecording,
  progress,
  hasSelection
}) => {
  return (
    <div className="w-full lg:w-96 bg-zinc-800 border-l border-zinc-700 flex flex-col h-[40vh] lg:h-full overflow-y-auto">
      <div className="p-6 space-y-8">

        {/* Header */}
        <div>
          <h2 className="text-xl font-bold text-white mb-1">Configuration</h2>
          <p className="text-zinc-400 text-sm">Customize your highlight effect.</p>
        </div>

        {/* Animation Types */}
        <div className="space-y-3">
          <label className="text-xs font-semibold uppercase tracking-wider text-zinc-500 flex items-center gap-2">
            <Eye size={14} /> Animation Style
          </label>
          <div className="grid grid-cols-2 gap-2">
            {ANIMATION_TYPES.map((type) => {
              const Icon = type.icon;
              const isSelected = settings.type === type.id;
              return (
                <button
                  key={type.id}
                  onClick={() => updateSettings({ type: type.id })}
                  className={`flex flex-col items-center p-3 rounded-xl border transition-all ${
                    isSelected
                      ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg shadow-indigo-900/50'
                      : 'bg-zinc-700/50 border-zinc-600 text-zinc-300 hover:bg-zinc-700 hover:border-zinc-500'
                  }`}
                >
                  <Icon size={24} className="mb-2" />
                  <span className="text-xs font-medium">{type.label}</span>
                </button>
              );
            })}
          </div>
        </div>

        {/* Appearance Controls */}
        <div className="space-y-4">
          <label className="text-xs font-semibold uppercase tracking-wider text-zinc-500 flex items-center gap-2">
            <Palette size={14} /> Appearance
          </label>

          <div className="flex items-center gap-4">
            <input
              type="color"
              value={settings.color}
              onChange={(e) => updateSettings({ color: e.target.value })}
              className="w-12 h-12 rounded cursor-pointer bg-transparent border-none"
            />
            <div className="flex-1">
              <label className="text-xs text-zinc-400 block mb-1">Intensity</label>
              <input
                type="range"
                min="0"
                max="1"
                step="0.1"
                value={settings.intensity}
                onChange={(e) => updateSettings({ intensity: parseFloat(e.target.value) })}
                className="w-full accent-indigo-500 h-2 bg-zinc-700 rounded-lg appearance-none cursor-pointer"
              />
            </div>
          </div>

           <div>
              <label className="text-xs text-zinc-400 block mb-1">Background Dim</label>
              <input
                type="range"
                min="0"
                max="0.9"
                step="0.1"
                value={settings.backgroundDim}
                onChange={(e) => updateSettings({ backgroundDim: parseFloat(e.target.value) })}
                className="w-full accent-indigo-500 h-2 bg-zinc-700 rounded-lg appearance-none cursor-pointer"
              />
            </div>
        </div>

        {/* Timing Controls */}
        <div className="space-y-4">
           <label className="text-xs font-semibold uppercase tracking-wider text-zinc-500 flex items-center gap-2">
            <Clock size={14} /> Timing
          </label>

          <div className="grid grid-cols-2 gap-4">
             <div>
              <label className="text-xs text-zinc-400 block mb-1">Start Delay</label>
              <input
                type="number"
                min="0"
                max="5"
                step="0.1"
                value={settings.delay}
                onChange={(e) => updateSettings({ delay: parseFloat(e.target.value) })}
                className="w-full bg-zinc-900 border border-zinc-700 rounded px-2 py-1 text-white text-sm focus:border-indigo-500 focus:outline-none"
              />
            </div>
             <div>
              <label className="text-xs text-zinc-400 block mb-1">Duration (sec)</label>
              <input
                type="number"
                min="1"
                max="10"
                step="0.5"
                value={settings.duration}
                onChange={(e) => updateSettings({ duration: parseFloat(e.target.value) })}
                className="w-full bg-zinc-900 border border-zinc-700 rounded px-2 py-1 text-white text-sm focus:border-indigo-500 focus:outline-none"
              />
            </div>
          </div>
        </div>

      </div>

      {/* Export Button - Sticky Bottom */}
      <div className="mt-auto p-6 border-t border-zinc-700 bg-zinc-800 sticky bottom-0 z-10">
        <button
          onClick={onExport}
          disabled={!hasSelection || isRecording}
          className={`w-full py-3 rounded-lg font-bold text-lg transition-all flex items-center justify-center gap-2 ${
            !hasSelection
              ? 'bg-zinc-700 text-zinc-500 cursor-not-allowed'
              : isRecording
              ? 'bg-zinc-600 text-zinc-300 cursor-wait'
              : 'bg-indigo-600 hover:bg-indigo-500 text-white shadow-lg shadow-indigo-900/40'
          }`}
        >
          {isRecording ? `Exporting ${progress}%` : 'Export Video'}
        </button>
        {!hasSelection && (
            <p className="text-center text-xs text-zinc-500 mt-2">Draw a box on the image to start.</p>
        )}
      </div>
    </div>
  );
};

import React from 'react';
import { Upload, Video } from 'lucide-react';

interface TopBarProps {
  onImageUpload: (e: React.ChangeEvent<HTMLInputElement>) => void;
  fileName: string | null;
}

export const TopBar: React.FC<TopBarProps> = ({ onImageUpload, fileName }) => {
