import React, { useState, useRef, useCallback } from 'react';
import { TopBar } from './components/TopBar';
import { EditorCanvas } from './components/EditorCanvas';
import { Controls } from './components/Controls';
import { useCanvasRecorder } from './hooks/useCanvasRecorder';
import { AnimationSettings, Selection } from './types';
import { DEFAULT_SETTINGS } from './constants';

const App = () => {
  const [imageSrc, setImageSrc] = useState<string | null>(null);
  const [imageName, setImageName] = useState<string | null>(null);
  const [selection, setSelection] = useState<Selection | null>(null);
  const [settings, setSettings] = useState<AnimationSettings>(DEFAULT_SETTINGS);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const { isRecording, progress, exportVideo } = useCanvasRecorder();

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setImageName(file.name);
      const reader = new FileReader();
      reader.onload = (event) => {
        setImageSrc(event.target?.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const updateSettings = useCallback((partial: Partial<AnimationSettings>) => {
    setSettings(prev => ({ ...prev, ...partial }));
  }, []);

  const handleExport = async () => {
    if (!canvasRef.current || !imageSrc || !selection) return;

    // Load fresh image element for the exporter to ensure clean state
    const img = new Image();
    img.src = imageSrc;
    await img.decode(); // Wait for load

    try {
      await exportVideo(canvasRef.current, img, selection, settings);
    } catch (err) {
      console.error("Export failed", err);
      alert("Failed to export video. Please try again.");
    }
  };

  return (
    <div className="h-screen flex flex-col bg-zinc-950 text-white font-sans overflow-hidden">
      <TopBar onImageUpload={handleImageUpload} fileName={imageName} />

      <div className="flex-1 flex flex-col lg:flex-row overflow-hidden">
        {/* Main Workspace */}
        <div className="flex-1 relative bg-zinc-900 overflow-hidden flex flex-col">
          <div className="flex-1 relative">
             <EditorCanvas 
                imageSrc={imageSrc || ''}
                selection={selection}
                setSelection={setSelection}
                settings={settings}
                canvasRef={canvasRef}
             />
             {/* Instructions Overlay if empty */}
             {!imageSrc && (
                 <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                     <div className="bg-zinc-900/80 p-6 rounded-2xl border border-zinc-800 text-center max-w-md">
                         <h3 className="text-xl font-bold text-white mb-2">Welcome to Highlight Animator</h3>
                         <p className="text-zinc-400">Upload an image, drag to select an area, and export a cinematic highlight video.</p>
                     </div>
                 </div>
             )}
          </div>

          {/* Mobile bottom spacer if needed */}
        </div>

        {/* Sidebar Controls */}
        <Controls 
            settings={settings}
            updateSettings={updateSettings}
            onExport={handleExport}
            isRecording={isRecording}
            progress={progress}
            hasSelection={!!selection}
        />
      </div>
    </div>
  );
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
