    setSettings(prev => ({ ...prev, ...partial }));
  }, []);

  const handleExport = async () => {
    if (!canvasRef.current || !imageSrc || !selection) return;

    const img = new Image();
    img.src = imageSrc;
    await img.decode(); 

    try {
      await exportVideo(canvasRef.current, img, selection, settings);
    } catch (err) {
      console.error("Export failed", err);
      alert("Failed to export video. Please try again.");
    }
  };

  return (
    <div className="h-[100dvh] w-full flex flex-col lg:flex-row bg-zinc-950 text-white font-sans overflow-hidden">
      {/* Sidebar - Tools & Upload (Top on mobile, Left on Desktop) */}
      <Sidebar onImageUpload={handleImageUpload} onClearSelection={() => setSelection(null)} />

      {/* Center - Canvas Workspace */}
      <div className="flex-1 flex flex-col min-w-0 bg-zinc-900/50 relative order-2 lg:order-none overflow-hidden">
          <EditorCanvas 
            imageSrc={imageSrc || ''}
            selection={selection}
            setSelection={setSelection}
            settings={settings}
            canvasRef={canvasRef}
          />
      </div>

      {/* Right Sidebar - Properties (Bottom on mobile, Right on Desktop) */}
      <Controls 
          settings={settings}
          updateSettings={updateSettings}
          onExport={handleExport}
          onClearSelection={() => setSelection(null)}
          isRecording={isRecording}
          progress={progress}
          hasSelection={!!selection}
      />
    </div>
  );
};

