import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Selection, AnimationSettings } from '../types';
import { renderFrame } from '../utils/drawing';
import { Play } from 'lucide-react';

interface EditorCanvasProps {
  imageSrc: string;
  selection: Selection | null;
  setSelection: (sel: Selection | null) => void;
  settings: AnimationSettings;
  canvasRef: React.RefObject<HTMLCanvasElement>;
}

export const EditorCanvas: React.FC<EditorCanvasProps> = ({
  imageSrc,
  selection,
  setSelection,
  settings,
  canvasRef,
}) => {
  const [image, setImage] = useState<HTMLImageElement | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const isDragging = useRef(false);
  const startPos = useRef({ x: 0, y: 0 });
  const requestRef = useRef<number>();
  const startTimeRef = useRef<number>(performance.now());

  // Load Image
  useEffect(() => {
    if (!imageSrc) return;
    const img = new Image();
    img.src = imageSrc;
    img.onload = () => {
      setImage(img);
      setSelection(null);
    };
  }, [imageSrc, setSelection]);

  // Animation Loop (Preview)
  const animate = useCallback((time: number) => {
    if (!canvasRef.current || !image) return;
    const ctx = canvasRef.current.getContext('2d');
    if (!ctx) return;

    const durationMs = settings.duration * 1000;
    const elapsed = (time - startTimeRef.current) % (durationMs + 1000); 

    renderFrame(ctx, image, selection, settings, elapsed, durationMs);
    requestRef.current = requestAnimationFrame(animate);
  }, [image, selection, settings, canvasRef]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [animate]);

  // Canvas Sizing
  useEffect(() => {
    if (image && canvasRef.current && containerRef.current) {
      canvasRef.current.width = image.width;
      canvasRef.current.height = image.height;
    }
  }, [image, canvasRef]);

  // Mouse Handlers
  const getCanvasCoordinates = (e: React.MouseEvent | React.TouchEvent) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const rect = canvasRef.current.getBoundingClientRect();
    const scaleX = canvasRef.current.width / rect.width;
    const scaleY = canvasRef.current.height / rect.height;

    const clientX = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : (e as React.MouseEvent).clientY;

    return {
      x: (clientX - rect.left) * scaleX,
      y: (clientY - rect.top) * scaleY,
    };
  };

  const handleMouseDown = (e: React.MouseEvent | React.TouchEvent) => {
    if (!image) return;
    isDragging.current = true;
    const { x, y } = getCanvasCoordinates(e);
    startPos.current = { x, y };
    setSelection({ x, y, width: 0, height: 0 });
  };

  const handleMouseMove = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDragging.current || !image) return;
    const { x, y } = getCanvasCoordinates(e);

    const width = x - startPos.current.x;
    const height = y - startPos.current.y;

    setSelection({
      x: width < 0 ? x : startPos.current.x,
      y: height < 0 ? y : startPos.current.y,
      width: Math.abs(width),
      height: Math.abs(height),
    });
  };

  const handleMouseUp = () => {
    isDragging.current = false;
    if (selection && (selection.width < 10 || selection.height < 10)) {
        setSelection(null);
    }
    startTimeRef.current = performance.now();
  };

  return (
    <div 
      ref={containerRef} 
      className="relative w-full h-full flex items-center justify-center bg-zinc-900 overflow-hidden select-none p-4 lg:p-0"
    >
      {!image && (
         <div className="text-zinc-500 flex flex-col items-center animate-pulse">
            <p className="text-sm">Upload an image to start</p>
         </div>
      )}

      <div className="relative shadow-2xl shadow-black/50 max-w-full max-h-full flex justify-center items-center">
          <canvas
            ref={canvasRef}
            className={`max-w-full max-h-full block object-contain ${image ? 'cursor-crosshair' : ''}`}
            // Removed inline hardcoded max-dimensions to allow flex container to manage size on mobile
            style={{ maxHeight: '100%', maxWidth: '100%' }}
            onMouseDown={handleMouseDown}
            onMouseMove={handleMouseMove}
            onMouseUp={handleMouseUp}
            onMouseLeave={handleMouseUp}
            onTouchStart={handleMouseDown}
            onTouchMove={handleMouseMove}
            onTouchEnd={handleMouseUp}
          />

          {/* Preview Badge Overlay */}
          {image && selection && (
              <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex items-center gap-2 bg-zinc-900/80 backdrop-blur px-3 py-1.5 rounded-full border border-zinc-700 pointer-events-none">
                  <Play size={10} className="text-indigo-400 fill-indigo-400" />
                  <span className="text-[10px] font-medium text-zinc-300 uppercase tracking-wide">Preview</span>
              </div>
          )}
      </div>
    </div>
  );
};

import { AnimationSettings, Selection } from '../types';

/**
 * Main render function used by both the preview loop and the export recorder.
 */
export const renderFrame = (
  ctx: CanvasRenderingContext2D,
  image: HTMLImageElement,
  selection: Selection | null,
  settings: AnimationSettings,
  timestamp: number, // current time in ms
  totalDurationMs: number
) => {
  const { width, height } = ctx.canvas;

  // 1. Draw Base Image
  ctx.clearRect(0, 0, width, height);
  ctx.drawImage(image, 0, 0, width, height);

  // If no selection, just show image
  if (!selection) return;

  // Calculate Relative Time for Animation
  const delayMs = settings.delay * 1000;
  const activeTime = timestamp - delayMs;
  const isStarted = activeTime > 0;

  // 2. Draw Background Dimming & Vignette (With Hole Punching)
  // We use clipping to ensure the dim/vignette DOES NOT cover the highlighted area.
  ctx.save();
  ctx.beginPath();
  // Outer rect (Canvas)
  ctx.rect(0, 0, width, height);
  // Inner rect (Selection) - Used to create hole via evenodd rule
  ctx.rect(selection.x, selection.y, selection.width, selection.height);
  ctx.clip('evenodd');

  // Apply Background Dim
  if (settings.backgroundDim > 0) {
    ctx.fillStyle = `rgba(0, 0, 0, ${settings.backgroundDim})`;
    ctx.fillRect(0, 0, width, height);
  }

  // Apply Vignette
  if (settings.vignette > 0) {
    const gradient = ctx.createRadialGradient(
      width / 2, height / 2, width * 0.3, // inner circle
      width / 2, height / 2, Math.max(width, height) * 0.8 // outer circle
    );
    gradient.addColorStop(0, 'rgba(0,0,0,0)');
    gradient.addColorStop(1, `rgba(0,0,0,${settings.vignette})`);

    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, width, height);
  }
  ctx.restore();

  if (!isStarted) return;

  // 3. Draw Highlights/Animations
  ctx.save();
  const cycle = (activeTime / 1000) * settings.speed;

  switch (settings.type) {
    case 'pulse': {
      // Oscillate alpha between 0.1 and settings.intensity
      const alpha = 0.1 + (Math.sin(cycle * Math.PI) + 1) / 2 * (settings.intensity - 0.1);

      // Glow fill
      ctx.globalCompositeOperation = 'overlay';
      ctx.fillStyle = settings.color;
      ctx.globalAlpha = alpha;
      ctx.fillRect(selection.x, selection.y, selection.width, selection.height);

      // Border stroke
      ctx.globalCompositeOperation = 'source-over';
      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 4;
      ctx.globalAlpha = alpha;
      ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
      break;
    }

    case 'sweep': {
      // Create a clipping region for the sweep so it stays inside selection
      ctx.beginPath();
      ctx.rect(selection.x, selection.y, selection.width, selection.height);
      ctx.clip();

      const gradientWidth = selection.width * 0.5;
      const totalDist = selection.width + gradientWidth * 2;
      const progress = (cycle % 2); 
      const xPos = selection.x - gradientWidth + (progress * totalDist);

      const grad = ctx.createLinearGradient(xPos, selection.y, xPos + gradientWidth, selection.y);
      grad.addColorStop(0, 'rgba(255,255,255,0)');
      grad.addColorStop(0.5, settings.color);
      grad.addColorStop(1, 'rgba(255,255,255,0)');

      ctx.fillStyle = grad;
      ctx.globalCompositeOperation = 'screen'; // Screen blend mode for nice light effect
      ctx.globalAlpha = settings.intensity;
      ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
      break;
    }

    case 'neon': {
      const pulseIntensity = 0.8 + (Math.sin(cycle * Math.PI * 2) * 0.2);
      ctx.globalAlpha = pulseIntensity * settings.intensity;

      // Outer Glow
      ctx.shadowBlur = 20;
      ctx.shadowColor = settings.color;
      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 4;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);

      // Inner Core
      ctx.shadowBlur = 0;
      ctx.strokeStyle = 'white';
      ctx.lineWidth = 1;
      ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
      break;
    }

    case 'underline': {
        const lineY = selection.y + selection.height + 8;
        const progress = Math.min(1, cycle); 
        const activeProgress = progress > 1 ? 1 : progress; 

        ctx.beginPath();
        ctx.strokeStyle = settings.color;
        ctx.lineWidth = 6 * settings.intensity;
        ctx.lineCap = 'round';
        ctx.globalAlpha = 0.9;

        const currentWidth = selection.width * activeProgress;
        ctx.moveTo(selection.x, lineY);
        // Subtle curve for natural look
        ctx.quadraticCurveTo(
            selection.x + currentWidth / 2, 
            lineY + 3, 
            selection.x + currentWidth, 
            lineY
        );
        ctx.stroke();
        break;
    }

    case 'marker': {
      ctx.beginPath();
      ctx.rect(selection.x, selection.y, selection.width, selection.height);
      ctx.clip();

      const progress = Math.min(1, cycle); 
      const w = selection.width * progress;

      ctx.fillStyle = settings.color;
      // 'multiply' is best for highlighters on light backgrounds, but 'overlay' or 'source-over' is safer for dark/mixed.
      // We'll use source-over with low alpha for a generic "tint".
      ctx.globalCompositeOperation = 'source-over'; 
      ctx.globalAlpha = 0.5 * settings.intensity;

      ctx.fillRect(selection.x, selection.y, w, selection.height);
      break;
    }

    case 'fade': {
      const progress = Math.min(1, cycle);
      // Fade in a border focus
      ctx.globalAlpha = progress * settings.intensity;
      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 3;
      ctx.setLineDash([10, 6]);
      // Animate dash offset for "marching ants" feel or just static? Let's do static for "Fade"
      ctx.strokeRect(selection.x - 4, selection.y - 4, selection.width + 8, selection.height + 8);

      // Also slight fill
      ctx.fillStyle = settings.color;
      ctx.globalAlpha = progress * 0.1 * settings.intensity;
      ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
      break;
    }

    case 'focus': {
       // Static focus border
       ctx.strokeStyle = settings.color;
       ctx.lineWidth = 2;
       ctx.globalAlpha = settings.intensity;
       ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
       break;
    }
  }

  ctx.restore();
};

import { useState, useRef, useCallback } from 'react';
import { renderFrame } from '../utils/drawing';
import { AnimationSettings, Selection } from '../types';

export const useCanvasRecorder = () => {
  const [isRecording, setIsRecording] = useState(false);
  const [progress, setProgress] = useState(0);

  const exportVideo = useCallback(async (
    sourceCanvas: HTMLCanvasElement,
    image: HTMLImageElement,
    selection: Selection,
    settings: AnimationSettings
  ) => {
    return new Promise<void>((resolve, reject) => {
      setIsRecording(true);
      setProgress(0);

      const canvas = document.createElement('canvas');
      canvas.width = sourceCanvas.width;
      canvas.height = sourceCanvas.height;
      const ctx = canvas.getContext('2d');

      if (!ctx) {
        setIsRecording(false);
        reject(new Error("Could not create canvas context"));
        return;
      }

      // Determine supported MIME type
      const types = [
        'video/webm;codecs=vp9',
        'video/webm;codecs=h264',
        'video/webm',
        'video/mp4' // Safari support
      ];
      const mimeType = types.find(t => MediaRecorder.isTypeSupported(t)) || '';

      if (!mimeType) {
        setIsRecording(false);
        alert("Video recording is not supported in this browser.");
        reject(new Error("No supported mime type"));
        return;
      }

      // Initial render to ensure canvas isn't empty when stream starts
      renderFrame(ctx, image, selection, settings, 0, settings.duration * 1000);

      const stream = canvas.captureStream(30); // 30 FPS
      const recorder = new MediaRecorder(stream, {
        mimeType,
        videoBitsPerSecond: 8000000 // 8 Mbps for better quality
      });

      const chunks: Blob[] = [];
      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.push(e.data);
      };

      recorder.onstop = () => {
        const type = mimeType.split(';')[0];
        const ext = type.includes('mp4') ? 'mp4' : 'webm';
        const blob = new Blob(chunks, { type });
        const url = URL.createObjectURL(blob);

        const a = document.createElement('a');
        a.href = url;
        a.download = `highlight-video.${ext}`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);

        setIsRecording(false);
        resolve();
      };

      recorder.start();

      const startTime = performance.now();
      const durationMs = settings.duration * 1000;

      const processFrame = (now: number) => {
        const elapsed = now - startTime;

        // Update progress UI
        setProgress(Math.min(100, Math.round((elapsed / durationMs) * 100)));

        renderFrame(ctx, image, selection, settings, elapsed, durationMs);

        // Record a tiny bit extra (100ms) to prevent cutting off the end abruptly
        if (elapsed < durationMs + 100) {
          requestAnimationFrame(processFrame);
        } else {
          recorder.stop();
        }
      };

      requestAnimationFrame(processFrame);
    });
  }, []);

  return { isRecording, progress, exportVideo };
};

