}

export const EditorCanvas: React.FC<EditorCanvasProps> = ({
  imageSrc,
  selection,
  setSelection,
  settings,
  canvasRef,
}) => {
  const [image, setImage] = useState<HTMLImageElement | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Interaction State
  const isDragging = useRef(false);
  const startPos = useRef({ x: 0, y: 0 });
  const currentDragSelection = useRef<Selection | null>(null);

  // Animation State
  const requestRef = useRef<number>(0);
  const startTimeRef = useRef<number>(0);

  // 1. Load Image
  useEffect(() => {
    if (!imageSrc) return;
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = imageSrc;
    img.onload = () => {
      setImage(img);
      setSelection(null);
      if(canvasRef.current) {
        canvasRef.current.width = img.width;
        canvasRef.current.height = img.height;
      }
    };
  }, [imageSrc, setSelection, canvasRef]);

  // 2. Main Render Loop
  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas || !image) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = canvas.width;
    const height = canvas.height;

    // A. Dragging Phase (Selection Mode)
    if (isDragging.current && currentDragSelection.current) {
        // Draw clean image
        ctx.clearRect(0, 0, width, height);
        ctx.drawImage(image, 0, 0, width, height);

        // Draw dragging guide
        const s = currentDragSelection.current;

        // Dim background slightly to focus on selection
        ctx.fillStyle = 'rgba(0,0,0,0.5)'; // Darker dim for better contrast
        ctx.fillRect(0,0, width, height);

        // Clear rect for the selection area (hole punching)
        // This removes the dim layer to show the bright original image below
        ctx.clearRect(s.x, s.y, s.width, s.height);
        ctx.drawImage(image, s.x, s.y, s.width, s.height, s.x, s.y, s.width, s.height);

        // Selection Border
        ctx.strokeStyle = '#fff';
        const rect = canvas.getBoundingClientRect();
        const scaleFactor = width / (rect.width || 1);
        ctx.lineWidth = 2 * scaleFactor; 

        ctx.setLineDash([6 * scaleFactor, 4 * scaleFactor]);
        ctx.strokeRect(s.x, s.y, s.width, s.height);
        ctx.setLineDash([]);

        // Crosshair in center of selection
        ctx.beginPath();
        ctx.moveTo(s.x + s.width / 2 - 5 * scaleFactor, s.y + s.height / 2);
        ctx.lineTo(s.x + s.width / 2 + 5 * scaleFactor, s.y + s.height / 2);
        ctx.moveTo(s.x + s.width / 2, s.y + s.height / 2 - 5 * scaleFactor);
        ctx.lineTo(s.x + s.width / 2, s.y + s.height / 2 + 5 * scaleFactor);
        ctx.stroke();

    } 
    // B. Preview Phase (Animation Mode)
    else if (selection) {
        const durationMs = settings.duration * 1000;
        const loopDuration = durationMs + 1000; // 1s pause at end

        if (startTimeRef.current === 0) {
            startTimeRef.current = time;
        }

        const elapsed = Math.max(0, time - startTimeRef.current);
        const loopTime = elapsed % loopDuration;

        renderFrame(ctx, image, selection, settings, loopTime, durationMs);
    } 
    // C. Idle Phase (Image Only)
    else {
        ctx.clearRect(0, 0, width, height);
        ctx.drawImage(image, 0, 0, width, height);
    }

    requestRef.current = requestAnimationFrame(animate);
  }, [image, selection, settings, canvasRef]); 

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current);
  }, [animate]);

  // 3. Coordinate Helpers
  const getCanvasPoint = (e: React.PointerEvent<HTMLCanvasElement>) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const canvas = canvasRef.current;
    const rect = canvas.getBoundingClientRect();

    // Calculate scale
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;

    // Get relative coordinates
    const rawX = (e.clientX - rect.left) * scaleX;
    const rawY = (e.clientY - rect.top) * scaleY;

    // Clamp to canvas bounds
    const x = Math.max(0, Math.min(rawX, canvas.width));
    const y = Math.max(0, Math.min(rawY, canvas.height));

    return { x, y };
  };

  // 4. Pointer Handlers (Unified Mouse/Touch)
  const onPointerDown = (e: React.PointerEvent<HTMLCanvasElement>) => {
      if (!image || !canvasRef.current) return;

      // Capture pointer to track dragging even if it leaves canvas bounds
      canvasRef.current.setPointerCapture(e.pointerId);

      isDragging.current = true;
      setSelection(null); // Clear existing selection immediately

      const { x, y } = getCanvasPoint(e);
      startPos.current = { x, y };
      currentDragSelection.current = { x, y, width: 0, height: 0 };
  };

  const onPointerMove = (e: React.PointerEvent<HTMLCanvasElement>) => {
      if (!isDragging.current || !image) return;

      const { x, y } = getCanvasPoint(e);
      const startX = startPos.current.x;
      const startY = startPos.current.y;

      const width = Math.abs(x - startX);
      const height = Math.abs(y - startY);
      const left = Math.min(x, startX);
      const top = Math.min(y, startY);

      currentDragSelection.current = {
          x: left,
          y: top,
          width,
          height
      };
  };

  const onPointerUp = (e: React.PointerEvent<HTMLCanvasElement>) => {
      if (!isDragging.current) return;
      isDragging.current = false;
      if (canvasRef.current) {
          canvasRef.current.releasePointerCapture(e.pointerId);
      }

      const sel = currentDragSelection.current;

      // Minimum size threshold (e.g., 5x5 pixels)
      if (sel && sel.width > 5 && sel.height > 5) {
          setSelection(sel);
          startTimeRef.current = performance.now(); // Start animation
      } else {
          setSelection(null);
      }
      currentDragSelection.current = null;
  };

  return (
    <div 
      ref={containerRef} 
      className="relative w-full h-full flex items-center justify-center bg-zinc-900 overflow-hidden select-none p-4 lg:p-8"
    >
      {!image && (
         <div className="text-zinc-500 flex flex-col items-center animate-pulse gap-4">
             <div className="w-16 h-16 border-2 border-dashed border-zinc-700 rounded-xl flex items-center justify-center">
                 <Play size={24} className="opacity-20" />
             </div>
            <p className="text-sm font-medium">Upload an image to start</p>
         </div>
      )}

      <div className="relative shadow-2xl shadow-black/50 flex justify-center items-center" style={{ maxWidth: '100%', maxHeight: '100%' }}>
          <canvas
            ref={canvasRef}
            className={`block object-contain max-w-full max-h-full ${image ? 'cursor-crosshair' : ''}`}
            style={{ touchAction: 'none', maxWidth: '100%', maxHeight: '100%' }}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={onPointerUp}
            onPointerCancel={onPointerUp}
            onPointerLeave={onPointerUp}
          />

          {/* Status Badge */}
          {image && selection && !isDragging.current && (
              <div className="absolute top-4 right-4 flex items-center gap-2 bg-black/60 backdrop-blur px-3 py-1.5 rounded-full border border-white/10 pointer-events-none animate-in fade-in duration-300">
                  <div className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></div>
                  <span className="text-[10px] font-medium text-white/80 uppercase tracking-wide">Previewing</span>
              </div>
          )}
      </div>
    </div>
  );
};

export type AnimationType = 'pulse' | 'sweep' | 'neon' | 'focus' | 'underline' | 'marker' | 'fade' | 'circle' | 'brackets' | 'flash' | 'ripple' | 'magnify' | 'glitch' | 'rainbow';

export interface Selection {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface AnimationSettings {
  type: AnimationType;
  color: string;
  intensity: number; // 0 to 1
  speed: number; // Multiplier
  delay: number; // Seconds
  duration: number; // Seconds (video length)
  backgroundDim: number; // 0 to 1
  vignette: number; // 0 to 1
}

export interface VideoExportOptions {
  width: number;
  height: number;
  fps: number;
}

import { AnimationSettings, Selection } from '../types';

/**
 * Main render function used by both the preview loop and the export recorder.
 */
export const renderFrame = (
  ctx: CanvasRenderingContext2D,
  image: HTMLImageElement,
  selection: Selection | null,
  settings: AnimationSettings,
  timestamp: number, // current time in ms
  totalDurationMs: number
) => {
  const { width, height } = ctx.canvas;

  // 1. Draw Base Image
  ctx.clearRect(0, 0, width, height);
  ctx.drawImage(image, 0, 0, width, height);

  // If no selection, just show image
  if (!selection) return;

  // Calculate Relative Time for Animation
  const delayMs = settings.delay * 1000;
  const activeTime = timestamp - delayMs;
  const isStarted = activeTime > 0;

  // 2. Draw Background Dimming & Vignette (With Hole Punching)
  // We use clipping to ensure the dim/vignette DOES NOT cover the highlighted area.
  ctx.save();
  ctx.beginPath();
  // Outer rect (Canvas)
  ctx.rect(0, 0, width, height);
  // Inner rect (Selection) - Used to create hole via evenodd rule
  ctx.rect(selection.x, selection.y, selection.width, selection.height);
  ctx.clip('evenodd');

  // Apply Background Dim
  if (settings.backgroundDim > 0) {
    ctx.fillStyle = `rgba(0, 0, 0, ${settings.backgroundDim})`;
    ctx.fillRect(0, 0, width, height);
  }

  // Apply Vignette
  if (settings.vignette > 0) {
    const gradient = ctx.createRadialGradient(
      width / 2, height / 2, width * 0.3, // inner circle
      width / 2, height / 2, Math.max(width, height) * 0.8 // outer circle
    );
    gradient.addColorStop(0, 'rgba(0,0,0,0)');
    gradient.addColorStop(1, `rgba(0,0,0,${settings.vignette})`);

    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, width, height);
  }
  ctx.restore();

  if (!isStarted) return;

  // 3. Draw Highlights/Animations
  ctx.save();
  const cycle = (activeTime / 1000) * settings.speed;

  switch (settings.type) {
    case 'pulse': {
      // Oscillate alpha between 0.1 and settings.intensity
      const alpha = 0.1 + (Math.sin(cycle * Math.PI) + 1) / 2 * (settings.intensity - 0.1);

      // Glow fill
      ctx.globalCompositeOperation = 'overlay';
      ctx.fillStyle = settings.color;
      ctx.globalAlpha = alpha;
      ctx.fillRect(selection.x, selection.y, selection.width, selection.height);

      // Border stroke
      ctx.globalCompositeOperation = 'source-over';
      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 4;
      ctx.globalAlpha = alpha;
      ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
      break;
    }

    case 'sweep': {
      // Create a clipping region for the sweep so it stays inside selection
      ctx.beginPath();
      ctx.rect(selection.x, selection.y, selection.width, selection.height);
      ctx.clip();

      const gradientWidth = selection.width * 0.5;
      const totalDist = selection.width + gradientWidth * 2;
      const progress = (cycle % 2); 
      const xPos = selection.x - gradientWidth + (progress * totalDist);

      const grad = ctx.createLinearGradient(xPos, selection.y, xPos + gradientWidth, selection.y);
      grad.addColorStop(0, 'rgba(255,255,255,0)');
      grad.addColorStop(0.5, settings.color);
      grad.addColorStop(1, 'rgba(255,255,255,0)');

      ctx.fillStyle = grad;
      ctx.globalCompositeOperation = 'screen'; // Screen blend mode for nice light effect
      ctx.globalAlpha = settings.intensity;
      ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
      break;
    }

    case 'neon': {
      const pulseIntensity = 0.8 + (Math.sin(cycle * Math.PI * 2) * 0.2);
      ctx.globalAlpha = pulseIntensity * settings.intensity;

      // Outer Glow
      ctx.shadowBlur = 20;
      ctx.shadowColor = settings.color;
      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 4;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);

      // Inner Core
      ctx.shadowBlur = 0;
      ctx.strokeStyle = 'white';
      ctx.lineWidth = 1;
      ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
      break;
    }

    case 'underline': {
        const lineY = selection.y + selection.height + 8;
        const progress = Math.min(1, cycle); 
        const activeProgress = progress > 1 ? 1 : progress; 

        ctx.beginPath();
        ctx.strokeStyle = settings.color;
        ctx.lineWidth = 6 * settings.intensity;
        ctx.lineCap = 'round';
        ctx.globalAlpha = 0.9;

        const currentWidth = selection.width * activeProgress;
        ctx.moveTo(selection.x, lineY);
        // Subtle curve for natural look
        ctx.quadraticCurveTo(
            selection.x + currentWidth / 2, 
            lineY + 3, 
            selection.x + currentWidth, 
            lineY
        );
        ctx.stroke();
        break;
    }

    case 'marker': {
      ctx.beginPath();
      ctx.rect(selection.x, selection.y, selection.width, selection.height);
      ctx.clip();

      const progress = Math.min(1, cycle); 
      const w = selection.width * progress;

      ctx.fillStyle = settings.color;
      // 'multiply' is best for highlighters on light backgrounds, but 'overlay' or 'source-over' is safer for dark/mixed.
      // We'll use source-over with low alpha for a generic "tint".
      ctx.globalCompositeOperation = 'source-over'; 
      ctx.globalAlpha = 0.5 * settings.intensity;

      ctx.fillRect(selection.x, selection.y, w, selection.height);
      break;
    }

    case 'fade': {
      const progress = Math.min(1, cycle);
      // Fade in a border focus
      ctx.globalAlpha = progress * settings.intensity;
      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 3;
      ctx.setLineDash([10, 6]);
      // Animate dash offset for "marching ants" feel or just static? Let's do static for "Fade"
      ctx.strokeRect(selection.x - 4, selection.y - 4, selection.width + 8, selection.height + 8);

      // Also slight fill
      ctx.fillStyle = settings.color;
      ctx.globalAlpha = progress * 0.1 * settings.intensity;
      ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
      break;
    }

    case 'focus': {
       // Static focus border
       ctx.strokeStyle = settings.color;
       ctx.lineWidth = 2;
       ctx.globalAlpha = settings.intensity;
       ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
       break;
    }

    case 'circle': {
      // Draw a "hand-drawn" style ellipse
      const progress = Math.min(1, cycle * 1.5); // Draw fast
      const cx = selection.x + selection.width / 2;
      const cy = selection.y + selection.height / 2;
      const rx = selection.width / 2 + 10;
      const ry = selection.height / 2 + 10;

      ctx.beginPath();
      ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2);
      const len = 2 * Math.PI * Math.sqrt((rx*rx + ry*ry)/2) + 100; // approximate perimeter

      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 4 * settings.intensity;
      ctx.lineCap = 'round';
      ctx.setLineDash([len, len]);
      ctx.lineDashOffset = len - (progress * len);
      ctx.stroke();
      break;
    }

    case 'brackets': {
      // Draw corners brackets
      const progress = Math.min(1, cycle);
      const pad = 10;
      const cornerLen = Math.min(selection.width, selection.height) * 0.3 * progress;

      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 5 * settings.intensity;
      ctx.lineCap = 'round';
      ctx.globalAlpha = Math.min(1, progress * 2);

      const x = selection.x - pad;
      const y = selection.y - pad;
      const w = selection.width + pad * 2;
      const h = selection.height + pad * 2;

      // Top Left
      ctx.beginPath();
      ctx.moveTo(x, y + cornerLen);
      ctx.lineTo(x, y);
      ctx.lineTo(x + cornerLen, y);
      ctx.stroke();

      // Top Right
      ctx.beginPath();
      ctx.moveTo(x + w - cornerLen, y);
      ctx.lineTo(x + w, y);
      ctx.lineTo(x + w, y + cornerLen);
      ctx.stroke();

      // Bottom Right
      ctx.beginPath();
      ctx.moveTo(x + w, y + h - cornerLen);
      ctx.lineTo(x + w, y + h);
      ctx.lineTo(x + w - cornerLen, y + h);
      ctx.stroke();

      // Bottom Left
      ctx.beginPath();
      ctx.moveTo(x + cornerLen, y + h);
      ctx.lineTo(x, y + h);
      ctx.lineTo(x, y + h - cornerLen);
      ctx.stroke();
      break;
    }

    case 'flash': {
      // Spike intensity at start of cycle
      const spike = Math.max(0, 1 - (cycle * 3)); // Fast fade out
      const lingeringBorder = Math.min(1, cycle * 2);

      // Flash fill
      if (spike > 0) {
        ctx.globalCompositeOperation = 'overlay';
        ctx.fillStyle = 'white';
        ctx.globalAlpha = spike * settings.intensity;
        ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
      }

      // Lingering border
      ctx.globalCompositeOperation = 'source-over';
      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 3;
      ctx.globalAlpha = lingeringBorder * settings.intensity;
      ctx.strokeRect(selection.x - 2, selection.y - 2, selection.width + 4, selection.height + 4);
      break;
    }

    case 'ripple': {
      const maxRipples = 3;
      const maxDist = 50;

      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 2;

      for (let i = 0; i < maxRipples; i++) {
        const offset = i * 0.5; // Stagger start
        let localTime = cycle - offset;
        if (localTime < 0) continue;

        // Loop ripple effect
        localTime = localTime % 2; 
        const rippleProgress = localTime / 2; // 0 to 1

        if (rippleProgress > 1) continue;

        const expansion = rippleProgress * maxDist;
        const alpha = 1 - rippleProgress;

        ctx.globalAlpha = alpha * settings.intensity;
        ctx.strokeRect(
          selection.x - expansion, 
          selection.y - expansion, 
          selection.width + expansion * 2, 
          selection.height + expansion * 2
        );
      }
      break;
    }

    case 'magnify': {
      // Pop scale effect
      // 0 -> 1.1 -> 1.05 (breathing)
      let scale = 1.0;
      const enterDuration = 0.3;

      if (cycle < enterDuration) {
         // Pop in elastic
         const t = cycle / enterDuration;
         scale = 1 + (Math.sin(t * Math.PI) * 0.1 * settings.intensity);
      } else {
         // Gentle hover breath
         scale = 1.05 + Math.sin((cycle - enterDuration) * 2) * 0.02 * settings.intensity;
      }

      const w = selection.width * scale;
      const h = selection.height * scale;
      const x = selection.x - (w - selection.width) / 2;
      const y = selection.y - (h - selection.height) / 2;

      // Draw shadow
      ctx.shadowColor = 'rgba(0,0,0,0.5)';
      ctx.shadowBlur = 30 * settings.intensity;
      ctx.shadowOffsetX = 0;
      ctx.shadowOffsetY = 15;

      // Draw background fill to cover the 'hole' if it exists (though we are drawing over it)
      ctx.fillStyle = 'white'; 
      ctx.fillRect(x, y, w, h);

      // Draw the actual magnified image part
      ctx.drawImage(
          image, 
          selection.x, selection.y, selection.width, selection.height, // Source
          x, y, w, h // Dest
      );

      // Border
      ctx.shadowColor = 'transparent';
      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 4;
      ctx.strokeRect(x, y, w, h);
      break;
    }

    case 'rainbow': {
      const hue = (cycle * 200) % 360; // Rotate hue
      const color = `hsl(${hue}, 100%, 60%)`;

      // Glow
      ctx.shadowColor = color;
      ctx.shadowBlur = 20 * settings.intensity;

      // Border
      ctx.strokeStyle = color;
      ctx.lineWidth = 5 * settings.intensity;
      ctx.lineJoin = 'round';
      ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
      break;
    }

    case 'glitch': {
        const offsetMax = 10 * settings.intensity;

        // Random jitter every few frames
        // Use Math.floor(cycle * 30) to make it "stepped" like 30fps animation not smooth
        const step = Math.floor(cycle * 20);
        const isGlitchy = step % 5 !== 0; // Glitch most of the time, rest occasionally

        const rOffsetX = isGlitchy ? (Math.sin(step * 123) * offsetMax) : 0;
        const bOffsetX = isGlitchy ? (Math.cos(step * 321) * offsetMax) : 0;

        // Cyan channel (Offset Left)
        ctx.save();
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.8;
        ctx.strokeStyle = '#00FFFF';
        ctx.lineWidth = 3;
        ctx.strokeRect(selection.x + bOffsetX, selection.y, selection.width, selection.height);
        ctx.restore();

        // Red channel (Offset Right)
        ctx.save();
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.8;
        ctx.strokeStyle = '#FF0000';
        ctx.lineWidth = 3;
        ctx.strokeRect(selection.x + rOffsetX, selection.y, selection.width, selection.height);
        ctx.restore();

        // Main Box
        ctx.strokeStyle = settings.color;
        ctx.lineWidth = 2;
        ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);

        // Random horizontal slice glitch
        if (isGlitchy && (step % 3 === 0)) {
             const sliceH = (Math.sin(step) + 1) * 0.2 * selection.height;
             const sliceY = selection.y + (Math.abs(Math.cos(step)) * (selection.height - sliceH));
             const sliceOffset = (Math.random() > 0.5 ? 1 : -1) * offsetMax * 2;

             ctx.save();
             ctx.beginPath();
             ctx.rect(selection.x, sliceY, selection.width, sliceH);
             ctx.clip();
             ctx.drawImage(image, selection.x + sliceOffset, selection.y, selection.width, selection.height);
             ctx.restore();

             // Slice Color artifact
             ctx.fillStyle = Math.random() > 0.5 ? '#FF00FF' : '#00FF00';
             ctx.globalAlpha = 0.3;
             ctx.fillRect(selection.x + sliceOffset, sliceY, selection.width, sliceH);
        }
        break;
    }
  }

  ctx.restore();
};

export type AnimationType = 'pulse' | 'sweep' | 'neon' | 'focus' | 'underline' | 'marker' | 'fade' | 'circle' | 'brackets' | 'flash' | 'ripple' | 'magnify' | 'glitch' | 'rainbow' | 'reading';

export interface Selection {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface AnimationSettings {
  type: AnimationType;
  color: string;
  intensity: number; // 0 to 1
  speed: number; // Multiplier
  delay: number; // Seconds
  duration: number; // Seconds (video length)
  backgroundDim: number; // 0 to 1
  vignette: number; // 0 to 1
}

export interface VideoExportOptions {
  width: number;
  height: number;
  fps: number;
}

import { AnimationSettings, Selection } from '../types';

/**
 * Main render function used by both the preview loop and the export recorder.
 */
export const renderFrame = (
  ctx: CanvasRenderingContext2D,
  image: HTMLImageElement,
  selection: Selection | null,
  settings: AnimationSettings,
  timestamp: number, // current time in ms
  totalDurationMs: number
) => {
  const { width, height } = ctx.canvas;

  // 1. Draw Base Image
  ctx.clearRect(0, 0, width, height);
  ctx.drawImage(image, 0, 0, width, height);

  // If no selection, just show image
  if (!selection) return;

  // Calculate Relative Time for Animation
  const delayMs = settings.delay * 1000;
  const activeTime = timestamp - delayMs;
  const isStarted = activeTime > 0;

  // 2. Draw Background Dimming & Vignette (With Hole Punching)
  // We use clipping to ensure the dim/vignette DOES NOT cover the highlighted area.
  ctx.save();
  ctx.beginPath();
  // Outer rect (Canvas)
  ctx.rect(0, 0, width, height);
  // Inner rect (Selection) - Used to create hole via evenodd rule
  ctx.rect(selection.x, selection.y, selection.width, selection.height);
  ctx.clip('evenodd');

  // Apply Background Dim
  if (settings.backgroundDim > 0) {
    ctx.fillStyle = `rgba(0, 0, 0, ${settings.backgroundDim})`;
    ctx.fillRect(0, 0, width, height);
  }

  // Apply Vignette
  if (settings.vignette > 0) {
    const gradient = ctx.createRadialGradient(
      width / 2, height / 2, width * 0.3, // inner circle
      width / 2, height / 2, Math.max(width, height) * 0.8 // outer circle
    );
    gradient.addColorStop(0, 'rgba(0,0,0,0)');
    gradient.addColorStop(1, `rgba(0,0,0,${settings.vignette})`);

    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, width, height);
  }
  ctx.restore();

  if (!isStarted) return;

  // 3. Draw Highlights/Animations
  ctx.save();
  const cycle = (activeTime / 1000) * settings.speed;

  switch (settings.type) {
    case 'pulse': {
      // Oscillate alpha between 0.1 and settings.intensity
      const alpha = 0.1 + (Math.sin(cycle * Math.PI) + 1) / 2 * (settings.intensity - 0.1);

      // Glow fill
      ctx.globalCompositeOperation = 'overlay';
      ctx.fillStyle = settings.color;
      ctx.globalAlpha = alpha;
      ctx.fillRect(selection.x, selection.y, selection.width, selection.height);

      // Border stroke
      ctx.globalCompositeOperation = 'source-over';
      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 4;
      ctx.globalAlpha = alpha;
      ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
      break;
    }

    case 'sweep': {
      // Create a clipping region for the sweep so it stays inside selection
      ctx.beginPath();
      ctx.rect(selection.x, selection.y, selection.width, selection.height);
      ctx.clip();

      const gradientWidth = selection.width * 0.5;
      const totalDist = selection.width + gradientWidth * 2;
      const progress = (cycle % 2); 
      const xPos = selection.x - gradientWidth + (progress * totalDist);

      const grad = ctx.createLinearGradient(xPos, selection.y, xPos + gradientWidth, selection.y);
      grad.addColorStop(0, 'rgba(255,255,255,0)');
      grad.addColorStop(0.5, settings.color);
      grad.addColorStop(1, 'rgba(255,255,255,0)');

      ctx.fillStyle = grad;
      ctx.globalCompositeOperation = 'screen'; // Screen blend mode for nice light effect
      ctx.globalAlpha = settings.intensity;
      ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
      break;
    }

    case 'reading': {
        // Multi-line reading effect
        // Estimate line count based on height (approx 40px per line, or at least 1)
        const approxLineHeight = 40; 
        const numLines = Math.max(1, Math.ceil(selection.height / approxLineHeight));
        const realLineHeight = selection.height / numLines;

        // Use 'screen' for dark mode friendly highlights, or 'multiply' for light mode if we knew background.
        // Screen/Overlay is safest for mixed content.
        ctx.globalCompositeOperation = 'source-over';
        ctx.fillStyle = settings.color;

        // Limit cycle to 1.0 (doesn't loop endlessly in a weird way, just fills)
        // Or if we want it to loop:
        const progress = cycle % 1.5; // Allow some pause at end
        const activeProgress = Math.min(1, progress);

        // We want to fill line 1, then line 2, etc.
        const totalLinesProgress = activeProgress * numLines;

        for (let i = 0; i < numLines; i++) {
             // Calculate how much of THIS line is filled
             // If totalLinesProgress is 2.5, line 0 is full (1), line 1 is full (1), line 2 is half (0.5)
             const lineProgress = Math.max(0, Math.min(1, totalLinesProgress - i));

             if (lineProgress > 0) {
                 ctx.globalAlpha = 0.5 * settings.intensity; // Base highlight opacity
                 const w = selection.width * lineProgress;
                 ctx.fillRect(selection.x, selection.y + (i * realLineHeight), w, realLineHeight);
             }
        }
        break;
    }

    case 'neon': {
      const pulseIntensity = 0.8 + (Math.sin(cycle * Math.PI * 2) * 0.2);
      ctx.globalAlpha = pulseIntensity * settings.intensity;

      // Outer Glow
      ctx.shadowBlur = 20;
      ctx.shadowColor = settings.color;
      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 4;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);

      // Inner Core
      ctx.shadowBlur = 0;
      ctx.strokeStyle = 'white';
      ctx.lineWidth = 1;
      ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
      break;
    }

    case 'underline': {
        const lineY = selection.y + selection.height + 8;
        const progress = Math.min(1, cycle); 
        const activeProgress = progress > 1 ? 1 : progress; 

        ctx.beginPath();
        ctx.strokeStyle = settings.color;
        ctx.lineWidth = 6 * settings.intensity;
        ctx.lineCap = 'round';
        ctx.globalAlpha = 0.9;

        const currentWidth = selection.width * activeProgress;
        ctx.moveTo(selection.x, lineY);
        // Subtle curve for natural look
        ctx.quadraticCurveTo(
            selection.x + currentWidth / 2, 
            lineY + 3, 
            selection.x + currentWidth, 
            lineY
        );
        ctx.stroke();
        break;
    }

    case 'marker': {
      ctx.beginPath();
      ctx.rect(selection.x, selection.y, selection.width, selection.height);
      ctx.clip();

      const progress = Math.min(1, cycle); 
      const w = selection.width * progress;

      ctx.fillStyle = settings.color;
      // 'multiply' is best for highlighters on light backgrounds, but 'overlay' or 'source-over' is safer for dark/mixed.
      // We'll use source-over with low alpha for a generic "tint".
      ctx.globalCompositeOperation = 'source-over'; 
      ctx.globalAlpha = 0.5 * settings.intensity;

      ctx.fillRect(selection.x, selection.y, w, selection.height);
      break;
    }

    case 'fade': {
      const progress = Math.min(1, cycle);
      // Fade in a border focus
      ctx.globalAlpha = progress * settings.intensity;
      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 3;
      ctx.setLineDash([10, 6]);
      // Animate dash offset for "marching ants" feel or just static? Let's do static for "Fade"
      ctx.strokeRect(selection.x - 4, selection.y - 4, selection.width + 8, selection.height + 8);

      // Also slight fill
      ctx.fillStyle = settings.color;
      ctx.globalAlpha = progress * 0.1 * settings.intensity;
      ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
      break;
    }

    case 'focus': {
       // Static focus border
       ctx.strokeStyle = settings.color;
       ctx.lineWidth = 2;
       ctx.globalAlpha = settings.intensity;
       ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
       break;
    }

    case 'circle': {
      // Draw a "hand-drawn" style ellipse
      const progress = Math.min(1, cycle * 1.5); // Draw fast
      const cx = selection.x + selection.width / 2;
      const cy = selection.y + selection.height / 2;
      const rx = selection.width / 2 + 10;
      const ry = selection.height / 2 + 10;

      ctx.beginPath();
      ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2);
      const len = 2 * Math.PI * Math.sqrt((rx*rx + ry*ry)/2) + 100; // approximate perimeter

      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 4 * settings.intensity;
      ctx.lineCap = 'round';
      ctx.setLineDash([len, len]);
      ctx.lineDashOffset = len - (progress * len);
      ctx.stroke();
      break;
    }

    case 'brackets': {
      // Draw corners brackets
      const progress = Math.min(1, cycle);
      const pad = 10;
      const cornerLen = Math.min(selection.width, selection.height) * 0.3 * progress;

      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 5 * settings.intensity;
      ctx.lineCap = 'round';
      ctx.globalAlpha = Math.min(1, progress * 2);

      const x = selection.x - pad;
      const y = selection.y - pad;
      const w = selection.width + pad * 2;
      const h = selection.height + pad * 2;

      // Top Left
      ctx.beginPath();
      ctx.moveTo(x, y + cornerLen);
      ctx.lineTo(x, y);
      ctx.lineTo(x + cornerLen, y);
      ctx.stroke();

      // Top Right
      ctx.beginPath();
      ctx.moveTo(x + w - cornerLen, y);
      ctx.lineTo(x + w, y);
      ctx.lineTo(x + w, y + cornerLen);
      ctx.stroke();

      // Bottom Right
      ctx.beginPath();
      ctx.moveTo(x + w, y + h - cornerLen);
      ctx.lineTo(x + w, y + h);
      ctx.lineTo(x + w - cornerLen, y + h);
      ctx.stroke();

      // Bottom Left
      ctx.beginPath();
      ctx.moveTo(x + cornerLen, y + h);
      ctx.lineTo(x, y + h);
      ctx.lineTo(x, y + h - cornerLen);
      ctx.stroke();
      break;
    }

    case 'flash': {
      // Spike intensity at start of cycle
      const spike = Math.max(0, 1 - (cycle * 3)); // Fast fade out
      const lingeringBorder = Math.min(1, cycle * 2);

      // Flash fill
      if (spike > 0) {
        ctx.globalCompositeOperation = 'overlay';
        ctx.fillStyle = 'white';
        ctx.globalAlpha = spike * settings.intensity;
        ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
      }

      // Lingering border
      ctx.globalCompositeOperation = 'source-over';
      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 3;
      ctx.globalAlpha = lingeringBorder * settings.intensity;
      ctx.strokeRect(selection.x - 2, selection.y - 2, selection.width + 4, selection.height + 4);
      break;
    }

    case 'ripple': {
      const maxRipples = 3;
      const maxDist = 50;

      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 2;

      for (let i = 0; i < maxRipples; i++) {
        const offset = i * 0.5; // Stagger start
        let localTime = cycle - offset;
        if (localTime < 0) continue;

        // Loop ripple effect
        localTime = localTime % 2; 
        const rippleProgress = localTime / 2; // 0 to 1

        if (rippleProgress > 1) continue;

        const expansion = rippleProgress * maxDist;
        const alpha = 1 - rippleProgress;

        ctx.globalAlpha = alpha * settings.intensity;
        ctx.strokeRect(
          selection.x - expansion, 
          selection.y - expansion, 
          selection.width + expansion * 2, 
          selection.height + expansion * 2
        );
      }
      break;
    }

    case 'magnify': {
      // Pop scale effect
      // 0 -> 1.1 -> 1.05 (breathing)
      let scale = 1.0;
      const enterDuration = 0.3;

      if (cycle < enterDuration) {
         // Pop in elastic
         const t = cycle / enterDuration;
         scale = 1 + (Math.sin(t * Math.PI) * 0.1 * settings.intensity);
      } else {
         // Gentle hover breath
         scale = 1.05 + Math.sin((cycle - enterDuration) * 2) * 0.02 * settings.intensity;
      }

      const w = selection.width * scale;
      const h = selection.height * scale;
      const x = selection.x - (w - selection.width) / 2;
      const y = selection.y - (h - selection.height) / 2;

      // Draw shadow
      ctx.shadowColor = 'rgba(0,0,0,0.5)';
      ctx.shadowBlur = 30 * settings.intensity;
      ctx.shadowOffsetX = 0;
      ctx.shadowOffsetY = 15;

      // Draw background fill to cover the 'hole' if it exists (though we are drawing over it)
      ctx.fillStyle = 'white'; 
      ctx.fillRect(x, y, w, h);

      // Draw the actual magnified image part
      ctx.drawImage(
          image, 
          selection.x, selection.y, selection.width, selection.height, // Source
          x, y, w, h // Dest
      );

      // Border
      ctx.shadowColor = 'transparent';
      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 4;
      ctx.strokeRect(x, y, w, h);
      break;
    }

    case 'rainbow': {
      const hue = (cycle * 200) % 360; // Rotate hue
      const color = `hsl(${hue}, 100%, 60%)`;

      // Glow
      ctx.shadowColor = color;
      ctx.shadowBlur = 20 * settings.intensity;

      // Border
      ctx.strokeStyle = color;
      ctx.lineWidth = 5 * settings.intensity;
      ctx.lineJoin = 'round';
      ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
      break;
    }

    case 'glitch': {
        const offsetMax = 10 * settings.intensity;

        // Random jitter every few frames
        // Use Math.floor(cycle * 30) to make it "stepped" like 30fps animation not smooth
        const step = Math.floor(cycle * 20);
        const isGlitchy = step % 5 !== 0; // Glitch most of the time, rest occasionally

        const rOffsetX = isGlitchy ? (Math.sin(step * 123) * offsetMax) : 0;
        const bOffsetX = isGlitchy ? (Math.cos(step * 321) * offsetMax) : 0;

        // Cyan channel (Offset Left)
        ctx.save();
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.8;
        ctx.strokeStyle = '#00FFFF';
        ctx.lineWidth = 3;
        ctx.strokeRect(selection.x + bOffsetX, selection.y, selection.width, selection.height);
        ctx.restore();

        // Red channel (Offset Right)
        ctx.save();
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.8;
        ctx.strokeStyle = '#FF0000';
        ctx.lineWidth = 3;
        ctx.strokeRect(selection.x + rOffsetX, selection.y, selection.width, selection.height);
        ctx.restore();

        // Main Box
        ctx.strokeStyle = settings.color;
        ctx.lineWidth = 2;
        ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);

        // Random horizontal slice glitch
        if (isGlitchy && (step % 3 === 0)) {
             const sliceH = (Math.sin(step) + 1) * 0.2 * selection.height;
             const sliceY = selection.y + (Math.abs(Math.cos(step)) * (selection.height - sliceH));
             const sliceOffset = (Math.random() > 0.5 ? 1 : -1) * offsetMax * 2;

             ctx.save();
             ctx.beginPath();
             ctx.rect(selection.x, sliceY, selection.width, sliceH);
             ctx.clip();
             ctx.drawImage(image, selection.x + sliceOffset, selection.y, selection.width, selection.height);
             ctx.restore();

             // Slice Color artifact
             ctx.fillStyle = Math.random() > 0.5 ? '#FF00FF' : '#00FF00';
             ctx.globalAlpha = 0.3;
             ctx.fillRect(selection.x + sliceOffset, sliceY, selection.width, sliceH);
        }
        break;
    }
  }

  ctx.restore();
};

