import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Selection, AnimationSettings } from '../types';
import { renderFrame } from '../utils/drawing';
import { Play } from 'lucide-react';

interface EditorCanvasProps {
  imageSrc: string;
  selection: Selection | null;
  setSelection: (sel: Selection | null) => void;
  settings: AnimationSettings;
  canvasRef: React.RefObject<HTMLCanvasElement | null>;
}

type InteractionMode = 'create' | 'move' | 'n-resize' | 'e-resize' | 's-resize' | 'w-resize' | 'ne-resize' | 'nw-resize' | 'se-resize' | 'sw-resize' | 'none';

export const EditorCanvas: React.FC<EditorCanvasProps> = ({
  imageSrc,
  selection,
  setSelection,
  settings,
  canvasRef,
}) => {
  const [image, setImage] = useState<HTMLImageElement | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [cursor, setCursor] = useState<string>('default');

  // Interaction State
  const isDragging = useRef(false);
  const interactionMode = useRef<InteractionMode>('none');
  const startPos = useRef({ x: 0, y: 0 });
  const dragStartSelection = useRef<Selection | null>(null);

  // Animation State
  const requestRef = useRef<number>(0);
  const startTimeRef = useRef<number>(0);

  // 1. Load Image
  useEffect(() => {
    if (!imageSrc) return;
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = imageSrc;
    img.onload = () => {
      setImage(img);
      setSelection(null);
      if(canvasRef.current) {
        canvasRef.current.width = img.width;
        canvasRef.current.height = img.height;
      }
    };
  }, [imageSrc, setSelection, canvasRef]);

  // Helper: Draw Resize Handles
  const drawHandles = (ctx: CanvasRenderingContext2D, sel: Selection) => {
      const handleSize = 10; // Handle visual size
      const half = handleSize / 2;

      ctx.fillStyle = '#ffffff';
      ctx.strokeStyle = '#000000';
      ctx.lineWidth = 1;

      // Positions: TL, T, TR, R, BR, B, BL, L
      const points = [
          { x: sel.x, y: sel.y }, // TL
          { x: sel.x + sel.width / 2, y: sel.y }, // T
          { x: sel.x + sel.width, y: sel.y }, // TR
          { x: sel.x + sel.width, y: sel.y + sel.height / 2 }, // R
          { x: sel.x + sel.width, y: sel.y + sel.height }, // BR
          { x: sel.x + sel.width / 2, y: sel.y + sel.height }, // B
          { x: sel.x, y: sel.y + sel.height }, // BL
          { x: sel.x, y: sel.y + sel.height / 2 }, // L
      ];

      points.forEach(p => {
          ctx.beginPath();
          ctx.rect(p.x - half, p.y - half, handleSize, handleSize);
          ctx.fill();
          ctx.stroke();
      });
  };

  // 2. Main Render Loop
  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas || !image) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = canvas.width;
    const height = canvas.height;

    // A. Dragging Phase (Visualizing the change in real-time)
    if (isDragging.current) {
        // Draw base image
        ctx.clearRect(0, 0, width, height);
        ctx.drawImage(image, 0, 0, width, height);

        // Use the current updated selection (passed via props/state)
        // If we are creating, `selection` might be null or growing.
        // If editing, `selection` is the current state.

        const activeSel = selection;

        if (activeSel) {
            // Dim background slightly to focus on selection
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            ctx.fillRect(0,0, width, height);

            // Hole punch
            ctx.clearRect(activeSel.x, activeSel.y, activeSel.width, activeSel.height);
            ctx.drawImage(image, activeSel.x, activeSel.y, activeSel.width, activeSel.height, activeSel.x, activeSel.y, activeSel.width, activeSel.height);

            // Selection Border
            ctx.strokeStyle = '#fff';
            // Scale linewidth based on canvas size vs display size roughly
            const rect = canvas.getBoundingClientRect();
            const scaleFactor = width / (rect.width || 1);
            ctx.lineWidth = 1 * scaleFactor; 

            ctx.setLineDash([4 * scaleFactor, 4 * scaleFactor]);
            ctx.strokeRect(activeSel.x, activeSel.y, activeSel.width, activeSel.height);
            ctx.setLineDash([]);

            // Draw handles if not creating (creating usually implies just dragging out a box)
            if (interactionMode.current !== 'create') {
                drawHandles(ctx, activeSel);
            }
        }
    } 
    // B. Preview Phase (Animation Mode + Handles)
    else if (selection) {
        const durationMs = settings.duration * 1000;
        const loopDuration = durationMs + 1000; // 1s pause at end

        if (startTimeRef.current === 0) {
            startTimeRef.current = time;
        }

        const elapsed = Math.max(0, time - startTimeRef.current);
        const loopTime = elapsed % loopDuration;

        // Render the actual effect
        renderFrame(ctx, image, selection, settings, loopTime, durationMs);

        // Draw UI Overlay (Handles) on top
        drawHandles(ctx, selection);

        // Dashed border for clarity that it is selected
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
        ctx.lineWidth = 1;
        ctx.setLineDash([4, 4]);
        ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
        ctx.setLineDash([]);
    } 
    // C. Idle Phase (Image Only)
    else {
        ctx.clearRect(0, 0, width, height);
        ctx.drawImage(image, 0, 0, width, height);
    }

    requestRef.current = requestAnimationFrame(animate);
  }, [image, selection, settings, canvasRef]); 

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current);
  }, [animate]);

  // 3. Coordinate Helpers
  const getCanvasPoint = (e: React.PointerEvent<HTMLCanvasElement>) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const canvas = canvasRef.current;
    const rect = canvas.getBoundingClientRect();

    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;

    const rawX = (e.clientX - rect.left) * scaleX;
    const rawY = (e.clientY - rect.top) * scaleY;

    // Clamp? Maybe not for dragging handles off screen
    return { x: rawX, y: rawY }; 
  };

  const getInteractionType = (x: number, y: number): InteractionMode => {
      if (!selection) return 'create';

      const handleRadius = 20 * (canvasRef.current!.width / canvasRef.current!.getBoundingClientRect().width); // Hit area size
      const { x: sx, y: sy, width: w, height: h } = selection;

      // Check Handles
      // Corners
      if (Math.abs(x - sx) < handleRadius && Math.abs(y - sy) < handleRadius) return 'nw-resize';
      if (Math.abs(x - (sx + w)) < handleRadius && Math.abs(y - sy) < handleRadius) return 'ne-resize';
      if (Math.abs(x - (sx + w)) < handleRadius && Math.abs(y - (sy + h)) < handleRadius) return 'se-resize';
      if (Math.abs(x - sx) < handleRadius && Math.abs(y - (sy + h)) < handleRadius) return 'sw-resize';

      // Edges (Center points)
      if (Math.abs(x - (sx + w/2)) < handleRadius && Math.abs(y - sy) < handleRadius) return 'n-resize';
      if (Math.abs(x - (sx + w)) < handleRadius && Math.abs(y - (sy + h/2)) < handleRadius) return 'e-resize';
      if (Math.abs(x - (sx + w/2)) < handleRadius && Math.abs(y - (sy + h)) < handleRadius) return 's-resize';
      if (Math.abs(x - sx) < handleRadius && Math.abs(y - (sy + h/2)) < handleRadius) return 'w-resize';

      // Check Inside
      if (x > sx && x < sx + w && y > sy && y < sy + h) return 'move';

      return 'create';
  };

  // 4. Pointer Handlers
  const onPointerDown = (e: React.PointerEvent<HTMLCanvasElement>) => {
      if (!image || !canvasRef.current) return;
      canvasRef.current.setPointerCapture(e.pointerId);

      const { x, y } = getCanvasPoint(e);
      const mode = getInteractionType(x, y);

      interactionMode.current = mode;
      isDragging.current = true;
      startPos.current = { x, y };

      if (mode === 'create') {
          setSelection(null); // Clear to start fresh
          dragStartSelection.current = { x, y, width: 0, height: 0 };
      } else {
          // Determine offsets based on existing selection
          dragStartSelection.current = { ...selection! };
          // Don't reset time here, allows smooth editing while animating
      }
  };

  const onPointerMove = (e: React.PointerEvent<HTMLCanvasElement>) => {
      if (!image || !canvasRef.current) return;
      const { x, y } = getCanvasPoint(e);

      // A. Hover State (Update Cursor)
      if (!isDragging.current) {
          const mode = getInteractionType(x, y);
          let cursorStyle = 'default';
          switch (mode) {
              case 'create': cursorStyle = 'crosshair'; break;
              case 'move': cursorStyle = 'move'; break;
              case 'n-resize': case 's-resize': cursorStyle = 'ns-resize'; break;
              case 'e-resize': case 'w-resize': cursorStyle = 'ew-resize'; break;
              case 'nw-resize': case 'se-resize': cursorStyle = 'nwse-resize'; break;
              case 'ne-resize': case 'sw-resize': cursorStyle = 'nesw-resize'; break;
          }
          if (cursor !== cursorStyle) setCursor(cursorStyle);
          return;
      }

      // B. Drag State
      const startX = startPos.current.x;
      const startY = startPos.current.y;
      const dx = x - startX;
      const dy = y - startY;
      const initialSel = dragStartSelection.current!;

      let newSel: Selection | null = null;

      if (interactionMode.current === 'create') {
          const width = Math.abs(x - startX);
          const height = Math.abs(y - startY);
          const left = Math.min(x, startX);
          const top = Math.min(y, startY);
          newSel = { x: left, y: top, width, height };
      } 
      else if (interactionMode.current === 'move') {
          newSel = {
              x: initialSel.x + dx,
              y: initialSel.y + dy,
              width: initialSel.width,
              height: initialSel.height
          };
      } 
      else {
          // Resizing Logic
          let nx = initialSel.x;
          let ny = initialSel.y;
          let nw = initialSel.width;
          let nh = initialSel.height;

          // Apply deltas based on handle
          if (interactionMode.current.includes('w')) {
              nx = Math.min(initialSel.x + dx, initialSel.x + initialSel.width);
              nw = initialSel.width - (nx - initialSel.x);
          }
          if (interactionMode.current.includes('e')) {
              nw = x - initialSel.x;
          }
          if (interactionMode.current.includes('n')) {
              ny = Math.min(initialSel.y + dy, initialSel.y + initialSel.height);
              nh = initialSel.height - (ny - initialSel.y);
          }
          if (interactionMode.current.includes('s')) {
              nh = y - initialSel.y;
          }

          // Normalize negative width/height (flip if dragged past opposite edge)
          if (nw < 0) {
              nx = nx + nw;
              nw = Math.abs(nw);
          }
          if (nh < 0) {
              ny = ny + nh;
              nh = Math.abs(nh);
          }

          newSel = { x: nx, y: ny, width: nw, height: nh };
      }

      // Boundary checks (keep inside canvas)
      if (newSel) {
           // For move/resize, try to clamp. For create, it's automatic via min/max above mostly
           // but let's just ensure we don't crash drawing
           // (Draw function handles off-canvas coords fine, but let's be neat)
      }

      setSelection(newSel);
  };

  const onPointerUp = (e: React.PointerEvent<HTMLCanvasElement>) => {
      if (!isDragging.current) return;
      isDragging.current = false;
      if (canvasRef.current) {
          canvasRef.current.releasePointerCapture(e.pointerId);
      }

      // Finalize
      if (selection) {
          if (selection.width < 5 || selection.height < 5) {
              setSelection(null);
          } else {
             startTimeRef.current = performance.now(); // Restart animation on drop
          }
      }
      interactionMode.current = 'none';
  };

  return (
    <div 
      ref={containerRef} 
      className="relative w-full h-full flex items-center justify-center bg-zinc-900 overflow-hidden select-none p-4 lg:p-8"
    >
      {!image && (
         <div className="text-zinc-500 flex flex-col items-center animate-pulse gap-4">
             <div className="w-16 h-16 border-2 border-dashed border-zinc-700 rounded-xl flex items-center justify-center">
                 <Play size={24} className="opacity-20" />
             </div>
            <p className="text-sm font-medium">Upload an image to start</p>
         </div>
      )}

      <div className="relative shadow-2xl shadow-black/50 flex justify-center items-center" style={{ maxWidth: '100%', maxHeight: '100%' }}>
          <canvas
            ref={canvasRef}
            className={`block object-contain max-w-full max-h-full`}
            style={{ 
                touchAction: 'none', 
                maxWidth: '100%', 
                maxHeight: '100%',
                cursor: cursor // Dynamic cursor
            }}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={onPointerUp}
            onPointerCancel={onPointerUp}
            onPointerLeave={onPointerUp}
          />

          {/* Status Badge */}
          {image && selection && !isDragging.current && (
              <div className="absolute top-4 right-4 flex items-center gap-2 bg-black/60 backdrop-blur px-3 py-1.5 rounded-full border border-white/10 pointer-events-none animate-in fade-in duration-300 z-10">
                  <div className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></div>
                  <span className="text-[10px] font-medium text-white/80 uppercase tracking-wide">Previewing</span>
              </div>
          )}
      </div>
    </div>
  );
};

import { AnimationSettings, Selection } from '../types';

/**
 * Main render function used by both the preview loop and the export recorder.
 */
export const renderFrame = (
  ctx: CanvasRenderingContext2D,
  image: HTMLImageElement,
  selection: Selection | null,
  settings: AnimationSettings,
  timestamp: number, // current time in ms
  totalDurationMs: number
) => {
  const { width, height } = ctx.canvas;

  // 1. Draw Base Image
  ctx.clearRect(0, 0, width, height);
  ctx.drawImage(image, 0, 0, width, height);

  // If no selection, just show image
  if (!selection) return;

  // Calculate Relative Time for Animation
  const delayMs = settings.delay * 1000;
  const activeTime = timestamp - delayMs;
  const isStarted = activeTime > 0;

  // 2. Draw Background Dimming & Vignette (With Hole Punching)
  // We use clipping to ensure the dim/vignette DOES NOT cover the highlighted area.
  ctx.save();
  ctx.beginPath();
  // Outer rect (Canvas)
  ctx.rect(0, 0, width, height);
  // Inner rect (Selection) - Used to create hole via evenodd rule
  ctx.rect(selection.x, selection.y, selection.width, selection.height);
  ctx.clip('evenodd');

  // Apply Background Dim
  if (settings.backgroundDim > 0) {
    ctx.fillStyle = `rgba(0, 0, 0, ${settings.backgroundDim})`;
    ctx.fillRect(0, 0, width, height);
  }

  // Apply Vignette
  if (settings.vignette > 0) {
    const gradient = ctx.createRadialGradient(
      width / 2, height / 2, width * 0.3, // inner circle
      width / 2, height / 2, Math.max(width, height) * 0.8 // outer circle
    );
    gradient.addColorStop(0, 'rgba(0,0,0,0)');
    gradient.addColorStop(1, `rgba(0,0,0,${settings.vignette})`);

    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, width, height);
  }
  ctx.restore();

  if (!isStarted) return;

  // 3. Draw Highlights/Animations
  ctx.save();
  const cycle = (activeTime / 1000) * settings.speed;

  switch (settings.type) {
    case 'pulse': {
      // Oscillate alpha between 0.1 and settings.intensity
      const alpha = 0.1 + (Math.sin(cycle * Math.PI) + 1) / 2 * (settings.intensity - 0.1);

      // Glow fill
      ctx.globalCompositeOperation = 'overlay';
      ctx.fillStyle = settings.color;
      ctx.globalAlpha = alpha;
      ctx.fillRect(selection.x, selection.y, selection.width, selection.height);

      // Border stroke
      ctx.globalCompositeOperation = 'source-over';
      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 4;
      ctx.globalAlpha = alpha;
      ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
      break;
    }

    case 'sweep': {
      // Create a clipping region for the sweep so it stays inside selection
      ctx.beginPath();
      ctx.rect(selection.x, selection.y, selection.width, selection.height);
      ctx.clip();

      const gradientWidth = selection.width * 0.5;
      const totalDist = selection.width + gradientWidth * 2;

      // Play once.
      const progress = cycle; 
      const xPos = selection.x - gradientWidth + (progress * totalDist);

      const grad = ctx.createLinearGradient(xPos, selection.y, xPos + gradientWidth, selection.y);
      grad.addColorStop(0, 'rgba(255,255,255,0)');
      grad.addColorStop(0.5, settings.color);
      grad.addColorStop(1, 'rgba(255,255,255,0)');

      ctx.fillStyle = grad;
      ctx.globalCompositeOperation = 'screen'; // Screen blend mode for nice light effect
      ctx.globalAlpha = settings.intensity;
      ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
      break;
    }

    case 'reading': {
        // Multi-line reading effect
        // Estimate line count based on height (approx 40px per line, or at least 1)
        const approxLineHeight = 40; 
        const numLines = Math.max(1, Math.ceil(selection.height / approxLineHeight));
        const realLineHeight = selection.height / numLines;

        ctx.globalCompositeOperation = 'source-over';
        ctx.fillStyle = settings.color;

        // Play once, clamp at end.
        const activeProgress = Math.min(1, cycle);

        // We want to fill line 1, then line 2, etc.
        const totalLinesProgress = activeProgress * numLines;

        for (let i = 0; i < numLines; i++) {
             // Calculate how much of THIS line is filled
             const lineProgress = Math.max(0, Math.min(1, totalLinesProgress - i));

             if (lineProgress > 0) {
                 ctx.globalAlpha = 0.5 * settings.intensity; // Base highlight opacity
                 const w = selection.width * lineProgress;
                 ctx.fillRect(selection.x, selection.y + (i * realLineHeight), w, realLineHeight);
             }
        }
        break;
    }

    case 'neon': {
      const pulseIntensity = 0.8 + (Math.sin(cycle * Math.PI * 2) * 0.2);
      ctx.globalAlpha = pulseIntensity * settings.intensity;

      // Outer Glow
      ctx.shadowBlur = 20;
      ctx.shadowColor = settings.color;
      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 4;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);

      // Inner Core
      ctx.shadowBlur = 0;
      ctx.strokeStyle = 'white';
      ctx.lineWidth = 1;
      ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
      break;
    }

    case 'underline': {
        const lineY = selection.y + selection.height + 8;
        const progress = Math.min(1, cycle); 
        const activeProgress = progress > 1 ? 1 : progress; 

        ctx.beginPath();
        ctx.strokeStyle = settings.color;
        ctx.lineWidth = 6 * settings.intensity;
        ctx.lineCap = 'round';
        ctx.globalAlpha = 0.9;

        const currentWidth = selection.width * activeProgress;
        ctx.moveTo(selection.x, lineY);
        // Subtle curve for natural look
        ctx.quadraticCurveTo(
            selection.x + currentWidth / 2, 
            lineY + 3, 
            selection.x + currentWidth, 
            lineY
        );
        ctx.stroke();
        break;
    }

    case 'marker': {
      ctx.beginPath();
      ctx.rect(selection.x, selection.y, selection.width, selection.height);
      ctx.clip();

      const progress = Math.min(1, cycle); 
      const w = selection.width * progress;

      ctx.fillStyle = settings.color;
      ctx.globalCompositeOperation = 'source-over'; 
      ctx.globalAlpha = 0.5 * settings.intensity;

      ctx.fillRect(selection.x, selection.y, w, selection.height);
      break;
    }

    case 'fade': {
      const progress = Math.min(1, cycle);
      // Fade in a border focus
      ctx.globalAlpha = progress * settings.intensity;
      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 3;
      ctx.setLineDash([10, 6]);
      // Animate dash offset for "marching ants" feel or just static? Let's do static for "Fade"
      ctx.strokeRect(selection.x - 4, selection.y - 4, selection.width + 8, selection.height + 8);

      // Also slight fill
      ctx.fillStyle = settings.color;
      ctx.globalAlpha = progress * 0.1 * settings.intensity;
      ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
      break;
    }

    case 'focus': {
       // Static focus border
       ctx.strokeStyle = settings.color;
       ctx.lineWidth = 2;
       ctx.globalAlpha = settings.intensity;
       ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
       break;
    }

    case 'circle': {
      // Draw a "hand-drawn" style ellipse
      const progress = Math.min(1, cycle * 1.5); // Draw fast
      const cx = selection.x + selection.width / 2;
      const cy = selection.y + selection.height / 2;
      const rx = selection.width / 2 + 10;
      const ry = selection.height / 2 + 10;

      ctx.beginPath();
      ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2);
      const len = 2 * Math.PI * Math.sqrt((rx*rx + ry*ry)/2) + 100; // approximate perimeter

      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 4 * settings.intensity;
      ctx.lineCap = 'round';
      ctx.setLineDash([len, len]);
      ctx.lineDashOffset = len - (progress * len);
      ctx.stroke();
      break;
    }

    case 'brackets': {
      // Draw corners brackets
      const progress = Math.min(1, cycle);
      const pad = 10;
      const cornerLen = Math.min(selection.width, selection.height) * 0.3 * progress;

      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 5 * settings.intensity;
      ctx.lineCap = 'round';
      ctx.globalAlpha = Math.min(1, progress * 2);

      const x = selection.x - pad;
      const y = selection.y - pad;
      const w = selection.width + pad * 2;
      const h = selection.height + pad * 2;

      // Top Left
      ctx.beginPath();
      ctx.moveTo(x, y + cornerLen);
      ctx.lineTo(x, y);
      ctx.lineTo(x + cornerLen, y);
      ctx.stroke();

      // Top Right
      ctx.beginPath();
      ctx.moveTo(x + w - cornerLen, y);
      ctx.lineTo(x + w, y);
      ctx.lineTo(x + w, y + cornerLen);
      ctx.stroke();

      // Bottom Right
      ctx.beginPath();
      ctx.moveTo(x + w, y + h - cornerLen);
      ctx.lineTo(x + w, y + h);
      ctx.lineTo(x + w - cornerLen, y + h);
      ctx.stroke();

      // Bottom Left
      ctx.beginPath();
      ctx.moveTo(x + cornerLen, y + h);
      ctx.lineTo(x, y + h);
      ctx.lineTo(x, y + h - cornerLen);
      ctx.stroke();
      break;
    }

    case 'flash': {
      // Spike intensity at start of cycle
      const spike = Math.max(0, 1 - (cycle * 3)); // Fast fade out
      const lingeringBorder = Math.min(1, cycle * 2);

      // Flash fill
      if (spike > 0) {
        ctx.globalCompositeOperation = 'overlay';
        ctx.fillStyle = 'white';
        ctx.globalAlpha = spike * settings.intensity;
        ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
      }

      // Lingering border
      ctx.globalCompositeOperation = 'source-over';
      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 3;
      ctx.globalAlpha = lingeringBorder * settings.intensity;
      ctx.strokeRect(selection.x - 2, selection.y - 2, selection.width + 4, selection.height + 4);
      break;
    }

    case 'ripple': {
      const maxRipples = 3;
      const maxDist = 50;

      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 2;

      for (let i = 0; i < maxRipples; i++) {
        const offset = i * 0.5; // Stagger start
        let localTime = cycle - offset;
        if (localTime < 0) continue;

        // Ripple plays once and fades out
        const rippleProgress = localTime / 2; // 0 to 1 scaling

        if (rippleProgress > 1) continue;

        const expansion = rippleProgress * maxDist;
        const alpha = 1 - rippleProgress;

        ctx.globalAlpha = alpha * settings.intensity;
        ctx.strokeRect(
          selection.x - expansion, 
          selection.y - expansion, 
          selection.width + expansion * 2, 
          selection.height + expansion * 2
        );
      }
      break;
    }

    case 'magnify': {
      // Pop scale effect
      // 0 -> 1.1 -> 1.05 (breathing)
      let scale = 1.0;
      const enterDuration = 0.3;

      if (cycle < enterDuration) {
         // Pop in elastic
         const t = cycle / enterDuration;
         scale = 1 + (Math.sin(t * Math.PI) * 0.1 * settings.intensity);
      } else {
         // Gentle hover breath
         scale = 1.05 + Math.sin((cycle - enterDuration) * 2) * 0.02 * settings.intensity;
      }

      const w = selection.width * scale;
      const h = selection.height * scale;
      const x = selection.x - (w - selection.width) / 2;
      const y = selection.y - (h - selection.height) / 2;

      // Draw shadow
      ctx.shadowColor = 'rgba(0,0,0,0.5)';
      ctx.shadowBlur = 30 * settings.intensity;
      ctx.shadowOffsetX = 0;
      ctx.shadowOffsetY = 15;

      // Draw background fill to cover the 'hole' if it exists (though we are drawing over it)
      ctx.fillStyle = 'white'; 
      ctx.fillRect(x, y, w, h);

      // Draw the actual magnified image part
      ctx.drawImage(
          image, 
          selection.x, selection.y, selection.width, selection.height, // Source
          x, y, w, h // Dest
      );

      // Border
      ctx.shadowColor = 'transparent';
      ctx.strokeStyle = settings.color;
      ctx.lineWidth = 4;
      ctx.strokeRect(x, y, w, h);
      break;
    }

    case 'rainbow': {
      const hue = (cycle * 200) % 360; // Rotate hue
      const color = `hsl(${hue}, 100%, 60%)`;

      // Glow
      ctx.shadowColor = color;
      ctx.shadowBlur = 20 * settings.intensity;

      // Border
      ctx.strokeStyle = color;
      ctx.lineWidth = 5 * settings.intensity;
      ctx.lineJoin = 'round';
      ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
      break;
    }

    case 'glitch': {
        const offsetMax = 10 * settings.intensity;

        // Random jitter every few frames
        // Use Math.floor(cycle * 30) to make it "stepped" like 30fps animation not smooth
        const step = Math.floor(cycle * 20);
        const isGlitchy = step % 5 !== 0; // Glitch most of the time, rest occasionally

        const rOffsetX = isGlitchy ? (Math.sin(step * 123) * offsetMax) : 0;
        const bOffsetX = isGlitchy ? (Math.cos(step * 321) * offsetMax) : 0;

        // Cyan channel (Offset Left)
        ctx.save();
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.8;
        ctx.strokeStyle = '#00FFFF';
        ctx.lineWidth = 3;
        ctx.strokeRect(selection.x + bOffsetX, selection.y, selection.width, selection.height);
        ctx.restore();

        // Red channel (Offset Right)
        ctx.save();
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.8;
        ctx.strokeStyle = '#FF0000';
        ctx.lineWidth = 3;
        ctx.strokeRect(selection.x + rOffsetX, selection.y, selection.width, selection.height);
        ctx.restore();

        // Main Box
        ctx.strokeStyle = settings.color;
        ctx.lineWidth = 2;
        ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);

        // Random horizontal slice glitch
        if (isGlitchy && (step % 3 === 0)) {
             const sliceH = (Math.sin(step) + 1) * 0.2 * selection.height;
             const sliceY = selection.y + (Math.abs(Math.cos(step)) * (selection.height - sliceH));
             const sliceOffset = (Math.random() > 0.5 ? 1 : -1) * offsetMax * 2;

             ctx.save();
             ctx.beginPath();
             ctx.rect(selection.x, sliceY, selection.width, sliceH);
             ctx.clip();
             ctx.drawImage(image, selection.x + sliceOffset, selection.y, selection.width, selection.height);
             ctx.restore();

             // Slice Color artifact
             ctx.fillStyle = Math.random() > 0.5 ? '#FF00FF' : '#00FF00';
             ctx.globalAlpha = 0.3;
             ctx.fillRect(selection.x + sliceOffset, sliceY, selection.width, sliceH);
        }
        break;
    }
  }

  ctx.restore();
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Selection, AnimationSettings } from '../types';
import { renderFrame } from '../utils/drawing';
import { Play } from 'lucide-react';

interface EditorCanvasProps {
  imageSrc: string;
  selection: Selection | null;
  setSelection: (sel: Selection | null) => void;
  settings: AnimationSettings;
  canvasRef: React.RefObject<HTMLCanvasElement | null>;
}

type InteractionMode = 'create' | 'move' | 'n-resize' | 'e-resize' | 's-resize' | 'w-resize' | 'ne-resize' | 'nw-resize' | 'se-resize' | 'sw-resize' | 'none';

export const EditorCanvas: React.FC<EditorCanvasProps> = ({
  imageSrc,
  selection,
  setSelection,
  settings,
  canvasRef,
}) => {
  const [image, setImage] = useState<HTMLImageElement | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [cursor, setCursor] = useState<string>('default');

  // Interaction State
  const isDragging = useRef(false);
  const interactionMode = useRef<InteractionMode>('none');
  const startPos = useRef({ x: 0, y: 0 });
  const dragStartSelection = useRef<Selection | null>(null);

  // Animation State
  const requestRef = useRef<number>(0);
  const startTimeRef = useRef<number>(0);

  // 1. Load Image
  useEffect(() => {
    if (!imageSrc) return;
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = imageSrc;
    img.onload = () => {
      setImage(img);
      setSelection(null);
      if(canvasRef.current) {
        canvasRef.current.width = img.width;
        canvasRef.current.height = img.height;
      }
    };
  }, [imageSrc, setSelection, canvasRef]);

  // Helper: Draw Resize Handles
  const drawHandles = (ctx: CanvasRenderingContext2D, sel: Selection) => {
      const handleSize = 10; // Handle visual size
      const half = handleSize / 2;

      ctx.fillStyle = '#ffffff';
      ctx.strokeStyle = '#000000';
      ctx.lineWidth = 1;

      // Positions: TL, T, TR, R, BR, B, BL, L
      const points = [
          { x: sel.x, y: sel.y }, // TL
          { x: sel.x + sel.width / 2, y: sel.y }, // T
          { x: sel.x + sel.width, y: sel.y }, // TR
          { x: sel.x + sel.width, y: sel.y + sel.height / 2 }, // R
          { x: sel.x + sel.width, y: sel.y + sel.height }, // BR
          { x: sel.x + sel.width / 2, y: sel.y + sel.height }, // B
          { x: sel.x, y: sel.y + sel.height }, // BL
          { x: sel.x, y: sel.y + sel.height / 2 }, // L
      ];

      points.forEach(p => {
          ctx.beginPath();
          ctx.rect(p.x - half, p.y - half, handleSize, handleSize);
          ctx.fill();
          ctx.stroke();
      });
  };

  // 2. Main Render Loop
  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas || !image) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const width = canvas.width;
    const height = canvas.height;

    // A. Dragging Phase (Visualizing the change in real-time)
    if (isDragging.current) {
        // Draw base image
        ctx.clearRect(0, 0, width, height);
        ctx.drawImage(image, 0, 0, width, height);

        // Use the current updated selection (passed via props/state)
        // If we are creating, `selection` might be null or growing.
        // If editing, `selection` is the current state.

        const activeSel = selection;

        if (activeSel) {
            // Dim background slightly to focus on selection
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            ctx.fillRect(0,0, width, height);

            // Hole punch
            ctx.clearRect(activeSel.x, activeSel.y, activeSel.width, activeSel.height);
            ctx.drawImage(image, activeSel.x, activeSel.y, activeSel.width, activeSel.height, activeSel.x, activeSel.y, activeSel.width, activeSel.height);

            // Selection Border
            ctx.strokeStyle = '#fff';
            // Scale linewidth based on canvas size vs display size roughly
            const rect = canvas.getBoundingClientRect();
            const scaleFactor = width / (rect.width || 1);
            ctx.lineWidth = 1 * scaleFactor; 

            ctx.setLineDash([4 * scaleFactor, 4 * scaleFactor]);
            ctx.strokeRect(activeSel.x, activeSel.y, activeSel.width, activeSel.height);
            ctx.setLineDash([]);

            // Draw handles if not creating (creating usually implies just dragging out a box)
            if (interactionMode.current !== 'create') {
                drawHandles(ctx, activeSel);
            }
        }
    } 
    // B. Preview Phase (Animation Mode + Handles)
    else if (selection) {
        const durationMs = settings.duration * 1000;
        const loopDuration = durationMs + 2000; // 2s pause at end

        if (startTimeRef.current === 0) {
            startTimeRef.current = time;
        }

        const elapsed = Math.max(0, time - startTimeRef.current);
        const loopTime = elapsed % loopDuration;

        // Render the actual effect
        renderFrame(ctx, image, selection, settings, loopTime, durationMs);

        // Draw UI Overlay (Handles) on top
        drawHandles(ctx, selection);

        // Dashed border for clarity that it is selected
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
        ctx.lineWidth = 1;
        ctx.setLineDash([4, 4]);
        ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
        ctx.setLineDash([]);
    } 
    // C. Idle Phase (Image Only)
    else {
        ctx.clearRect(0, 0, width, height);
        ctx.drawImage(image, 0, 0, width, height);
    }

    requestRef.current = requestAnimationFrame(animate);
  }, [image, selection, settings, canvasRef]); 

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current);
  }, [animate]);

  // 3. Coordinate Helpers
  const getCanvasPoint = (e: React.PointerEvent<HTMLCanvasElement>) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const canvas = canvasRef.current;
    const rect = canvas.getBoundingClientRect();

    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;

    const rawX = (e.clientX - rect.left) * scaleX;
    const rawY = (e.clientY - rect.top) * scaleY;

    // Clamp? Maybe not for dragging handles off screen
    return { x: rawX, y: rawY }; 
  };

  const getInteractionType = (x: number, y: number): InteractionMode => {
      if (!selection) return 'create';

      const handleRadius = 20 * (canvasRef.current!.width / canvasRef.current!.getBoundingClientRect().width); // Hit area size
      const { x: sx, y: sy, width: w, height: h } = selection;

      // Check Handles
      // Corners
      if (Math.abs(x - sx) < handleRadius && Math.abs(y - sy) < handleRadius) return 'nw-resize';
      if (Math.abs(x - (sx + w)) < handleRadius && Math.abs(y - sy) < handleRadius) return 'ne-resize';
      if (Math.abs(x - (sx + w)) < handleRadius && Math.abs(y - (sy + h)) < handleRadius) return 'se-resize';
      if (Math.abs(x - sx) < handleRadius && Math.abs(y - (sy + h)) < handleRadius) return 'sw-resize';

      // Edges (Center points)
      if (Math.abs(x - (sx + w/2)) < handleRadius && Math.abs(y - sy) < handleRadius) return 'n-resize';
      if (Math.abs(x - (sx + w)) < handleRadius && Math.abs(y - (sy + h/2)) < handleRadius) return 'e-resize';
      if (Math.abs(x - (sx + w/2)) < handleRadius && Math.abs(y - (sy + h)) < handleRadius) return 's-resize';
      if (Math.abs(x - sx) < handleRadius && Math.abs(y - (sy + h/2)) < handleRadius) return 'w-resize';

      // Check Inside
      if (x > sx && x < sx + w && y > sy && y < sy + h) return 'move';

      return 'create';
  };

  // 4. Pointer Handlers
  const onPointerDown = (e: React.PointerEvent<HTMLCanvasElement>) => {
      if (!image || !canvasRef.current) return;
      canvasRef.current.setPointerCapture(e.pointerId);

      const { x, y } = getCanvasPoint(e);
      const mode = getInteractionType(x, y);

      interactionMode.current = mode;
      isDragging.current = true;
      startPos.current = { x, y };

      if (mode === 'create') {
          setSelection(null); // Clear to start fresh
          dragStartSelection.current = { x, y, width: 0, height: 0 };
      } else {
          // Determine offsets based on existing selection
          dragStartSelection.current = { ...selection! };
          // Don't reset time here, allows smooth editing while animating
      }
  };

  const onPointerMove = (e: React.PointerEvent<HTMLCanvasElement>) => {
      if (!image || !canvasRef.current) return;
      const { x, y } = getCanvasPoint(e);

      // A. Hover State (Update Cursor)
      if (!isDragging.current) {
          const mode = getInteractionType(x, y);
          let cursorStyle = 'default';
          switch (mode) {
              case 'create': cursorStyle = 'crosshair'; break;
              case 'move': cursorStyle = 'move'; break;
              case 'n-resize': case 's-resize': cursorStyle = 'ns-resize'; break;
              case 'e-resize': case 'w-resize': cursorStyle = 'ew-resize'; break;
              case 'nw-resize': case 'se-resize': cursorStyle = 'nwse-resize'; break;
              case 'ne-resize': case 'sw-resize': cursorStyle = 'nesw-resize'; break;
          }
          if (cursor !== cursorStyle) setCursor(cursorStyle);
          return;
      }

      // B. Drag State
      const startX = startPos.current.x;
      const startY = startPos.current.y;
      const dx = x - startX;
      const dy = y - startY;
      const initialSel = dragStartSelection.current!;

      let newSel: Selection | null = null;

      if (interactionMode.current === 'create') {
          const width = Math.abs(x - startX);
          const height = Math.abs(y - startY);
          const left = Math.min(x, startX);
          const top = Math.min(y, startY);
          newSel = { x: left, y: top, width, height };
      } 
      else if (interactionMode.current === 'move') {
          newSel = {
              x: initialSel.x + dx,
              y: initialSel.y + dy,
              width: initialSel.width,
              height: initialSel.height
          };
      } 
      else {
          // Resizing Logic
          let nx = initialSel.x;
          let ny = initialSel.y;
          let nw = initialSel.width;
          let nh = initialSel.height;

          // Apply deltas based on handle
          if (interactionMode.current.includes('w')) {
              nx = Math.min(initialSel.x + dx, initialSel.x + initialSel.width);
              nw = initialSel.width - (nx - initialSel.x);
          }
          if (interactionMode.current.includes('e')) {
              nw = x - initialSel.x;
          }
          if (interactionMode.current.includes('n')) {
              ny = Math.min(initialSel.y + dy, initialSel.y + initialSel.height);
              nh = initialSel.height - (ny - initialSel.y);
          }
          if (interactionMode.current.includes('s')) {
              nh = y - initialSel.y;
          }

          // Normalize negative width/height (flip if dragged past opposite edge)
          if (nw < 0) {
              nx = nx + nw;
              nw = Math.abs(nw);
          }
          if (nh < 0) {
              ny = ny + nh;
              nh = Math.abs(nh);
          }

          newSel = { x: nx, y: ny, width: nw, height: nh };
      }

      // Boundary checks (keep inside canvas)
      if (newSel) {
           // For move/resize, try to clamp. For create, it's automatic via min/max above mostly
           // but let's just ensure we don't crash drawing
           // (Draw function handles off-canvas coords fine, but let's be neat)
      }

      setSelection(newSel);
  };

  const onPointerUp = (e: React.PointerEvent<HTMLCanvasElement>) => {
      if (!isDragging.current) return;
      isDragging.current = false;
      if (canvasRef.current) {
          canvasRef.current.releasePointerCapture(e.pointerId);
      }

      // Finalize
      if (selection) {
          if (selection.width < 5 || selection.height < 5) {
              setSelection(null);
          } else {
             startTimeRef.current = performance.now(); // Restart animation on drop
          }
      }
      interactionMode.current = 'none';
  };

  return (
    <div 
      ref={containerRef} 
      className="relative w-full h-full flex items-center justify-center bg-zinc-900 overflow-hidden select-none p-4 lg:p-8"
    >
      {!image && (
         <div className="text-zinc-500 flex flex-col items-center animate-pulse gap-4">
             <div className="w-16 h-16 border-2 border-dashed border-zinc-700 rounded-xl flex items-center justify-center">
                 <Play size={24} className="opacity-20" />
             </div>
            <p className="text-sm font-medium">Upload an image to start</p>
         </div>
      )}

      <div className="relative shadow-2xl shadow-black/50 flex justify-center items-center" style={{ maxWidth: '100%', maxHeight: '100%' }}>
          <canvas
            ref={canvasRef}
            className={`block object-contain max-w-full max-h-full`}
            style={{ 
                touchAction: 'none', 
                maxWidth: '100%', 
                maxHeight: '100%',
                cursor: cursor // Dynamic cursor
            }}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={onPointerUp}
            onPointerCancel={onPointerUp}
            onPointerLeave={onPointerUp}
          />

          {/* Status Badge */}
          {image && selection && !isDragging.current && (
              <div className="absolute top-4 right-4 flex items-center gap-2 bg-black/60 backdrop-blur px-3 py-1.5 rounded-full border border-white/10 pointer-events-none animate-in fade-in duration-300 z-10">
                  <div className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></div>
                  <span className="text-[10px] font-medium text-white/80 uppercase tracking-wide">Previewing</span>
              </div>
          )}
      </div>
    </div>
  );
};

export type AnimationType = 'pulse' | 'sweep' | 'neon' | 'focus' | 'underline' | 'marker' | 'fade' | 'circle' | 'brackets' | 'flash' | 'ripple' | 'magnify' | 'glitch' | 'rainbow' | 'reading';

export interface Selection {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface AnimationSettings {
  type: AnimationType;
  color: string;
  intensity: number; // 0 to 1
  speed: number; // Multiplier
  delay: number; // Seconds
  duration: number; // Seconds (video length)
  backgroundDim: number; // 0 to 1
  vignette: number; // 0 to 1
}

export interface Layer {
  id: string;
  selection: Selection;
  settings: AnimationSettings;
}

export interface VideoExportOptions {
  width: number;
  height: number;
  fps: number;
}

import { AnimationSettings, Layer, Selection } from '../types';

/**
 * Helper: Analyzes pixel data to find where text exists vs whitespace.
 * Returns an array of booleans (true = content, false = space) for each X coordinate.
 */
const getCompositionMask = (
  ctx: CanvasRenderingContext2D,
  image: HTMLImageElement,
  selection: Selection
): boolean[] => {
  // Optimization: For very large selections, we might want to downsample, 
  // but for typical text highlights, full res is fine.

  // We need to draw the source image to a temp canvas to read pixel data safely
  // if the main ctx is already dirty. However, renderFrame clears ctx first.
  // We can read directly from the main ctx since the base image is drawn first.

  try {
    const imageData = ctx.getImageData(selection.x, selection.y, selection.width, selection.height);
    const data = imageData.data;
    const width = imageData.width;
    const height = imageData.height;
    const hasContent = new Array(width).fill(false);

    // Threshold for "darkness" (assuming text is darker than background)
    // Or "variance" from background. Let's assume white/light background for now.
    // A pixel is "content" if it's significantly darker than white.
    const threshold = 230; 

    for (let x = 0; x < width; x++) {
      let darkPixelsInColumn = 0;
      for (let y = 0; y < height; y++) {
        const idx = (y * width + x) * 4;
        const r = data[idx];
        const g = data[idx + 1];
        const b = data[idx + 2];
        const a = data[idx + 3];

        // Simple brightness check
        const brightness = (r + g + b) / 3;

        if (a > 20 && brightness < threshold) {
          darkPixelsInColumn++;
        }
      }
      // If a column has enough dark pixels, it's part of a character
      if (darkPixelsInColumn > 0) {
        hasContent[x] = true;
      }
    }

    // Dilate (expand) the mask slightly to connect letters within a word
    // but keep gaps between words
    const dilated = [...hasContent];
    const gapThreshold = 4; // If a gap is smaller than this, fill it (it's space between letters, not words)

    let currentGap = 0;
    for(let x=0; x<width; x++) {
        if (!hasContent[x]) {
            currentGap++;
        } else {
            if (currentGap > 0 && currentGap < gapThreshold) {
                // Backfill small gaps
                for(let k=1; k<=currentGap; k++) dilated[x-k] = true;
            }
            currentGap = 0;
        }
    }

    return dilated;

  } catch (e) {
    // Canvas security errors or other issues
    return new Array(selection.width).fill(true);
  }
};

/**
 * Main render function used by both the preview loop and the export recorder.
 */
export const renderFrame = (
  ctx: CanvasRenderingContext2D,
  image: HTMLImageElement,
  layers: Layer[],
  activeLayerId: string | null,
  timestamp: number, // current time in ms
  totalDurationMs: number
) => {
  const { width, height } = ctx.canvas;

  // 1. Draw Base Image
  ctx.clearRect(0, 0, width, height);
  ctx.drawImage(image, 0, 0, width, height);

  if (layers.length === 0) return;

  // 2. Draw Background Dimming & Vignette (With Multiple Hole Punches)
  // We use the settings from the ACTIVE layer for global background effects
  // OR just use the first layer's settings if none active. 
  // Design choice: The LAST modified layer controls the background feel.
  const activeLayer = layers.find(l => l.id === activeLayerId) || layers[layers.length - 1];
  const globalSettings = activeLayer.settings;

  ctx.save();
  ctx.beginPath();
  // Outer rect (Canvas)
  ctx.rect(0, 0, width, height);

  // Inner rects (All Layers) - Used to create holes
  layers.forEach(layer => {
    ctx.rect(layer.selection.x, layer.selection.y, layer.selection.width, layer.selection.height);
  });

  ctx.clip('evenodd');

  // Apply Background Dim
  if (globalSettings.backgroundDim > 0) {
    ctx.fillStyle = `rgba(0, 0, 0, ${globalSettings.backgroundDim})`;
    ctx.fillRect(0, 0, width, height);
  }

  // Apply Vignette
  if (globalSettings.vignette > 0) {
    const gradient = ctx.createRadialGradient(
      width / 2, height / 2, width * 0.3, // inner circle
      width / 2, height / 2, Math.max(width, height) * 0.8 // outer circle
    );
    gradient.addColorStop(0, 'rgba(0,0,0,0)');
    gradient.addColorStop(1, `rgba(0,0,0,${globalSettings.vignette})`);

    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, width, height);
  }
  ctx.restore();

  // 3. Draw Highlights/Animations for EACH layer
  layers.forEach(layer => {
    const { selection, settings } = layer;

    // Calculate Relative Time for Animation
    const delayMs = settings.delay * 1000;
    const activeTime = timestamp - delayMs;

    if (activeTime <= 0) return;

    ctx.save();
    const cycle = (activeTime / 1000) * settings.speed;

    // --- Space Skipping Logic for specific types ---
    let mask: boolean[] | null = null;
    if (settings.type === 'reading' || settings.type === 'underline') {
        mask = getCompositionMask(ctx, image, selection);
    }

    switch (settings.type) {
        case 'reading': {
            const numLines = Math.max(1, Math.ceil(selection.height / 40));
            const realLineHeight = selection.height / numLines;

            ctx.globalCompositeOperation = 'multiply'; // Blend like a highlighter
            ctx.fillStyle = settings.color;

            const activeProgress = Math.min(1, cycle);
            const totalLinesProgress = activeProgress * numLines;

            for (let i = 0; i < numLines; i++) {
                const lineProgress = Math.max(0, Math.min(1, totalLinesProgress - i));

                if (lineProgress > 0) {
                    ctx.globalAlpha = 0.6 * settings.intensity;
                    const w = selection.width * lineProgress;
                    const yPos = selection.y + (i * realLineHeight);

                    // If we have a smart mask, draw column by column
                    if (mask) {
                        for (let x = 0; x < w; x++) {
                            if (mask[x]) {
                                ctx.fillRect(selection.x + x, yPos, 1, realLineHeight);
                            }
                        }
                    } else {
                        // Fallback (include spaces)
                        ctx.fillRect(selection.x, yPos, w, realLineHeight);
                    }
                }
            }
            break;
        }

        case 'underline': {
            const lineY = selection.y + selection.height + 6;
            const progress = Math.min(1, cycle); 
            const activeProgress = progress > 1 ? 1 : progress; 

            ctx.lineWidth = 4 * settings.intensity;
            ctx.lineCap = 'round';
            ctx.strokeStyle = settings.color;
            ctx.globalAlpha = 0.9;

            const drawWidth = selection.width * activeProgress;

            if (mask) {
                ctx.beginPath();
                let isDrawing = false;
                for(let x = 0; x < drawWidth; x++) {
                    if (mask[x]) {
                        if (!isDrawing) {
                            ctx.moveTo(selection.x + x, lineY);
                            isDrawing = true;
                        }
                        ctx.lineTo(selection.x + x, lineY);
                    } else {
                        isDrawing = false; // Lift pen
                    }
                }
                ctx.stroke();
            } else {
                ctx.beginPath();
                ctx.moveTo(selection.x, lineY);
                ctx.quadraticCurveTo(
                    selection.x + drawWidth / 2, 
                    lineY + 2, 
                    selection.x + drawWidth, 
                    lineY
                );
                ctx.stroke();
            }
            break;
        }

        // --- Standard Animations (No space skipping needed) ---

        case 'pulse': {
            const alpha = 0.1 + (Math.sin(cycle * Math.PI) + 1) / 2 * (settings.intensity - 0.1);
            ctx.globalCompositeOperation = 'overlay';
            ctx.fillStyle = settings.color;
            ctx.globalAlpha = alpha;
            ctx.fillRect(selection.x, selection.y, selection.width, selection.height);

            ctx.globalCompositeOperation = 'source-over';
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 4;
            ctx.globalAlpha = alpha;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'sweep': {
            ctx.beginPath();
            ctx.rect(selection.x, selection.y, selection.width, selection.height);
            ctx.clip();
            const gradientWidth = selection.width * 0.5;
            const totalDist = selection.width + gradientWidth * 2;
            const progress = cycle; 
            const xPos = selection.x - gradientWidth + (progress * totalDist);
            const grad = ctx.createLinearGradient(xPos, selection.y, xPos + gradientWidth, selection.y);
            grad.addColorStop(0, 'rgba(255,255,255,0)');
            grad.addColorStop(0.5, settings.color);
            grad.addColorStop(1, 'rgba(255,255,255,0)');
            ctx.fillStyle = grad;
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = settings.intensity;
            ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'neon': {
            const pulseIntensity = 0.8 + (Math.sin(cycle * Math.PI * 2) * 0.2);
            ctx.globalAlpha = pulseIntensity * settings.intensity;
            ctx.shadowBlur = 20;
            ctx.shadowColor = settings.color;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 4;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            ctx.shadowBlur = 0;
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 1;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'marker': {
            ctx.beginPath();
            ctx.rect(selection.x, selection.y, selection.width, selection.height);
            ctx.clip();
            const progress = Math.min(1, cycle); 
            const w = selection.width * progress;
            ctx.fillStyle = settings.color;
            ctx.globalCompositeOperation = 'multiply'; // Better marker feel
            ctx.globalAlpha = 0.6 * settings.intensity;
            ctx.fillRect(selection.x, selection.y, w, selection.height);
            break;
        }

        case 'fade': {
            const progress = Math.min(1, cycle);
            ctx.globalAlpha = progress * settings.intensity;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 3;
            ctx.setLineDash([10, 6]);
            ctx.strokeRect(selection.x - 4, selection.y - 4, selection.width + 8, selection.height + 8);
            ctx.fillStyle = settings.color;
            ctx.globalAlpha = progress * 0.1 * settings.intensity;
            ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'focus': {
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = settings.intensity;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'circle': {
            const progress = Math.min(1, cycle * 1.5);
            const cx = selection.x + selection.width / 2;
            const cy = selection.y + selection.height / 2;
            const rx = selection.width / 2 + 10;
            const ry = selection.height / 2 + 10;
            ctx.beginPath();
            ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2);
            const len = 2 * Math.PI * Math.sqrt((rx*rx + ry*ry)/2) + 100;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 4 * settings.intensity;
            ctx.lineCap = 'round';
            ctx.setLineDash([len, len]);
            ctx.lineDashOffset = len - (progress * len);
            ctx.stroke();
            break;
        }

        case 'brackets': {
            const progress = Math.min(1, cycle);
            const pad = 10;
            const cornerLen = Math.min(selection.width, selection.height) * 0.3 * progress;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 5 * settings.intensity;
            ctx.lineCap = 'round';
            ctx.globalAlpha = Math.min(1, progress * 2);
            const x = selection.x - pad;
            const y = selection.y - pad;
            const w = selection.width + pad * 2;
            const h = selection.height + pad * 2;
            // TL
            ctx.beginPath(); ctx.moveTo(x, y + cornerLen); ctx.lineTo(x, y); ctx.lineTo(x + cornerLen, y); ctx.stroke();
            // TR
            ctx.beginPath(); ctx.moveTo(x + w - cornerLen, y); ctx.lineTo(x + w, y); ctx.lineTo(x + w, y + cornerLen); ctx.stroke();
            // BR
            ctx.beginPath(); ctx.moveTo(x + w, y + h - cornerLen); ctx.lineTo(x + w, y + h); ctx.lineTo(x + w - cornerLen, y + h); ctx.stroke();
            // BL
            ctx.beginPath(); ctx.moveTo(x + cornerLen, y + h); ctx.lineTo(x, y + h); ctx.lineTo(x, y + h - cornerLen); ctx.stroke();
            break;
        }

        case 'flash': {
            const spike = Math.max(0, 1 - (cycle * 3));
            const lingeringBorder = Math.min(1, cycle * 2);
            if (spike > 0) {
                ctx.globalCompositeOperation = 'overlay';
                ctx.fillStyle = 'white';
                ctx.globalAlpha = spike * settings.intensity;
                ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
            }
            ctx.globalCompositeOperation = 'source-over';
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 3;
            ctx.globalAlpha = lingeringBorder * settings.intensity;
            ctx.strokeRect(selection.x - 2, selection.y - 2, selection.width + 4, selection.height + 4);
            break;
        }

        case 'ripple': {
            const maxRipples = 3;
            const maxDist = 50;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 2;
            for (let i = 0; i < maxRipples; i++) {
                const offset = i * 0.5;
                let localTime = cycle - offset;
                if (localTime < 0) continue;
                const rippleProgress = localTime / 2;
                if (rippleProgress > 1) continue;
                const expansion = rippleProgress * maxDist;
                const alpha = 1 - rippleProgress;
                ctx.globalAlpha = alpha * settings.intensity;
                ctx.strokeRect(selection.x - expansion, selection.y - expansion, selection.width + expansion * 2, selection.height + expansion * 2);
            }
            break;
        }

        case 'magnify': {
            let scale = 1.0;
            const enterDuration = 0.3;
            if (cycle < enterDuration) {
                const t = cycle / enterDuration;
                scale = 1 + (Math.sin(t * Math.PI) * 0.1 * settings.intensity);
            } else {
                scale = 1.05 + Math.sin((cycle - enterDuration) * 2) * 0.02 * settings.intensity;
            }
            const w = selection.width * scale;
            const h = selection.height * scale;
            const x = selection.x - (w - selection.width) / 2;
            const y = selection.y - (h - selection.height) / 2;

            ctx.save();
            ctx.shadowColor = 'rgba(0,0,0,0.5)';
            ctx.shadowBlur = 30 * settings.intensity;
            ctx.shadowOffsetY = 15;
            ctx.fillStyle = 'white'; 
            ctx.fillRect(x, y, w, h);
            ctx.drawImage(image, selection.x, selection.y, selection.width, selection.height, x, y, w, h);
            ctx.shadowColor = 'transparent';
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 4;
            ctx.strokeRect(x, y, w, h);
            ctx.restore();
            break;
        }

        case 'rainbow': {
            const hue = (cycle * 200) % 360;
            const color = `hsl(${hue}, 100%, 60%)`;
            ctx.shadowColor = color;
            ctx.shadowBlur = 20 * settings.intensity;
            ctx.strokeStyle = color;
            ctx.lineWidth = 5 * settings.intensity;
            ctx.lineJoin = 'round';
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'glitch': {
            const offsetMax = 10 * settings.intensity;
            const step = Math.floor(cycle * 20);
            const isGlitchy = step % 5 !== 0;
            const rOffsetX = isGlitchy ? (Math.sin(step * 123) * offsetMax) : 0;
            const bOffsetX = isGlitchy ? (Math.cos(step * 321) * offsetMax) : 0;

            ctx.save();
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.8;
            ctx.strokeStyle = '#00FFFF';
            ctx.lineWidth = 3;
            ctx.strokeRect(selection.x + bOffsetX, selection.y, selection.width, selection.height);
            ctx.restore();

            ctx.save();
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.8;
            ctx.strokeStyle = '#FF0000';
            ctx.lineWidth = 3;
            ctx.strokeRect(selection.x + rOffsetX, selection.y, selection.width, selection.height);
            ctx.restore();

            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 2;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }
    }

    ctx.restore();
  });
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Selection, AnimationSettings, Layer } from '../types';
import { renderFrame } from '../utils/drawing';
import { Play } from 'lucide-react';
import { DEFAULT_SETTINGS } from '../constants';

interface EditorCanvasProps {
  imageSrc: string;
  layers: Layer[];
  activeLayerId: string | null;
  onUpdateLayer: (id: string, updates: Partial<Layer>) => void;
  onAddLayer: (layer: Layer) => void;
  onSelectLayer: (id: string | null) => void;
  canvasRef: React.RefObject<HTMLCanvasElement | null>;
}

type InteractionMode = 'create' | 'move' | 'n-resize' | 'e-resize' | 's-resize' | 'w-resize' | 'ne-resize' | 'nw-resize' | 'se-resize' | 'sw-resize' | 'none';

export const EditorCanvas: React.FC<EditorCanvasProps> = ({
  imageSrc,
  layers,
  activeLayerId,
  onUpdateLayer,
  onAddLayer,
  onSelectLayer,
  canvasRef,
}) => {
  const [image, setImage] = useState<HTMLImageElement | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [cursor, setCursor] = useState<string>('default');

  // Interaction State
  const isDragging = useRef(false);
  const interactionMode = useRef<InteractionMode>('none');
  const startPos = useRef({ x: 0, y: 0 });

  // We use this to track which layer we are manipulating during a drag
  const draggingLayerId = useRef<string | null>(null);
  const dragStartSelection = useRef<Selection | null>(null);

  // Animation State
  const requestRef = useRef<number>(0);
  const startTimeRef = useRef<number>(0);

  // 1. Load Image
  useEffect(() => {
    if (!imageSrc) return;
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = imageSrc;
    img.onload = () => {
      setImage(img);
      if(canvasRef.current) {
        canvasRef.current.width = img.width;
        canvasRef.current.height = img.height;
      }
    };
  }, [imageSrc, canvasRef]);

  // Helper: Draw Resize Handles for ACTIVE layer only
  const drawHandles = (ctx: CanvasRenderingContext2D, sel: Selection) => {
      const handleSize = 10; 
      const half = handleSize / 2;

      ctx.fillStyle = '#ffffff';
      ctx.strokeStyle = '#000000';
      ctx.lineWidth = 1;

      const points = [
          { x: sel.x, y: sel.y }, // TL
          { x: sel.x + sel.width / 2, y: sel.y }, // T
          { x: sel.x + sel.width, y: sel.y }, // TR
          { x: sel.x + sel.width, y: sel.y + sel.height / 2 }, // R
          { x: sel.x + sel.width, y: sel.y + sel.height }, // BR
          { x: sel.x + sel.width / 2, y: sel.y + sel.height }, // B
          { x: sel.x, y: sel.y + sel.height }, // BL
          { x: sel.x, y: sel.y + sel.height / 2 }, // L
      ];

      points.forEach(p => {
          ctx.beginPath();
          ctx.rect(p.x - half, p.y - half, handleSize, handleSize);
          ctx.fill();
          ctx.stroke();
      });
  };

  // 2. Main Render Loop
  const animate = useCallback((time: number) => {
    const canvas = canvasRef.current;
    if (!canvas || !image) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // We get duration from the active layer, or default
    const activeLayer = layers.find(l => l.id === activeLayerId);
    const durationMs = (activeLayer?.settings.duration || 2) * 1000;
    const loopDuration = durationMs + 2000; 

    if (startTimeRef.current === 0) {
        startTimeRef.current = time;
    }

    const elapsed = Math.max(0, time - startTimeRef.current);
    const loopTime = elapsed % loopDuration;

    // --- RENDER CONTENT ---

    // We don't want to play animation while dragging to avoid distraction/flicker
    if (isDragging.current) {
        // Static Render (show start state or just image + overlay)
        // Just use time=0 for static preview
         renderFrame(ctx, image, layers, activeLayerId, 0, durationMs);
    } else {
        renderFrame(ctx, image, layers, activeLayerId, loopTime, durationMs);
    }

    // --- DRAW UI OVERLAYS ---

    // 1. Draw border for ALL layers (faint)
    layers.forEach(layer => {
        if (layer.id !== activeLayerId) {
             ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)';
             ctx.lineWidth = 1;
             ctx.setLineDash([4, 4]);
             ctx.strokeRect(layer.selection.x, layer.selection.y, layer.selection.width, layer.selection.height);
             ctx.setLineDash([]);
        }
    });

    // 2. Draw handles and bright border for ACTIVE layer
    if (activeLayer) {
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1;
        ctx.setLineDash([4, 4]);
        ctx.strokeRect(activeLayer.selection.x, activeLayer.selection.y, activeLayer.selection.width, activeLayer.selection.height);
        ctx.setLineDash([]);

        // Only draw handles if we are not in the middle of creating it
        if (interactionMode.current !== 'create') {
            drawHandles(ctx, activeLayer.selection);
        }
    }

    requestRef.current = requestAnimationFrame(animate);
  }, [image, layers, activeLayerId, canvasRef]); 

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current);
  }, [animate]);

  // 3. Coordinate Helpers
  const getCanvasPoint = (e: React.PointerEvent<HTMLCanvasElement>) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const canvas = canvasRef.current;
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    const rawX = (e.clientX - rect.left) * scaleX;
    const rawY = (e.clientY - rect.top) * scaleY;
    return { x: rawX, y: rawY }; 
  };

  const getHitLayer = (x: number, y: number): string | null => {
      // Check active layer handles first? (Not implemented for simplicity, relying on general hit)
      // Check layers in reverse order (top first)
      for (let i = layers.length - 1; i >= 0; i--) {
          const l = layers[i];
          if (x >= l.selection.x && x <= l.selection.x + l.selection.width &&
              y >= l.selection.y && y <= l.selection.y + l.selection.height) {
              return l.id;
          }
      }
      return null;
  };

  const getInteractionType = (x: number, y: number, layer: Layer | undefined): InteractionMode => {
      if (!layer) return 'none'; // Only resize/move active layer

      const handleRadius = 20 * (canvasRef.current!.width / canvasRef.current!.getBoundingClientRect().width); 
      const { x: sx, y: sy, width: w, height: h } = layer.selection;

      // Check Handles
      if (Math.abs(x - sx) < handleRadius && Math.abs(y - sy) < handleRadius) return 'nw-resize';
      if (Math.abs(x - (sx + w)) < handleRadius && Math.abs(y - sy) < handleRadius) return 'ne-resize';
      if (Math.abs(x - (sx + w)) < handleRadius && Math.abs(y - (sy + h)) < handleRadius) return 'se-resize';
      if (Math.abs(x - sx) < handleRadius && Math.abs(y - (sy + h)) < handleRadius) return 'sw-resize';

      if (Math.abs(x - (sx + w/2)) < handleRadius && Math.abs(y - sy) < handleRadius) return 'n-resize';
      if (Math.abs(x - (sx + w)) < handleRadius && Math.abs(y - (sy + h/2)) < handleRadius) return 'e-resize';
      if (Math.abs(x - (sx + w/2)) < handleRadius && Math.abs(y - (sy + h)) < handleRadius) return 's-resize';
      if (Math.abs(x - sx) < handleRadius && Math.abs(y - (sy + h/2)) < handleRadius) return 'w-resize';

      // Check Inside
      if (x > sx && x < sx + w && y > sy && y < sy + h) return 'move';

      return 'none';
  };

  // 4. Pointer Handlers
  const onPointerDown = (e: React.PointerEvent<HTMLCanvasElement>) => {
      if (!image || !canvasRef.current) return;
      canvasRef.current.setPointerCapture(e.pointerId);

      const { x, y } = getCanvasPoint(e);

      const activeLayer = layers.find(l => l.id === activeLayerId);
      let mode = getInteractionType(x, y, activeLayer);

      // If we clicked outside the active layer (mode is none), check if we clicked ANOTHER layer
      if (mode === 'none') {
          const hitId = getHitLayer(x, y);
          if (hitId) {
              onSelectLayer(hitId);
              // Switch to move mode immediately for that new layer
              mode = 'move';
              draggingLayerId.current = hitId;
              const hitLayer = layers.find(l => l.id === hitId)!;
              dragStartSelection.current = { ...hitLayer.selection };
          } else {
              // Clicked empty space -> Create new layer
              mode = 'create';
              const newId = crypto.randomUUID();
              draggingLayerId.current = newId;
              // Add the new layer immediately
              onAddLayer({
                  id: newId,
                  selection: { x, y, width: 0, height: 0 },
                  settings: { ...DEFAULT_SETTINGS }
              });
              dragStartSelection.current = { x, y, width: 0, height: 0 };
          }
      } else {
          // Interacting with active layer
          draggingLayerId.current = activeLayerId;
          dragStartSelection.current = { ...activeLayer!.selection };
      }

      interactionMode.current = mode;
      isDragging.current = true;
      startPos.current = { x, y };
  };

  const onPointerMove = (e: React.PointerEvent<HTMLCanvasElement>) => {
      if (!image || !canvasRef.current) return;
      const { x, y } = getCanvasPoint(e);

      // A. Hover State (Update Cursor)
      if (!isDragging.current) {
          const activeLayer = layers.find(l => l.id === activeLayerId);
          const mode = getInteractionType(x, y, activeLayer);
          let cursorStyle = 'default';

          if (mode === 'none') {
             // Check if over any other layer
             if (getHitLayer(x, y)) cursorStyle = 'pointer'; 
             else cursorStyle = 'crosshair';
          } else {
            switch (mode) {
                case 'move': cursorStyle = 'move'; break;
                case 'n-resize': case 's-resize': cursorStyle = 'ns-resize'; break;
                case 'e-resize': case 'w-resize': cursorStyle = 'ew-resize'; break;
                case 'nw-resize': case 'se-resize': cursorStyle = 'nwse-resize'; break;
                case 'ne-resize': case 'sw-resize': cursorStyle = 'nesw-resize'; break;
            }
          }
          if (cursor !== cursorStyle) setCursor(cursorStyle);
          return;
      }

      // B. Drag State
      if (!draggingLayerId.current || !dragStartSelection.current) return;

      const startX = startPos.current.x;
      const startY = startPos.current.y;
      const dx = x - startX;
      const dy = y - startY;
      const initialSel = dragStartSelection.current;

      let newSel: Selection | null = null;

      if (interactionMode.current === 'create') {
          const width = Math.abs(x - startX);
          const height = Math.abs(y - startY);
          const left = Math.min(x, startX);
          const top = Math.min(y, startY);
          newSel = { x: left, y: top, width, height };
      } 
      else if (interactionMode.current === 'move') {
          newSel = {
              x: initialSel.x + dx,
              y: initialSel.y + dy,
              width: initialSel.width,
              height: initialSel.height
          };
      } 
      else {
          // Resizing Logic
          let nx = initialSel.x;
          let ny = initialSel.y;
          let nw = initialSel.width;
          let nh = initialSel.height;

          // Apply deltas
          if (interactionMode.current.includes('w')) {
              nx = Math.min(initialSel.x + dx, initialSel.x + initialSel.width);
              nw = initialSel.width - (nx - initialSel.x);
          }
          if (interactionMode.current.includes('e')) {
              nw = x - initialSel.x;
          }
          if (interactionMode.current.includes('n')) {
              ny = Math.min(initialSel.y + dy, initialSel.y + initialSel.height);
              nh = initialSel.height - (ny - initialSel.y);
          }
          if (interactionMode.current.includes('s')) {
              nh = y - initialSel.y;
          }

          if (nw < 0) { nx = nx + nw; nw = Math.abs(nw); }
          if (nh < 0) { ny = ny + nh; nh = Math.abs(nh); }

          newSel = { x: nx, y: ny, width: nw, height: nh };
      }

      onUpdateLayer(draggingLayerId.current, { selection: newSel! });
  };

  const onPointerUp = (e: React.PointerEvent<HTMLCanvasElement>) => {
      if (!isDragging.current) return;
      isDragging.current = false;

      if (canvasRef.current) {
          canvasRef.current.releasePointerCapture(e.pointerId);
      }

      // Cleanup tiny layers created by accident
      const layer = layers.find(l => l.id === draggingLayerId.current);
      if (layer && (layer.selection.width < 5 || layer.selection.height < 5)) {
          // This creates a circular dependency if we delete from here, but the parent handles updates
          // For now, let's just leave it or notify parent to delete.
          // Better: The updateLayer was already called, we might need a delete callback.
          // Implementing deletion via parent checking size or manual button is safer.
      } else {
         startTimeRef.current = performance.now(); // Restart animation
      }

      interactionMode.current = 'none';
      draggingLayerId.current = null;
  };

  return (
    <div 
      ref={containerRef} 
      className="relative w-full h-full flex items-center justify-center bg-zinc-900 overflow-hidden select-none p-4 lg:p-8"
    >
      {!image && (
         <div className="text-zinc-500 flex flex-col items-center animate-pulse gap-4">
             <div className="w-16 h-16 border-2 border-dashed border-zinc-700 rounded-xl flex items-center justify-center">
                 <Play size={24} className="opacity-20" />
             </div>
            <p className="text-sm font-medium">Upload an image to start</p>
         </div>
      )}

      <div className="relative shadow-2xl shadow-black/50 flex justify-center items-center" style={{ maxWidth: '100%', maxHeight: '100%' }}>
          <canvas
            ref={canvasRef}
            className={`block object-contain max-w-full max-h-full`}
            style={{ 
                touchAction: 'none', 
                maxWidth: '100%', 
                maxHeight: '100%',
                cursor: cursor 
            }}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={onPointerUp}
            onPointerCancel={onPointerUp}
            onPointerLeave={onPointerUp}
          />
      </div>
    </div>
  );
};

