import React, { useState, useRef, useCallback } from 'react';
import { Sidebar } from './components/Sidebar';
import { EditorCanvas } from './components/EditorCanvas';
import { Controls } from './components/Controls';
import { useCanvasRecorder } from './hooks/useCanvasRecorder';
import { AnimationSettings, Layer } from './types';
import { DEFAULT_SETTINGS } from './constants';

const App = () => {
  const [imageSrc, setImageSrc] = useState<string | null>(null);

  // State for multiple layers
  const [layers, setLayers] = useState<Layer[]>([]);
  const [activeLayerId, setActiveLayerId] = useState<string | null>(null);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const { isRecording, progress, exportVideo } = useCanvasRecorder();

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setImageSrc(event.target?.result as string);
        setLayers([]); // Clear old selections
        setActiveLayerId(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const updateActiveSettings = useCallback((partial: Partial<AnimationSettings>) => {
    if (!activeLayerId) return;
    setLayers(prev => prev.map(layer => 
      layer.id === activeLayerId 
        ? { ...layer, settings: { ...layer.settings, ...partial } } 
        : layer
    ));
  }, [activeLayerId]);

  const handleUpdateLayer = (id: string, updates: Partial<Layer>) => {
      setLayers(prev => prev.map(l => l.id === id ? { ...l, ...updates } : l));
  };

  const handleAddLayer = (newLayer: Layer) => {
      setLayers(prev => [...prev, newLayer]);
      setActiveLayerId(newLayer.id);
  };

  const handleDeleteActiveLayer = () => {
      if (!activeLayerId) return;
      setLayers(prev => prev.filter(l => l.id !== activeLayerId));
      setActiveLayerId(null);
  };

  const handleExport = async () => {
    if (!canvasRef.current || !imageSrc || layers.length === 0) return;

    const img = new Image();
    img.src = imageSrc;
    await img.decode(); 

    try {
      // Find the max duration among all layers to determine video length
      const maxDuration = Math.max(...layers.map(l => l.settings.duration), 2);

      await exportVideo(canvasRef.current, img, layers, activeLayerId, maxDuration);
    } catch (err) {
      console.error("Export failed", err);
      alert("Failed to export video. Please try again.");
    }
  };

  // Get active settings or default for display
  const activeSettings = layers.find(l => l.id === activeLayerId)?.settings || DEFAULT_SETTINGS;

  return (
    <div className="h-[100dvh] w-full flex flex-col lg:flex-row bg-zinc-950 text-white font-sans overflow-hidden">
      {/* Sidebar - Tools & Upload (Top on mobile, Left on Desktop) */}
      <Sidebar 
        onImageUpload={handleImageUpload} 
        onClearSelection={() => setLayers([])} 
      />

      {/* Center - Canvas Workspace */}
      <div className="flex-1 flex flex-col min-w-0 bg-zinc-900/50 relative order-2 lg:order-none overflow-hidden">
          <EditorCanvas 
            imageSrc={imageSrc || ''}
            layers={layers}
            activeLayerId={activeLayerId}
            onUpdateLayer={handleUpdateLayer}
            onAddLayer={handleAddLayer}
            onSelectLayer={setActiveLayerId}
            canvasRef={canvasRef}
          />
      </div>

      {/* Right Sidebar - Properties (Bottom on mobile, Right on Desktop) */}
      <Controls 
          settings={activeSettings}
          updateSettings={updateActiveSettings}
          onExport={handleExport}
          onClearSelection={handleDeleteActiveLayer}
          isRecording={isRecording}
          progress={progress}
          hasSelection={!!activeLayerId}
      />
    </div>
  );
};

export default App;

import { useState, useCallback } from 'react';
import { renderFrame } from '../utils/drawing';
import { Layer } from '../types';

export const useCanvasRecorder = () => {
  const [isRecording, setIsRecording] = useState(false);
  const [progress, setProgress] = useState(0);

  const exportVideo = useCallback(async (
    sourceCanvas: HTMLCanvasElement,
    image: HTMLImageElement,
    layers: Layer[],
    activeLayerId: string | null,
    totalDuration: number
  ) => {
    return new Promise<void>((resolve, reject) => {
      setIsRecording(true);
      setProgress(0);

      const canvas = document.createElement('canvas');
      canvas.width = sourceCanvas.width;
      canvas.height = sourceCanvas.height;
      const ctx = canvas.getContext('2d');

      if (!ctx) {
        setIsRecording(false);
        reject(new Error("Could not create canvas context"));
        return;
      }

      // Determine supported MIME type
      const types = [
        'video/webm;codecs=vp9',
        'video/webm;codecs=h264',
        'video/webm',
        'video/mp4' // Safari support
      ];
      const mimeType = types.find(t => MediaRecorder.isTypeSupported(t)) || '';

      if (!mimeType) {
        setIsRecording(false);
        alert("Video recording is not supported in this browser.");
        reject(new Error("No supported mime type"));
        return;
      }

      // Initial render to ensure canvas isn't empty when stream starts
      renderFrame(ctx, image, layers, activeLayerId, 0, totalDuration * 1000);

      const stream = canvas.captureStream(30); // 30 FPS
      const recorder = new MediaRecorder(stream, {
        mimeType,
        videoBitsPerSecond: 8000000 // 8 Mbps for better quality
      });

      const chunks: Blob[] = [];
      recorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.push(e.data);
      };

      recorder.onstop = () => {
        const type = mimeType.split(';')[0];
        const ext = type.includes('mp4') ? 'mp4' : 'webm';
        const blob = new Blob(chunks, { type });
        const url = URL.createObjectURL(blob);

        const a = document.createElement('a');
        a.href = url;
        a.download = `highlight-video.${ext}`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);

        setIsRecording(false);
        resolve();
      };

      recorder.start();

      const startTime = performance.now();
      const durationMs = totalDuration * 1000;

      const processFrame = (now: number) => {
        const elapsed = now - startTime;

        // Update progress UI
        setProgress(Math.min(100, Math.round((elapsed / durationMs) * 100)));

        // We render WITHOUT the active UI selection outlines for the final video
        renderFrame(ctx, image, layers, null, elapsed, durationMs);

        // Record a tiny bit extra (100ms) to prevent cutting off the end abruptly
        if (elapsed < durationMs + 100) {
          requestAnimationFrame(processFrame);
        } else {
          recorder.stop();
        }
      };

      requestAnimationFrame(processFrame);
    });
  }, []);

  return { isRecording, progress, exportVideo };
};

import { AnimationSettings, Layer, Selection } from '../types';

/**
 * Helper: Analyzes pixel data to find where text exists vs whitespace.
 * Returns an array of booleans (true = content, false = space) for each X coordinate.
 */
const getCompositionMask = (
  ctx: CanvasRenderingContext2D,
  image: HTMLImageElement,
  selection: Selection
): boolean[] => {
  // Optimization: For very large selections, we might want to downsample, 
  // but for typical text highlights, full res is fine.

  // We need to draw the source image to a temp canvas to read pixel data safely
  // if the main ctx is already dirty. However, renderFrame clears ctx first.
  // We can read directly from the main ctx since the base image is drawn first.

  try {
    const imageData = ctx.getImageData(selection.x, selection.y, selection.width, selection.height);
    const data = imageData.data;
    const width = imageData.width;
    const height = imageData.height;
    const hasContent = new Array(width).fill(false);

    // Threshold for "darkness" (assuming text is darker than background)
    // Or "variance" from background. Let's assume white/light background for now.
    // A pixel is "content" if it's significantly darker than white.
    const threshold = 230; 

    for (let x = 0; x < width; x++) {
      let darkPixelsInColumn = 0;
      for (let y = 0; y < height; y++) {
        const idx = (y * width + x) * 4;
        const r = data[idx];
        const g = data[idx + 1];
        const b = data[idx + 2];
        const a = data[idx + 3];

        // Simple brightness check
        const brightness = (r + g + b) / 3;

        if (a > 20 && brightness < threshold) {
          darkPixelsInColumn++;
        }
      }
      // If a column has enough dark pixels, it's part of a character
      if (darkPixelsInColumn > 0) {
        hasContent[x] = true;
      }
    }

    // Dilate (expand) the mask slightly to connect letters within a word
    // but keep gaps between words
    const dilated = [...hasContent];
    const gapThreshold = 4; // If a gap is smaller than this, fill it (it's space between letters, not words)

    let currentGap = 0;
    for(let x=0; x<width; x++) {
        if (!hasContent[x]) {
            currentGap++;
        } else {
            if (currentGap > 0 && currentGap < gapThreshold) {
                // Backfill small gaps
                for(let k=1; k<=currentGap; k++) dilated[x-k] = true;
            }
            currentGap = 0;
        }
    }

    return dilated;

  } catch (e) {
    // Canvas security errors or other issues
    return new Array(selection.width).fill(true);
  }
};

/**
 * Main render function used by both the preview loop and the export recorder.
 */
export const renderFrame = (
  ctx: CanvasRenderingContext2D,
  image: HTMLImageElement,
  layers: Layer[],
  activeLayerId: string | null,
  timestamp: number, // current time in ms
  totalDurationMs: number
) => {
  const { width, height } = ctx.canvas;

  // 1. Draw Base Image
  ctx.clearRect(0, 0, width, height);
  ctx.drawImage(image, 0, 0, width, height);

  if (layers.length === 0) return;

  // 2. Draw Background Dimming & Vignette (With Multiple Hole Punches)
  // We use the settings from the ACTIVE layer for global background effects
  // OR just use the first layer's settings if none active. 
  // Design choice: The LAST modified layer controls the background feel.
  const activeLayer = layers.find(l => l.id === activeLayerId) || layers[layers.length - 1];
  const globalSettings = activeLayer.settings;

  ctx.save();
  ctx.beginPath();
  // Outer rect (Canvas)
  ctx.rect(0, 0, width, height);

  // Inner rects (All Layers) - Used to create holes
  layers.forEach(layer => {
    ctx.rect(layer.selection.x, layer.selection.y, layer.selection.width, layer.selection.height);
  });

  ctx.clip('evenodd');

  // Apply Background Dim
  if (globalSettings.backgroundDim > 0) {
    ctx.fillStyle = `rgba(0, 0, 0, ${globalSettings.backgroundDim})`;
    ctx.fillRect(0, 0, width, height);
  }

  // Apply Vignette
  if (globalSettings.vignette > 0) {
    const gradient = ctx.createRadialGradient(
      width / 2, height / 2, width * 0.3, // inner circle
      width / 2, height / 2, Math.max(width, height) * 0.8 // outer circle
    );
    gradient.addColorStop(0, 'rgba(0,0,0,0)');
    gradient.addColorStop(1, `rgba(0,0,0,${globalSettings.vignette})`);

    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, width, height);
  }
  ctx.restore();

  // 3. Draw Highlights/Animations for EACH layer
  layers.forEach(layer => {
    const { selection, settings } = layer;

    // Calculate Relative Time for Animation
    const delayMs = settings.delay * 1000;
    const activeTime = timestamp - delayMs;

    if (activeTime <= 0) return;

    ctx.save();
    const cycle = (activeTime / 1000) * settings.speed;

    // --- Space Skipping Logic for specific types ---
    let mask: boolean[] | null = null;
    if (settings.type === 'reading' || settings.type === 'underline') {
        mask = getCompositionMask(ctx, image, selection);
    }

    switch (settings.type) {
        case 'reading': {
            const numLines = Math.max(1, Math.ceil(selection.height / 40));
            const realLineHeight = selection.height / numLines;

            ctx.globalCompositeOperation = 'multiply'; // Blend like a highlighter
            ctx.fillStyle = settings.color;

            const activeProgress = Math.min(1, cycle);
            const totalLinesProgress = activeProgress * numLines;

            for (let i = 0; i < numLines; i++) {
                const lineProgress = Math.max(0, Math.min(1, totalLinesProgress - i));

                if (lineProgress > 0) {
                    ctx.globalAlpha = 0.6 * settings.intensity;
                    const w = selection.width * lineProgress;
                    const yPos = selection.y + (i * realLineHeight);

                    // If we have a smart mask, draw column by column
                    if (mask) {
                        for (let x = 0; x < w; x++) {
                            if (mask[x]) {
                                ctx.fillRect(selection.x + x, yPos, 1, realLineHeight);
                            }
                        }
                    } else {
                        // Fallback (include spaces)
                        ctx.fillRect(selection.x, yPos, w, realLineHeight);
                    }
                }
            }
            break;
        }

        case 'underline': {
            // Multi-line aware underline
            const numLines = Math.max(1, Math.ceil(selection.height / 40));
            const realLineHeight = selection.height / numLines;

            ctx.lineWidth = 3 * settings.intensity;
            ctx.lineCap = 'round';
            ctx.strokeStyle = settings.color;
            ctx.globalAlpha = 0.9;

            const activeProgress = Math.min(1, cycle);
            const totalLinesProgress = activeProgress * numLines;

            for (let i = 0; i < numLines; i++) {
                const lineProgress = Math.max(0, Math.min(1, totalLinesProgress - i));

                if (lineProgress > 0) {
                     const lineY = selection.y + ((i + 1) * realLineHeight) - 4;
                     const drawWidth = selection.width * lineProgress;

                     if (mask) {
                        ctx.beginPath();
                        let isDrawing = false;
                        for(let x = 0; x < drawWidth; x++) {
                            if (mask[x]) {
                                if (!isDrawing) {
                                    ctx.moveTo(selection.x + x, lineY);
                                    isDrawing = true;
                                }
                                ctx.lineTo(selection.x + x, lineY);
                            } else {
                                isDrawing = false; 
                            }
                        }
                        ctx.stroke();
                     } else {
                        ctx.beginPath();
                        ctx.moveTo(selection.x, lineY);
                        ctx.quadraticCurveTo(
                            selection.x + drawWidth / 2, 
                            lineY + 1.5, 
                            selection.x + drawWidth, 
                            lineY
                        );
                        ctx.stroke();
                     }
                }
            }
            break;
        }

        // --- Standard Animations (No space skipping needed) ---

        case 'pulse': {
            const alpha = 0.1 + (Math.sin(cycle * Math.PI) + 1) / 2 * (settings.intensity - 0.1);
            ctx.globalCompositeOperation = 'overlay';
            ctx.fillStyle = settings.color;
            ctx.globalAlpha = alpha;
            ctx.fillRect(selection.x, selection.y, selection.width, selection.height);

            ctx.globalCompositeOperation = 'source-over';
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 4;
            ctx.globalAlpha = alpha;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'sweep': {
            ctx.beginPath();
            ctx.rect(selection.x, selection.y, selection.width, selection.height);
            ctx.clip();
            const gradientWidth = selection.width * 0.5;
            const totalDist = selection.width + gradientWidth * 2;
            const progress = cycle; 
            const xPos = selection.x - gradientWidth + (progress * totalDist);
            const grad = ctx.createLinearGradient(xPos, selection.y, xPos + gradientWidth, selection.y);
            grad.addColorStop(0, 'rgba(255,255,255,0)');
            grad.addColorStop(0.5, settings.color);
            grad.addColorStop(1, 'rgba(255,255,255,0)');
            ctx.fillStyle = grad;
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = settings.intensity;
            ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'neon': {
            const pulseIntensity = 0.8 + (Math.sin(cycle * Math.PI * 2) * 0.2);
            ctx.globalAlpha = pulseIntensity * settings.intensity;
            ctx.shadowBlur = 20;
            ctx.shadowColor = settings.color;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 4;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            ctx.shadowBlur = 0;
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 1;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'marker': {
            ctx.beginPath();
            ctx.rect(selection.x, selection.y, selection.width, selection.height);
            ctx.clip();
            const progress = Math.min(1, cycle); 
            const w = selection.width * progress;
            ctx.fillStyle = settings.color;
            ctx.globalCompositeOperation = 'multiply'; // Better marker feel
            ctx.globalAlpha = 0.6 * settings.intensity;
            ctx.fillRect(selection.x, selection.y, w, selection.height);
            break;
        }

        case 'fade': {
            const progress = Math.min(1, cycle);
            ctx.globalAlpha = progress * settings.intensity;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 3;
            ctx.setLineDash([10, 6]);
            ctx.strokeRect(selection.x - 4, selection.y - 4, selection.width + 8, selection.height + 8);
            ctx.fillStyle = settings.color;
            ctx.globalAlpha = progress * 0.1 * settings.intensity;
            ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'focus': {
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = settings.intensity;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'circle': {
            const progress = Math.min(1, cycle * 1.5);
            const cx = selection.x + selection.width / 2;
            const cy = selection.y + selection.height / 2;
            const rx = selection.width / 2 + 10;
            const ry = selection.height / 2 + 10;
            ctx.beginPath();
            ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2);
            const len = 2 * Math.PI * Math.sqrt((rx*rx + ry*ry)/2) + 100;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 4 * settings.intensity;
            ctx.lineCap = 'round';
            ctx.setLineDash([len, len]);
            ctx.lineDashOffset = len - (progress * len);
            ctx.stroke();
            break;
        }

        case 'brackets': {
            const progress = Math.min(1, cycle);
            const pad = 10;
            const cornerLen = Math.min(selection.width, selection.height) * 0.3 * progress;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 5 * settings.intensity;
            ctx.lineCap = 'round';
            ctx.globalAlpha = Math.min(1, progress * 2);
            const x = selection.x - pad;
            const y = selection.y - pad;
            const w = selection.width + pad * 2;
            const h = selection.height + pad * 2;
            // TL
            ctx.beginPath(); ctx.moveTo(x, y + cornerLen); ctx.lineTo(x, y); ctx.lineTo(x + cornerLen, y); ctx.stroke();
            // TR
            ctx.beginPath(); ctx.moveTo(x + w - cornerLen, y); ctx.lineTo(x + w, y); ctx.lineTo(x + w, y + cornerLen); ctx.stroke();
            // BR
            ctx.beginPath(); ctx.moveTo(x + w, y + h - cornerLen); ctx.lineTo(x + w, y + h); ctx.lineTo(x + w - cornerLen, y + h); ctx.stroke();
            // BL
            ctx.beginPath(); ctx.moveTo(x + cornerLen, y + h); ctx.lineTo(x, y + h); ctx.lineTo(x, y + h - cornerLen); ctx.stroke();
            break;
        }

        case 'flash': {
            const spike = Math.max(0, 1 - (cycle * 3));
            const lingeringBorder = Math.min(1, cycle * 2);
            if (spike > 0) {
                ctx.globalCompositeOperation = 'overlay';
                ctx.fillStyle = 'white';
                ctx.globalAlpha = spike * settings.intensity;
                ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
            }
            ctx.globalCompositeOperation = 'source-over';
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 3;
            ctx.globalAlpha = lingeringBorder * settings.intensity;
            ctx.strokeRect(selection.x - 2, selection.y - 2, selection.width + 4, selection.height + 4);
            break;
        }

        case 'ripple': {
            const maxRipples = 3;
            const maxDist = 50;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 2;
            for (let i = 0; i < maxRipples; i++) {
                const offset = i * 0.5;
                let localTime = cycle - offset;
                if (localTime < 0) continue;
                const rippleProgress = localTime / 2;
                if (rippleProgress > 1) continue;
                const expansion = rippleProgress * maxDist;
                const alpha = 1 - rippleProgress;
                ctx.globalAlpha = alpha * settings.intensity;
                ctx.strokeRect(selection.x - expansion, selection.y - expansion, selection.width + expansion * 2, selection.height + expansion * 2);
            }
            break;
        }

        case 'magnify': {
            let scale = 1.0;
            const enterDuration = 0.3;
            if (cycle < enterDuration) {
                const t = cycle / enterDuration;
                scale = 1 + (Math.sin(t * Math.PI) * 0.1 * settings.intensity);
            } else {
                scale = 1.05 + Math.sin((cycle - enterDuration) * 2) * 0.02 * settings.intensity;
            }
            const w = selection.width * scale;
            const h = selection.height * scale;
            const x = selection.x - (w - selection.width) / 2;
            const y = selection.y - (h - selection.height) / 2;

            ctx.save();
            ctx.shadowColor = 'rgba(0,0,0,0.5)';
            ctx.shadowBlur = 30 * settings.intensity;
            ctx.shadowOffsetY = 15;
            ctx.fillStyle = 'white'; 
            ctx.fillRect(x, y, w, h);
            ctx.drawImage(image, selection.x, selection.y, selection.width, selection.height, x, y, w, h);
            ctx.shadowColor = 'transparent';
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 4;
            ctx.strokeRect(x, y, w, h);
            ctx.restore();
            break;
        }

        case 'rainbow': {
            const hue = (cycle * 200) % 360;
            const color = `hsl(${hue}, 100%, 60%)`;
            ctx.shadowColor = color;
            ctx.shadowBlur = 20 * settings.intensity;
            ctx.strokeStyle = color;
            ctx.lineWidth = 5 * settings.intensity;
            ctx.lineJoin = 'round';
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'glitch': {
            const offsetMax = 10 * settings.intensity;
            const step = Math.floor(cycle * 20);
            const isGlitchy = step % 5 !== 0;
            const rOffsetX = isGlitchy ? (Math.sin(step * 123) * offsetMax) : 0;
            const bOffsetX = isGlitchy ? (Math.cos(step * 321) * offsetMax) : 0;

            ctx.save();
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.8;
            ctx.strokeStyle = '#00FFFF';
            ctx.lineWidth = 3;
            ctx.strokeRect(selection.x + bOffsetX, selection.y, selection.width, selection.height);
            ctx.restore();

            ctx.save();
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.8;
            ctx.strokeStyle = '#FF0000';
            ctx.lineWidth = 3;
            ctx.strokeRect(selection.x + rOffsetX, selection.y, selection.width, selection.height);
            ctx.restore();

            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 2;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }
    }

    ctx.restore();
  });
};

export type AnimationType = 'pulse' | 'sweep' | 'neon' | 'focus' | 'underline' | 'marker' | 'fade' | 'circle' | 'brackets' | 'flash' | 'ripple' | 'magnify' | 'glitch' | 'rainbow' | 'reading' | 'rectangle' | 'strike' | 'squiggle';

export interface Selection {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface AnimationSettings {
  type: AnimationType;
  color: string;
  intensity: number; // 0 to 1
  speed: number; // Multiplier
  delay: number; // Seconds
  duration: number; // Seconds (video length)
  backgroundDim: number; // 0 to 1
  vignette: number; // 0 to 1
}

export interface Layer {
  id: string;
  selection: Selection;
  settings: AnimationSettings;
}

export interface VideoExportOptions {
  width: number;
  height: number;
  fps: number;
}

import { AnimationSettings, Layer, Selection } from '../types';

/**
 * Helper: Analyzes pixel data to find where text exists vs whitespace.
 * Returns an array of booleans (true = content, false = space) for each X coordinate.
 */
const getCompositionMask = (
  ctx: CanvasRenderingContext2D,
  image: HTMLImageElement,
  selection: Selection
): boolean[] => {
  try {
    const imageData = ctx.getImageData(selection.x, selection.y, selection.width, selection.height);
    const data = imageData.data;
    const width = imageData.width;
    const height = imageData.height;
    const hasContent = new Array(width).fill(false);

    const threshold = 230; 

    for (let x = 0; x < width; x++) {
      let darkPixelsInColumn = 0;
      for (let y = 0; y < height; y++) {
        const idx = (y * width + x) * 4;
        const r = data[idx];
        const g = data[idx + 1];
        const b = data[idx + 2];
        const a = data[idx + 3];

        const brightness = (r + g + b) / 3;

        if (a > 20 && brightness < threshold) {
          darkPixelsInColumn++;
        }
      }
      if (darkPixelsInColumn > 0) {
        hasContent[x] = true;
      }
    }

    const dilated = [...hasContent];
    const gapThreshold = 4;

    let currentGap = 0;
    for(let x=0; x<width; x++) {
        if (!hasContent[x]) {
            currentGap++;
        } else {
            if (currentGap > 0 && currentGap < gapThreshold) {
                for(let k=1; k<=currentGap; k++) dilated[x-k] = true;
            }
            currentGap = 0;
        }
    }

    return dilated;

  } catch (e) {
    return new Array(selection.width).fill(true);
  }
};

/**
 * Main render function used by both the preview loop and the export recorder.
 */
export const renderFrame = (
  ctx: CanvasRenderingContext2D,
  image: HTMLImageElement,
  layers: Layer[],
  activeLayerId: string | null,
  timestamp: number, // current time in ms
  totalDurationMs: number
) => {
  const { width, height } = ctx.canvas;

  // 1. Draw Base Image
  ctx.clearRect(0, 0, width, height);
  ctx.drawImage(image, 0, 0, width, height);

  if (layers.length === 0) return;

  // 2. Draw Background Dimming & Vignette
  const activeLayer = layers.find(l => l.id === activeLayerId) || layers[layers.length - 1];
  const globalSettings = activeLayer.settings;

  ctx.save();
  ctx.beginPath();
  ctx.rect(0, 0, width, height);

  layers.forEach(layer => {
    ctx.rect(layer.selection.x, layer.selection.y, layer.selection.width, layer.selection.height);
  });

  ctx.clip('evenodd');

  if (globalSettings.backgroundDim > 0) {
    ctx.fillStyle = `rgba(0, 0, 0, ${globalSettings.backgroundDim})`;
    ctx.fillRect(0, 0, width, height);
  }

  if (globalSettings.vignette > 0) {
    const gradient = ctx.createRadialGradient(
      width / 2, height / 2, width * 0.3, 
      width / 2, height / 2, Math.max(width, height) * 0.8 
    );
    gradient.addColorStop(0, 'rgba(0,0,0,0)');
    gradient.addColorStop(1, `rgba(0,0,0,${globalSettings.vignette})`);

    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, width, height);
  }
  ctx.restore();

  // 3. Draw Highlights/Animations
  layers.forEach(layer => {
    const { selection, settings } = layer;
    const delayMs = settings.delay * 1000;
    const activeTime = timestamp - delayMs;

    if (activeTime <= 0) return;

    ctx.save();
    const cycle = (activeTime / 1000) * settings.speed;

    // Determine if we need space skipping
    const needsMask = ['reading', 'underline', 'strike', 'squiggle'].includes(settings.type);
    let mask: boolean[] | null = null;
    if (needsMask) {
        mask = getCompositionMask(ctx, image, selection);
    }

    switch (settings.type) {
        case 'rectangle': {
            // Box Drawing Effect
            const p = (selection.width + selection.height) * 2;
            const progress = Math.min(1, cycle); 

            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 4 * settings.intensity;
            ctx.lineJoin = 'miter';

            // Draw stroke using dash offset
            ctx.setLineDash([p, p]);
            ctx.lineDashOffset = p + (progress * p); // Start from offset p (hidden) to 0 (shown)? 
            // Standard: dash=p, gap=p. offset=p means start at gap. decrease offset to show line.
            ctx.lineDashOffset = p * (1 - progress); 

            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'reading': {
            const numLines = Math.max(1, Math.ceil(selection.height / 40));
            const realLineHeight = selection.height / numLines;

            ctx.globalCompositeOperation = 'multiply'; 
            ctx.fillStyle = settings.color;

            const activeProgress = Math.min(1, cycle);
            const totalLinesProgress = activeProgress * numLines;

            for (let i = 0; i < numLines; i++) {
                const lineProgress = Math.max(0, Math.min(1, totalLinesProgress - i));
                if (lineProgress > 0) {
                    ctx.globalAlpha = 0.6 * settings.intensity;
                    const w = selection.width * lineProgress;
                    const yPos = selection.y + (i * realLineHeight);

                    if (mask) {
                        for (let x = 0; x < w; x++) {
                            if (mask[x]) ctx.fillRect(selection.x + x, yPos, 1, realLineHeight);
                        }
                    } else {
                        ctx.fillRect(selection.x, yPos, w, realLineHeight);
                    }
                }
            }
            break;
        }

        case 'underline': {
            const numLines = Math.max(1, Math.ceil(selection.height / 40));
            const realLineHeight = selection.height / numLines;

            ctx.lineWidth = 3 * settings.intensity;
            ctx.lineCap = 'round';
            ctx.strokeStyle = settings.color;
            ctx.globalAlpha = 0.9;

            const activeProgress = Math.min(1, cycle);
            const totalLinesProgress = activeProgress * numLines;

            for (let i = 0; i < numLines; i++) {
                const lineProgress = Math.max(0, Math.min(1, totalLinesProgress - i));
                if (lineProgress > 0) {
                     const lineY = selection.y + ((i + 1) * realLineHeight) - 4;
                     const drawWidth = selection.width * lineProgress;

                     if (mask) {
                        ctx.beginPath();
                        let isDrawing = false;
                        for(let x = 0; x < drawWidth; x++) {
                            if (mask[x]) {
                                if (!isDrawing) { ctx.moveTo(selection.x + x, lineY); isDrawing = true; }
                                ctx.lineTo(selection.x + x, lineY);
                            } else { isDrawing = false; }
                        }
                        ctx.stroke();
                     } else {
                        ctx.beginPath();
                        ctx.moveTo(selection.x, lineY);
                        ctx.quadraticCurveTo(selection.x + drawWidth/2, lineY + 1.5, selection.x + drawWidth, lineY);
                        ctx.stroke();
                     }
                }
            }
            break;
        }

        case 'strike': {
            const numLines = Math.max(1, Math.ceil(selection.height / 40));
            const realLineHeight = selection.height / numLines;

            ctx.lineWidth = 3 * settings.intensity;
            ctx.lineCap = 'round';
            ctx.strokeStyle = settings.color;
            ctx.globalAlpha = 0.8;

            const activeProgress = Math.min(1, cycle);
            const totalLinesProgress = activeProgress * numLines;

            for (let i = 0; i < numLines; i++) {
                const lineProgress = Math.max(0, Math.min(1, totalLinesProgress - i));
                if (lineProgress > 0) {
                     // Center of the line
                     const lineY = selection.y + (i * realLineHeight) + (realLineHeight / 2);
                     const drawWidth = selection.width * lineProgress;

                     if (mask) {
                        ctx.beginPath();
                        let isDrawing = false;
                        for(let x = 0; x < drawWidth; x++) {
                            if (mask[x]) {
                                if (!isDrawing) { ctx.moveTo(selection.x + x, lineY); isDrawing = true; }
                                ctx.lineTo(selection.x + x, lineY);
                            } else { isDrawing = false; }
                        }
                        ctx.stroke();
                     } else {
                        ctx.beginPath();
                        ctx.moveTo(selection.x, lineY);
                        ctx.lineTo(selection.x + drawWidth, lineY);
                        ctx.stroke();
                     }
                }
            }
            break;
        }

        case 'squiggle': {
            const numLines = Math.max(1, Math.ceil(selection.height / 40));
            const realLineHeight = selection.height / numLines;

            ctx.lineWidth = 2 * settings.intensity;
            ctx.lineCap = 'round';
            ctx.strokeStyle = settings.color;
            ctx.globalAlpha = 0.9;

            const activeProgress = Math.min(1, cycle);
            const totalLinesProgress = activeProgress * numLines;

            // Wave parameters
            const freq = 0.3;
            const amp = 3;

            for (let i = 0; i < numLines; i++) {
                const lineProgress = Math.max(0, Math.min(1, totalLinesProgress - i));
                if (lineProgress > 0) {
                     const baseY = selection.y + ((i + 1) * realLineHeight) - 4;
                     const drawWidth = selection.width * lineProgress;

                     ctx.beginPath();
                     let isDrawing = false;

                     for(let x = 0; x < drawWidth; x++) {
                        const waveY = baseY + Math.sin(x * freq) * amp;

                        // Smart masking check
                        if (!mask || mask[Math.floor(x)]) {
                            if (!isDrawing) {
                                ctx.moveTo(selection.x + x, waveY);
                                isDrawing = true;
                            } else {
                                ctx.lineTo(selection.x + x, waveY);
                            }
                        } else {
                            isDrawing = false;
                        }
                     }
                     ctx.stroke();
                }
            }
            break;
        }

        case 'pulse': {
            const alpha = 0.1 + (Math.sin(cycle * Math.PI) + 1) / 2 * (settings.intensity - 0.1);
            ctx.globalCompositeOperation = 'overlay';
            ctx.fillStyle = settings.color;
            ctx.globalAlpha = alpha;
            ctx.fillRect(selection.x, selection.y, selection.width, selection.height);

            ctx.globalCompositeOperation = 'source-over';
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 4;
            ctx.globalAlpha = alpha;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'sweep': {
            ctx.beginPath();
            ctx.rect(selection.x, selection.y, selection.width, selection.height);
            ctx.clip();
            const gradientWidth = selection.width * 0.5;
            const totalDist = selection.width + gradientWidth * 2;
            const progress = cycle; 
            const xPos = selection.x - gradientWidth + (progress * totalDist);
            const grad = ctx.createLinearGradient(xPos, selection.y, xPos + gradientWidth, selection.y);
            grad.addColorStop(0, 'rgba(255,255,255,0)');
            grad.addColorStop(0.5, settings.color);
            grad.addColorStop(1, 'rgba(255,255,255,0)');
            ctx.fillStyle = grad;
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = settings.intensity;
            ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'neon': {
            const pulseIntensity = 0.8 + (Math.sin(cycle * Math.PI * 2) * 0.2);
            ctx.globalAlpha = pulseIntensity * settings.intensity;
            ctx.shadowBlur = 20;
            ctx.shadowColor = settings.color;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 4;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            ctx.shadowBlur = 0;
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 1;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'marker': {
            ctx.beginPath();
            ctx.rect(selection.x, selection.y, selection.width, selection.height);
            ctx.clip();
            const progress = Math.min(1, cycle); 
            const w = selection.width * progress;
            ctx.fillStyle = settings.color;
            ctx.globalCompositeOperation = 'multiply'; 
            ctx.globalAlpha = 0.6 * settings.intensity;
            ctx.fillRect(selection.x, selection.y, w, selection.height);
            break;
        }

        case 'fade': {
            const progress = Math.min(1, cycle);
            ctx.globalAlpha = progress * settings.intensity;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 3;
            ctx.setLineDash([10, 6]);
            ctx.strokeRect(selection.x - 4, selection.y - 4, selection.width + 8, selection.height + 8);
            ctx.fillStyle = settings.color;
            ctx.globalAlpha = progress * 0.1 * settings.intensity;
            ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'focus': {
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = settings.intensity;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'circle': {
            const progress = Math.min(1, cycle * 1.5);
            const cx = selection.x + selection.width / 2;
            const cy = selection.y + selection.height / 2;
            const rx = selection.width / 2 + 10;
            const ry = selection.height / 2 + 10;
            ctx.beginPath();
            ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2);
            const len = 2 * Math.PI * Math.sqrt((rx*rx + ry*ry)/2) + 100;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 4 * settings.intensity;
            ctx.lineCap = 'round';
            ctx.setLineDash([len, len]);
            ctx.lineDashOffset = len - (progress * len);
            ctx.stroke();
            break;
        }

        case 'brackets': {
            const progress = Math.min(1, cycle);
            const pad = 10;
            const cornerLen = Math.min(selection.width, selection.height) * 0.3 * progress;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 5 * settings.intensity;
            ctx.lineCap = 'round';
            ctx.globalAlpha = Math.min(1, progress * 2);
            const x = selection.x - pad;
            const y = selection.y - pad;
            const w = selection.width + pad * 2;
            const h = selection.height + pad * 2;
            // TL
            ctx.beginPath(); ctx.moveTo(x, y + cornerLen); ctx.lineTo(x, y); ctx.lineTo(x + cornerLen, y); ctx.stroke();
            // TR
            ctx.beginPath(); ctx.moveTo(x + w - cornerLen, y); ctx.lineTo(x + w, y); ctx.lineTo(x + w, y + cornerLen); ctx.stroke();
            // BR
            ctx.beginPath(); ctx.moveTo(x + w, y + h - cornerLen); ctx.lineTo(x + w, y + h); ctx.lineTo(x + w - cornerLen, y + h); ctx.stroke();
            // BL
            ctx.beginPath(); ctx.moveTo(x + cornerLen, y + h); ctx.lineTo(x, y + h); ctx.lineTo(x, y + h - cornerLen); ctx.stroke();
            break;
        }

        case 'flash': {
            const spike = Math.max(0, 1 - (cycle * 3));
            const lingeringBorder = Math.min(1, cycle * 2);
            if (spike > 0) {
                ctx.globalCompositeOperation = 'overlay';
                ctx.fillStyle = 'white';
                ctx.globalAlpha = spike * settings.intensity;
                ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
            }
            ctx.globalCompositeOperation = 'source-over';
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 3;
            ctx.globalAlpha = lingeringBorder * settings.intensity;
            ctx.strokeRect(selection.x - 2, selection.y - 2, selection.width + 4, selection.height + 4);
            break;
        }

        case 'ripple': {
            const maxRipples = 3;
            const maxDist = 50;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 2;
            for (let i = 0; i < maxRipples; i++) {
                const offset = i * 0.5;
                let localTime = cycle - offset;
                if (localTime < 0) continue;
                const rippleProgress = localTime / 2;
                if (rippleProgress > 1) continue;
                const expansion = rippleProgress * maxDist;
                const alpha = 1 - rippleProgress;
                ctx.globalAlpha = alpha * settings.intensity;
                ctx.strokeRect(selection.x - expansion, selection.y - expansion, selection.width + expansion * 2, selection.height + expansion * 2);
            }
            break;
        }

        case 'magnify': {
            let scale = 1.0;
            const enterDuration = 0.3;
            if (cycle < enterDuration) {
                const t = cycle / enterDuration;
                scale = 1 + (Math.sin(t * Math.PI) * 0.1 * settings.intensity);
            } else {
                scale = 1.05 + Math.sin((cycle - enterDuration) * 2) * 0.02 * settings.intensity;
            }
            const w = selection.width * scale;
            const h = selection.height * scale;
            const x = selection.x - (w - selection.width) / 2;
            const y = selection.y - (h - selection.height) / 2;

            ctx.save();
            ctx.shadowColor = 'rgba(0,0,0,0.5)';
            ctx.shadowBlur = 30 * settings.intensity;
            ctx.shadowOffsetY = 15;
            ctx.fillStyle = 'white'; 
            ctx.fillRect(x, y, w, h);
            ctx.drawImage(image, selection.x, selection.y, selection.width, selection.height, x, y, w, h);
            ctx.shadowColor = 'transparent';
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 4;
            ctx.strokeRect(x, y, w, h);
            ctx.restore();
            break;
        }

        case 'rainbow': {
            const hue = (cycle * 200) % 360;
            const color = `hsl(${hue}, 100%, 60%)`;
            ctx.shadowColor = color;
            ctx.shadowBlur = 20 * settings.intensity;
            ctx.strokeStyle = color;
            ctx.lineWidth = 5 * settings.intensity;
            ctx.lineJoin = 'round';
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'glitch': {
            const offsetMax = 10 * settings.intensity;
            const step = Math.floor(cycle * 20);
            const isGlitchy = step % 5 !== 0;
            const rOffsetX = isGlitchy ? (Math.sin(step * 123) * offsetMax) : 0;
            const bOffsetX = isGlitchy ? (Math.cos(step * 321) * offsetMax) : 0;

            ctx.save();
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.8;
            ctx.strokeStyle = '#00FFFF';
            ctx.lineWidth = 3;
            ctx.strokeRect(selection.x + bOffsetX, selection.y, selection.width, selection.height);
            ctx.restore();

            ctx.save();
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.8;
            ctx.strokeStyle = '#FF0000';
            ctx.lineWidth = 3;
            ctx.strokeRect(selection.x + rOffsetX, selection.y, selection.width, selection.height);
            ctx.restore();

            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 2;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }
    }

    ctx.restore();
  });
};

import { AnimationSettings, Layer, Selection } from '../types';

/**
 * Main render function used by both the preview loop and the export recorder.
 */
export const renderFrame = (
  ctx: CanvasRenderingContext2D,
  image: HTMLImageElement,
  layers: Layer[],
  activeLayerId: string | null,
  timestamp: number, // current time in ms
  totalDurationMs: number
) => {
  const { width, height } = ctx.canvas;

  // 1. Draw Base Image
  ctx.clearRect(0, 0, width, height);
  ctx.drawImage(image, 0, 0, width, height);

  if (layers.length === 0) return;

  // 2. Draw Background Dimming & Vignette
  const activeLayer = layers.find(l => l.id === activeLayerId) || layers[layers.length - 1];
  const globalSettings = activeLayer.settings;

  ctx.save();
  ctx.beginPath();
  ctx.rect(0, 0, width, height);

  layers.forEach(layer => {
    ctx.rect(layer.selection.x, layer.selection.y, layer.selection.width, layer.selection.height);
  });

  ctx.clip('evenodd');

  if (globalSettings.backgroundDim > 0) {
    ctx.fillStyle = `rgba(0, 0, 0, ${globalSettings.backgroundDim})`;
    ctx.fillRect(0, 0, width, height);
  }

  if (globalSettings.vignette > 0) {
    const gradient = ctx.createRadialGradient(
      width / 2, height / 2, width * 0.3, 
      width / 2, height / 2, Math.max(width, height) * 0.8 
    );
    gradient.addColorStop(0, 'rgba(0,0,0,0)');
    gradient.addColorStop(1, `rgba(0,0,0,${globalSettings.vignette})`);

    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, width, height);
  }
  ctx.restore();

  // 3. Draw Highlights/Animations
  layers.forEach(layer => {
    const { selection, settings } = layer;
    const delayMs = settings.delay * 1000;
    const activeTime = timestamp - delayMs;

    if (activeTime <= 0) return;

    ctx.save();
    const cycle = (activeTime / 1000) * settings.speed;

    // --- Advanced Text Masking Logic ---
    const isTextAnimation = ['reading', 'marker', 'underline', 'strike', 'squiggle'].includes(settings.type);
    let fullImageData: ImageData | null = null;

    // Only grab image data if strictly necessary to avoid performance hit
    if (isTextAnimation) {
        try {
             // We use the base canvas which has the image drawn on it
             fullImageData = ctx.getImageData(selection.x, selection.y, selection.width, selection.height);
        } catch(e) {
            // CORS or security error - fallback to full rect
        }
    }

    /**
     * Generates a boolean mask for a specific horizontal strip (line) of the selection.
     * This ensures that text on line 1 doesn't cause a highlight on the empty space of line 2.
     */
    const getLineMask = (lineIndex: number, totalLines: number): boolean[] => {
        if (!fullImageData) return new Array(Math.ceil(selection.width)).fill(true);

        const { data, width, height } = fullImageData;
        const lineH = height / totalLines;
        // Scan a slightly narrower strip to avoid ascenders/descenders from other lines interference
        const paddingY = lineH * 0.15; 
        const startY = Math.floor((lineIndex * lineH) + paddingY);
        const endY = Math.floor(((lineIndex + 1) * lineH) - paddingY);
        const mask = new Array(width).fill(false);
        const threshold = 230; // Brightness threshold

        // Safety check
        if (startY >= height || endY <= 0 || startY >= endY) return mask;

        for (let x = 0; x < width; x++) {
            let hasContent = false;
            for (let y = startY; y < endY; y++) {
                const i = (y * width + x) * 4;
                const r = data[i];
                const g = data[i+1];
                const b = data[i+2];
                const a = data[i+3];
                // Check for dark pixels (text)
                const avg = (r + g + b) / 3;
                if (a > 20 && avg < threshold) {
                    hasContent = true;
                    break;
                }
            }
            if (hasContent) mask[x] = true;
        }

        // Dilation: Connect letters (small gaps) but keep words separate (large gaps)
        const dilated = [...mask];
        const gapThreshold = 5; // Pixels
        let currentGap = 0;

        // Forward pass
        for(let x=0; x<width; x++) {
            if (!mask[x]) {
                currentGap++;
            } else {
                if (currentGap > 0 && currentGap < gapThreshold) {
                     for(let k=1; k<=currentGap; k++) dilated[x-k] = true;
                }
                currentGap = 0;
            }
        }
        return dilated;
    };

    switch (settings.type) {
        case 'reading': 
        case 'marker': {
            // These two are very similar: fill the text body.
            // Reading is usually line-by-line animated. Marker might be all at once or similar.
            // We'll use the same logic but maybe 'marker' is faster or cleaner.

            const numLines = Math.max(1, Math.ceil(selection.height / 40));
            const realLineHeight = selection.height / numLines;

            ctx.globalCompositeOperation = 'multiply'; 
            ctx.fillStyle = settings.color;

            const activeProgress = Math.min(1, cycle);
            const totalLinesProgress = activeProgress * numLines;

            for (let i = 0; i < numLines; i++) {
                const lineProgress = Math.max(0, Math.min(1, totalLinesProgress - i));

                if (lineProgress > 0) {
                    ctx.globalAlpha = 0.6 * settings.intensity;
                    const w = selection.width * lineProgress;
                    const yPos = selection.y + (i * realLineHeight);

                    // Generate mask specifically for THIS line
                    const mask = getLineMask(i, numLines);

                    for (let x = 0; x < w; x++) {
                        if (mask[Math.floor(x)]) {
                             // Draw a vertical slice for this X
                             ctx.fillRect(selection.x + x, yPos, 1, realLineHeight);
                        }
                    }
                }
            }
            break;
        }

        case 'underline': {
            const numLines = Math.max(1, Math.ceil(selection.height / 40));
            const realLineHeight = selection.height / numLines;

            ctx.lineWidth = 3 * settings.intensity;
            ctx.lineCap = 'round';
            ctx.strokeStyle = settings.color;
            ctx.globalAlpha = 0.9;

            const activeProgress = Math.min(1, cycle);
            const totalLinesProgress = activeProgress * numLines;

            for (let i = 0; i < numLines; i++) {
                const lineProgress = Math.max(0, Math.min(1, totalLinesProgress - i));
                if (lineProgress > 0) {
                     const lineY = selection.y + ((i + 1) * realLineHeight) - 4;
                     const drawWidth = selection.width * lineProgress;
                     const mask = getLineMask(i, numLines);

                     ctx.beginPath();
                     let isDrawing = false;
                     for(let x = 0; x < drawWidth; x++) {
                        if (mask[Math.floor(x)]) {
                             if (!isDrawing) { ctx.moveTo(selection.x + x, lineY); isDrawing = true; }
                             ctx.lineTo(selection.x + x, lineY);
                        } else {
                             isDrawing = false;
                        }
                     }
                     ctx.stroke();
                }
            }
            break;
        }

        case 'strike': {
            const numLines = Math.max(1, Math.ceil(selection.height / 40));
            const realLineHeight = selection.height / numLines;

            ctx.lineWidth = 3 * settings.intensity;
            ctx.lineCap = 'round';
            ctx.strokeStyle = settings.color;
            ctx.globalAlpha = 0.8;

            const activeProgress = Math.min(1, cycle);
            const totalLinesProgress = activeProgress * numLines;

            for (let i = 0; i < numLines; i++) {
                const lineProgress = Math.max(0, Math.min(1, totalLinesProgress - i));
                if (lineProgress > 0) {
                     const lineY = selection.y + (i * realLineHeight) + (realLineHeight / 2);
                     const drawWidth = selection.width * lineProgress;
                     const mask = getLineMask(i, numLines);

                     ctx.beginPath();
                     let isDrawing = false;
                     for(let x = 0; x < drawWidth; x++) {
                         if (mask[Math.floor(x)]) {
                             if (!isDrawing) { ctx.moveTo(selection.x + x, lineY); isDrawing = true; }
                             ctx.lineTo(selection.x + x, lineY);
                         } else {
                             isDrawing = false;
                         }
                     }
                     ctx.stroke();
                }
            }
            break;
        }

        case 'squiggle': {
            const numLines = Math.max(1, Math.ceil(selection.height / 40));
            const realLineHeight = selection.height / numLines;

            ctx.lineWidth = 2 * settings.intensity;
            ctx.lineCap = 'round';
            ctx.strokeStyle = settings.color;
            ctx.globalAlpha = 0.9;

            const activeProgress = Math.min(1, cycle);
            const totalLinesProgress = activeProgress * numLines;

            const freq = 0.3;
            const amp = 3;

            for (let i = 0; i < numLines; i++) {
                const lineProgress = Math.max(0, Math.min(1, totalLinesProgress - i));
                if (lineProgress > 0) {
                     const baseY = selection.y + ((i + 1) * realLineHeight) - 4;
                     const drawWidth = selection.width * lineProgress;
                     const mask = getLineMask(i, numLines);

                     ctx.beginPath();
                     let isDrawing = false;

                     for(let x = 0; x < drawWidth; x++) {
                        const waveY = baseY + Math.sin(x * freq) * amp;
                        if (mask[Math.floor(x)]) {
                            if (!isDrawing) {
                                ctx.moveTo(selection.x + x, waveY);
                                isDrawing = true;
                            } else {
                                ctx.lineTo(selection.x + x, waveY);
                            }
                        } else {
                            isDrawing = false;
                        }
                     }
                     ctx.stroke();
                }
            }
            break;
        }

        // --- Standard Animations (Geometric / Overlay) ---

        case 'rectangle': {
            const p = (selection.width + selection.height) * 2;
            const progress = Math.min(1, cycle); 
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 4 * settings.intensity;
            ctx.lineJoin = 'miter';
            ctx.setLineDash([p, p]);
            ctx.lineDashOffset = p * (1 - progress); 
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'pulse': {
            const alpha = 0.1 + (Math.sin(cycle * Math.PI) + 1) / 2 * (settings.intensity - 0.1);
            ctx.globalCompositeOperation = 'overlay';
            ctx.fillStyle = settings.color;
            ctx.globalAlpha = alpha;
            ctx.fillRect(selection.x, selection.y, selection.width, selection.height);

            ctx.globalCompositeOperation = 'source-over';
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 4;
            ctx.globalAlpha = alpha;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'sweep': {
            ctx.beginPath();
            ctx.rect(selection.x, selection.y, selection.width, selection.height);
            ctx.clip();
            const gradientWidth = selection.width * 0.5;
            const totalDist = selection.width + gradientWidth * 2;
            const progress = cycle; 
            const xPos = selection.x - gradientWidth + (progress * totalDist);
            const grad = ctx.createLinearGradient(xPos, selection.y, xPos + gradientWidth, selection.y);
            grad.addColorStop(0, 'rgba(255,255,255,0)');
            grad.addColorStop(0.5, settings.color);
            grad.addColorStop(1, 'rgba(255,255,255,0)');
            ctx.fillStyle = grad;
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = settings.intensity;
            ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'neon': {
            const pulseIntensity = 0.8 + (Math.sin(cycle * Math.PI * 2) * 0.2);
            ctx.globalAlpha = pulseIntensity * settings.intensity;
            ctx.shadowBlur = 20;
            ctx.shadowColor = settings.color;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 4;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            ctx.shadowBlur = 0;
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 1;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'fade': {
            const progress = Math.min(1, cycle);
            ctx.globalAlpha = progress * settings.intensity;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 3;
            ctx.setLineDash([10, 6]);
            ctx.strokeRect(selection.x - 4, selection.y - 4, selection.width + 8, selection.height + 8);
            ctx.fillStyle = settings.color;
            ctx.globalAlpha = progress * 0.1 * settings.intensity;
            ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'focus': {
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = settings.intensity;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'circle': {
            const progress = Math.min(1, cycle * 1.5);
            const cx = selection.x + selection.width / 2;
            const cy = selection.y + selection.height / 2;
            const rx = selection.width / 2 + 10;
            const ry = selection.height / 2 + 10;
            ctx.beginPath();
            ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2);
            const len = 2 * Math.PI * Math.sqrt((rx*rx + ry*ry)/2) + 100;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 4 * settings.intensity;
            ctx.lineCap = 'round';
            ctx.setLineDash([len, len]);
            ctx.lineDashOffset = len - (progress * len);
            ctx.stroke();
            break;
        }

        case 'brackets': {
            const progress = Math.min(1, cycle);
            const pad = 10;
            const cornerLen = Math.min(selection.width, selection.height) * 0.3 * progress;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 5 * settings.intensity;
            ctx.lineCap = 'round';
            ctx.globalAlpha = Math.min(1, progress * 2);
            const x = selection.x - pad;
            const y = selection.y - pad;
            const w = selection.width + pad * 2;
            const h = selection.height + pad * 2;
            // TL
            ctx.beginPath(); ctx.moveTo(x, y + cornerLen); ctx.lineTo(x, y); ctx.lineTo(x + cornerLen, y); ctx.stroke();
            // TR
            ctx.beginPath(); ctx.moveTo(x + w - cornerLen, y); ctx.lineTo(x + w, y); ctx.lineTo(x + w, y + cornerLen); ctx.stroke();
            // BR
            ctx.beginPath(); ctx.moveTo(x + w, y + h - cornerLen); ctx.lineTo(x + w, y + h); ctx.lineTo(x + w - cornerLen, y + h); ctx.stroke();
            // BL
            ctx.beginPath(); ctx.moveTo(x + cornerLen, y + h); ctx.lineTo(x, y + h); ctx.lineTo(x, y + h - cornerLen); ctx.stroke();
            break;
        }

        case 'flash': {
            const spike = Math.max(0, 1 - (cycle * 3));
            const lingeringBorder = Math.min(1, cycle * 2);
            if (spike > 0) {
                ctx.globalCompositeOperation = 'overlay';
                ctx.fillStyle = 'white';
                ctx.globalAlpha = spike * settings.intensity;
                ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
            }
            ctx.globalCompositeOperation = 'source-over';
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 3;
            ctx.globalAlpha = lingeringBorder * settings.intensity;
            ctx.strokeRect(selection.x - 2, selection.y - 2, selection.width + 4, selection.height + 4);
            break;
        }

        case 'ripple': {
            const maxRipples = 3;
            const maxDist = 50;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 2;
            for (let i = 0; i < maxRipples; i++) {
                const offset = i * 0.5;
                let localTime = cycle - offset;
                if (localTime < 0) continue;
                const rippleProgress = localTime / 2;
                if (rippleProgress > 1) continue;
                const expansion = rippleProgress * maxDist;
                const alpha = 1 - rippleProgress;
                ctx.globalAlpha = alpha * settings.intensity;
                ctx.strokeRect(selection.x - expansion, selection.y - expansion, selection.width + expansion * 2, selection.height + expansion * 2);
            }
            break;
        }

        case 'magnify': {
            let scale = 1.0;
            const enterDuration = 0.3;
            if (cycle < enterDuration) {
                const t = cycle / enterDuration;
                scale = 1 + (Math.sin(t * Math.PI) * 0.1 * settings.intensity);
            } else {
                scale = 1.05 + Math.sin((cycle - enterDuration) * 2) * 0.02 * settings.intensity;
            }
            const w = selection.width * scale;
            const h = selection.height * scale;
            const x = selection.x - (w - selection.width) / 2;
            const y = selection.y - (h - selection.height) / 2;

            ctx.save();
            ctx.shadowColor = 'rgba(0,0,0,0.5)';
            ctx.shadowBlur = 30 * settings.intensity;
            ctx.shadowOffsetY = 15;
            ctx.fillStyle = 'white'; 
            ctx.fillRect(x, y, w, h);
            ctx.drawImage(image, selection.x, selection.y, selection.width, selection.height, x, y, w, h);
            ctx.shadowColor = 'transparent';
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 4;
            ctx.strokeRect(x, y, w, h);
            ctx.restore();
            break;
        }

        case 'rainbow': {
            const hue = (cycle * 200) % 360;
            const color = `hsl(${hue}, 100%, 60%)`;
            ctx.shadowColor = color;
            ctx.shadowBlur = 20 * settings.intensity;
            ctx.strokeStyle = color;
            ctx.lineWidth = 5 * settings.intensity;
            ctx.lineJoin = 'round';
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'glitch': {
            const offsetMax = 10 * settings.intensity;
            const step = Math.floor(cycle * 20);
            const isGlitchy = step % 5 !== 0;
            const rOffsetX = isGlitchy ? (Math.sin(step * 123) * offsetMax) : 0;
            const bOffsetX = isGlitchy ? (Math.cos(step * 321) * offsetMax) : 0;

            ctx.save();
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.8;
            ctx.strokeStyle = '#00FFFF';
            ctx.lineWidth = 3;
            ctx.strokeRect(selection.x + bOffsetX, selection.y, selection.width, selection.height);
            ctx.restore();

            ctx.save();
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.8;
            ctx.strokeStyle = '#FF0000';
            ctx.lineWidth = 3;
            ctx.strokeRect(selection.x + rOffsetX, selection.y, selection.width, selection.height);
            ctx.restore();

            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 2;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }
    }

    ctx.restore();
  });
};

import { AnimationSettings, Layer, Selection } from '../types';

/**
 * Main render function used by both the preview loop and the export recorder.
 */
export const renderFrame = (
  ctx: CanvasRenderingContext2D,
  image: HTMLImageElement,
  layers: Layer[],
  activeLayerId: string | null,
  timestamp: number, // current time in ms
  totalDurationMs: number
) => {
  const { width, height } = ctx.canvas;

  // 1. Draw Base Image
  ctx.clearRect(0, 0, width, height);
  ctx.drawImage(image, 0, 0, width, height);

  if (layers.length === 0) return;

  // 2. Draw Background Dimming & Vignette
  const activeLayer = layers.find(l => l.id === activeLayerId) || layers[layers.length - 1];
  const globalSettings = activeLayer.settings;

  ctx.save();
  ctx.beginPath();
  ctx.rect(0, 0, width, height);

  layers.forEach(layer => {
    ctx.rect(layer.selection.x, layer.selection.y, layer.selection.width, layer.selection.height);
  });

  ctx.clip('evenodd');

  if (globalSettings.backgroundDim > 0) {
    ctx.fillStyle = `rgba(0, 0, 0, ${globalSettings.backgroundDim})`;
    ctx.fillRect(0, 0, width, height);
  }

  if (globalSettings.vignette > 0) {
    const gradient = ctx.createRadialGradient(
      width / 2, height / 2, width * 0.3, 
      width / 2, height / 2, Math.max(width, height) * 0.8 
    );
    gradient.addColorStop(0, 'rgba(0,0,0,0)');
    gradient.addColorStop(1, `rgba(0,0,0,${globalSettings.vignette})`);

    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, width, height);
  }
  ctx.restore();

  // 3. Draw Highlights/Animations
  layers.forEach(layer => {
    const { selection, settings } = layer;
    const delayMs = settings.delay * 1000;
    const activeTime = timestamp - delayMs;

    if (activeTime <= 0) return;

    ctx.save();
    const cycle = (activeTime / 1000) * settings.speed;

    // --- Advanced Text Bounds Logic ---
    const isTextAnimation = ['reading', 'marker', 'underline', 'strike', 'squiggle'].includes(settings.type);
    let fullImageData: ImageData | null = null;

    if (isTextAnimation) {
        try {
             fullImageData = ctx.getImageData(selection.x, selection.y, selection.width, selection.height);
        } catch(e) {
            // Fallback for CORS
        }
    }

    /**
     * Scans a specific line index to find the Min X and Max X where content exists.
     * This creates a tight bounding box around the text on that line.
     */
    const getLineBounds = (lineIndex: number, totalLines: number) => {
        if (!fullImageData) return { start: 0, width: selection.width };

        const { data, width, height } = fullImageData;
        const lineH = height / totalLines;

        // Skip top/bottom 15% of the line to avoid noise/ascenders from other lines
        const paddingY = Math.floor(lineH * 0.15); 
        const startY = Math.floor((lineIndex * lineH) + paddingY);
        const endY = Math.floor(((lineIndex + 1) * lineH) - paddingY);

        // Safety
        if (startY >= height || endY <= 0 || startY >= endY) return null;

        const threshold = 230; // Brightness threshold
        let minX = -1;
        let maxX = -1;

        // Scan for Start X (Left to Right)
        for (let x = 0; x < width; x++) {
             for (let y = startY; y < endY; y++) {
                 const i = (y * width + x) * 4;
                 const avg = (data[i] + data[i+1] + data[i+2]) / 3;
                 if (data[i+3] > 20 && avg < threshold) {
                     minX = x;
                     break;
                 }
             }
             if (minX !== -1) break;
        }

        // Empty line?
        if (minX === -1) return null;

        // Scan for End X (Right to Left)
        for (let x = width - 1; x >= minX; x--) {
            for (let y = startY; y < endY; y++) {
                const i = (y * width + x) * 4;
                const avg = (data[i] + data[i+1] + data[i+2]) / 3;
                if (data[i+3] > 20 && avg < threshold) {
                    maxX = x;
                    break;
                }
            }
            if (maxX !== -1) break;
        }

        // Add small padding for aesthetics
        const paddingX = 2;
        const finalX = Math.max(0, minX - paddingX);
        const finalW = Math.min(width, maxX + paddingX) - finalX + paddingX; // Extra padding on right

        return { start: finalX, width: finalW };
    };

    switch (settings.type) {
        case 'reading': 
        case 'marker': {
            const numLines = Math.max(1, Math.ceil(selection.height / 40));
            const realLineHeight = selection.height / numLines;

            ctx.globalCompositeOperation = 'multiply'; 
            ctx.fillStyle = settings.color;

            const activeProgress = Math.min(1, cycle);
            const totalLinesProgress = activeProgress * numLines;

            for (let i = 0; i < numLines; i++) {
                const lineProgress = Math.max(0, Math.min(1, totalLinesProgress - i));

                if (lineProgress > 0) {
                    const bounds = getLineBounds(i, numLines);

                    if (bounds) {
                        ctx.globalAlpha = 0.6 * settings.intensity;

                        // Animate the width from 0 to bounds.width
                        // However, we want it to start at bounds.start!
                        const currentWidth = bounds.width * lineProgress;

                        const xPos = selection.x + bounds.start;
                        const yPos = selection.y + (i * realLineHeight);

                        ctx.fillRect(xPos, yPos, currentWidth, realLineHeight);
                    }
                }
            }
            break;
        }

        case 'underline': {
            const numLines = Math.max(1, Math.ceil(selection.height / 40));
            const realLineHeight = selection.height / numLines;

            ctx.lineWidth = 3 * settings.intensity;
            ctx.lineCap = 'butt'; // Cleaner edges
            ctx.strokeStyle = settings.color;
            ctx.globalAlpha = 0.9;

            const activeProgress = Math.min(1, cycle);
            const totalLinesProgress = activeProgress * numLines;

            for (let i = 0; i < numLines; i++) {
                const lineProgress = Math.max(0, Math.min(1, totalLinesProgress - i));
                if (lineProgress > 0) {
                     const bounds = getLineBounds(i, numLines);
                     if (bounds) {
                        const lineY = selection.y + ((i + 1) * realLineHeight) - 4;
                        const startX = selection.x + bounds.start;
                        const targetWidth = bounds.width * lineProgress;

                        ctx.beginPath();
                        ctx.moveTo(startX, lineY);
                        ctx.lineTo(startX + targetWidth, lineY);
                        ctx.stroke();
                     }
                }
            }
            break;
        }

        case 'strike': {
            const numLines = Math.max(1, Math.ceil(selection.height / 40));
            const realLineHeight = selection.height / numLines;

            ctx.lineWidth = 3 * settings.intensity;
            ctx.lineCap = 'butt';
            ctx.strokeStyle = settings.color;
            ctx.globalAlpha = 0.8;

            const activeProgress = Math.min(1, cycle);
            const totalLinesProgress = activeProgress * numLines;

            for (let i = 0; i < numLines; i++) {
                const lineProgress = Math.max(0, Math.min(1, totalLinesProgress - i));
                if (lineProgress > 0) {
                     const bounds = getLineBounds(i, numLines);
                     if (bounds) {
                        const lineY = selection.y + (i * realLineHeight) + (realLineHeight / 2);
                        const startX = selection.x + bounds.start;
                        const targetWidth = bounds.width * lineProgress;

                        ctx.beginPath();
                        ctx.moveTo(startX, lineY);
                        ctx.lineTo(startX + targetWidth, lineY);
                        ctx.stroke();
                     }
                }
            }
            break;
        }

        case 'squiggle': {
            const numLines = Math.max(1, Math.ceil(selection.height / 40));
            const realLineHeight = selection.height / numLines;

            ctx.lineWidth = 2 * settings.intensity;
            ctx.lineCap = 'round';
            ctx.strokeStyle = settings.color;
            ctx.globalAlpha = 0.9;

            const activeProgress = Math.min(1, cycle);
            const totalLinesProgress = activeProgress * numLines;

            const freq = 0.3;
            const amp = 3;

            for (let i = 0; i < numLines; i++) {
                const lineProgress = Math.max(0, Math.min(1, totalLinesProgress - i));
                if (lineProgress > 0) {
                     const bounds = getLineBounds(i, numLines);
                     if (bounds) {
                         const baseY = selection.y + ((i + 1) * realLineHeight) - 4;
                         const startX = selection.x + bounds.start;
                         const targetWidth = bounds.width * lineProgress;

                         ctx.beginPath();
                         let isDrawing = false;

                         // Draw sine wave
                         for(let localX = 0; localX < targetWidth; localX++) {
                            const waveY = baseY + Math.sin((localX + startX) * freq) * amp;
                            if (!isDrawing) {
                                ctx.moveTo(startX + localX, waveY);
                                isDrawing = true;
                            } else {
                                ctx.lineTo(startX + localX, waveY);
                            }
                         }
                         ctx.stroke();
                     }
                }
            }
            break;
        }

        // --- Standard Animations (Geometric / Overlay) ---

        case 'rectangle': {
            const p = (selection.width + selection.height) * 2;
            const progress = Math.min(1, cycle); 
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 4 * settings.intensity;
            ctx.lineJoin = 'miter';
            ctx.setLineDash([p, p]);
            ctx.lineDashOffset = p * (1 - progress); 
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'pulse': {
            const alpha = 0.1 + (Math.sin(cycle * Math.PI) + 1) / 2 * (settings.intensity - 0.1);
            ctx.globalCompositeOperation = 'overlay';
            ctx.fillStyle = settings.color;
            ctx.globalAlpha = alpha;
            ctx.fillRect(selection.x, selection.y, selection.width, selection.height);

            ctx.globalCompositeOperation = 'source-over';
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 4;
            ctx.globalAlpha = alpha;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'sweep': {
            ctx.beginPath();
            ctx.rect(selection.x, selection.y, selection.width, selection.height);
            ctx.clip();
            const gradientWidth = selection.width * 0.5;
            const totalDist = selection.width + gradientWidth * 2;
            const progress = cycle; 
            const xPos = selection.x - gradientWidth + (progress * totalDist);
            const grad = ctx.createLinearGradient(xPos, selection.y, xPos + gradientWidth, selection.y);
            grad.addColorStop(0, 'rgba(255,255,255,0)');
            grad.addColorStop(0.5, settings.color);
            grad.addColorStop(1, 'rgba(255,255,255,0)');
            ctx.fillStyle = grad;
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = settings.intensity;
            ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'neon': {
            const pulseIntensity = 0.8 + (Math.sin(cycle * Math.PI * 2) * 0.2);
            ctx.globalAlpha = pulseIntensity * settings.intensity;
            ctx.shadowBlur = 20;
            ctx.shadowColor = settings.color;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 4;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            ctx.shadowBlur = 0;
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 1;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'fade': {
            const progress = Math.min(1, cycle);
            ctx.globalAlpha = progress * settings.intensity;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 3;
            ctx.setLineDash([10, 6]);
            ctx.strokeRect(selection.x - 4, selection.y - 4, selection.width + 8, selection.height + 8);
            ctx.fillStyle = settings.color;
            ctx.globalAlpha = progress * 0.1 * settings.intensity;
            ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'focus': {
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = settings.intensity;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'circle': {
            const progress = Math.min(1, cycle * 1.5);
            const cx = selection.x + selection.width / 2;
            const cy = selection.y + selection.height / 2;
            const rx = selection.width / 2 + 10;
            const ry = selection.height / 2 + 10;
            ctx.beginPath();
            ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2);
            const len = 2 * Math.PI * Math.sqrt((rx*rx + ry*ry)/2) + 100;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 4 * settings.intensity;
            ctx.lineCap = 'round';
            ctx.setLineDash([len, len]);
            ctx.lineDashOffset = len - (progress * len);
            ctx.stroke();
            break;
        }

        case 'brackets': {
            const progress = Math.min(1, cycle);
            const pad = 10;
            const cornerLen = Math.min(selection.width, selection.height) * 0.3 * progress;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 5 * settings.intensity;
            ctx.lineCap = 'round';
            ctx.globalAlpha = Math.min(1, progress * 2);
            const x = selection.x - pad;
            const y = selection.y - pad;
            const w = selection.width + pad * 2;
            const h = selection.height + pad * 2;
            // TL
            ctx.beginPath(); ctx.moveTo(x, y + cornerLen); ctx.lineTo(x, y); ctx.lineTo(x + cornerLen, y); ctx.stroke();
            // TR
            ctx.beginPath(); ctx.moveTo(x + w - cornerLen, y); ctx.lineTo(x + w, y); ctx.lineTo(x + w, y + cornerLen); ctx.stroke();
            // BR
            ctx.beginPath(); ctx.moveTo(x + w, y + h - cornerLen); ctx.lineTo(x + w, y + h); ctx.lineTo(x + w - cornerLen, y + h); ctx.stroke();
            // BL
            ctx.beginPath(); ctx.moveTo(x + cornerLen, y + h); ctx.lineTo(x, y + h); ctx.lineTo(x, y + h - cornerLen); ctx.stroke();
            break;
        }

        case 'flash': {
            const spike = Math.max(0, 1 - (cycle * 3));
            const lingeringBorder = Math.min(1, cycle * 2);
            if (spike > 0) {
                ctx.globalCompositeOperation = 'overlay';
                ctx.fillStyle = 'white';
                ctx.globalAlpha = spike * settings.intensity;
                ctx.fillRect(selection.x, selection.y, selection.width, selection.height);
            }
            ctx.globalCompositeOperation = 'source-over';
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 3;
            ctx.globalAlpha = lingeringBorder * settings.intensity;
            ctx.strokeRect(selection.x - 2, selection.y - 2, selection.width + 4, selection.height + 4);
            break;
        }

        case 'ripple': {
            const maxRipples = 3;
            const maxDist = 50;
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 2;
            for (let i = 0; i < maxRipples; i++) {
                const offset = i * 0.5;
                let localTime = cycle - offset;
                if (localTime < 0) continue;
                const rippleProgress = localTime / 2;
                if (rippleProgress > 1) continue;
                const expansion = rippleProgress * maxDist;
                const alpha = 1 - rippleProgress;
                ctx.globalAlpha = alpha * settings.intensity;
                ctx.strokeRect(selection.x - expansion, selection.y - expansion, selection.width + expansion * 2, selection.height + expansion * 2);
            }
            break;
        }

        case 'magnify': {
            let scale = 1.0;
            const enterDuration = 0.3;
            if (cycle < enterDuration) {
                const t = cycle / enterDuration;
                scale = 1 + (Math.sin(t * Math.PI) * 0.1 * settings.intensity);
            } else {
                scale = 1.05 + Math.sin((cycle - enterDuration) * 2) * 0.02 * settings.intensity;
            }
            const w = selection.width * scale;
            const h = selection.height * scale;
            const x = selection.x - (w - selection.width) / 2;
            const y = selection.y - (h - selection.height) / 2;

            ctx.save();
            ctx.shadowColor = 'rgba(0,0,0,0.5)';
            ctx.shadowBlur = 30 * settings.intensity;
            ctx.shadowOffsetY = 15;
            ctx.fillStyle = 'white'; 
            ctx.fillRect(x, y, w, h);
            ctx.drawImage(image, selection.x, selection.y, selection.width, selection.height, x, y, w, h);
            ctx.shadowColor = 'transparent';
            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 4;
            ctx.strokeRect(x, y, w, h);
            ctx.restore();
            break;
        }

        case 'rainbow': {
            const hue = (cycle * 200) % 360;
            const color = `hsl(${hue}, 100%, 60%)`;
            ctx.shadowColor = color;
            ctx.shadowBlur = 20 * settings.intensity;
            ctx.strokeStyle = color;
            ctx.lineWidth = 5 * settings.intensity;
            ctx.lineJoin = 'round';
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }

        case 'glitch': {
            const offsetMax = 10 * settings.intensity;
            const step = Math.floor(cycle * 20);
            const isGlitchy = step % 5 !== 0;
            const rOffsetX = isGlitchy ? (Math.sin(step * 123) * offsetMax) : 0;
            const bOffsetX = isGlitchy ? (Math.cos(step * 321) * offsetMax) : 0;

            ctx.save();
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.8;
            ctx.strokeStyle = '#00FFFF';
            ctx.lineWidth = 3;
            ctx.strokeRect(selection.x + bOffsetX, selection.y, selection.width, selection.height);
            ctx.restore();

            ctx.save();
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.8;
            ctx.strokeStyle = '#FF0000';
            ctx.lineWidth = 3;
            ctx.strokeRect(selection.x + rOffsetX, selection.y, selection.width, selection.height);
            ctx.restore();

            ctx.strokeStyle = settings.color;
            ctx.lineWidth = 2;
            ctx.strokeRect(selection.x, selection.y, selection.width, selection.height);
            break;
        }
    }

    ctx.restore();
  });
};

